window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["35010191"]={"book":{"id":35010191,"title":"故事力","author":"高琳/[美]林宏博","translator":"","publisher":"中信出版社","pubdate":"2020-4","isbn":"9787521708882","tags":["沟通","讲故事","职场","个人成长","写作","；沟通；高情商","高情商","教练"],"memCount":null},"np":1,"pb":[24],"idx":[{"i":19830,"t":"有共鸣的故事才能赢得人心","l":"TF2-4","c":"谢尚袁","g":1,"p":1},{"i":19579,"t":"掌握邀功三步法，让你的辛苦被看见","l":"TF2-3","c":"kkk-cq","g":1,"p":1},{"i":19541,"t":"不冲突无价值-—用冲突显现你的价值观","l":"TF2-3","c":"谢尚袁","g":1,"p":1},{"i":19540,"t":"成人达已的卖自己","l":"TF2-2","c":"谢尚袁","g":1,"p":1},{"i":19539,"t":"故事力","l":"TF2-1","c":"谢尚袁","g":1,"p":1},{"i":18532,"t":"邀功三步法","l":"TF2-3","c":"kkk-cq","g":1,"p":1},{"i":18349,"t":"塑造故事三步法","l":"TF2-2","c":"kkk-cq","g":1,"p":1},{"i":17959,"t":"如何讲动力故事？","l":"TF1-2","c":"醉人书香","g":1,"p":1},{"i":17857,"t":"故事力：从感动到行动","l":"TF3-2","c":"喜春","g":1,"p":1},{"i":17759,"t":"故事介绍法","l":"TF3-1","c":"喜春","g":1,"p":1},{"i":17608,"t":"讲好故事，助你升职加薪","l":"TF2-4","c":"喜春","g":1,"p":1},{"i":16173,"t":"学会讲故事，走心又动人","l":"TF3-3","c":"美君grace","g":1,"p":1},{"i":15867,"t":"激发共鸣，提升社交力","l":"TF3-2","c":"美君grace","g":1,"p":1},{"i":15803,"t":"2-3@英雄之旅＆2-4@神奇的PDCA循环法@无锡太湖分舵第236期","l":"TF2-3","c":"彼岸2022","g":1,"p":1},{"i":15799,"t":"什么样的故事才会影响他人","l":"TF2-4","c":"大雪","g":1,"p":1},{"i":15750,"t":"用故事述说人生，用故事影响他人","l":"TF3-1","c":"美君grace","g":1,"p":1},{"i":15660,"t":"用故事讲出你的价值观","l":"TF2-3","c":"程林","g":1,"p":1},{"i":14875,"t":"一学就会，一会就可以用的故事架构","l":"TF3-1","c":"万敏","g":1,"p":1},{"i":14758,"t":"如何提高自己的同理心","l":"TF1-2","c":"可睿","g":1,"p":1},{"i":14455,"t":"因为-但是-所以故事模式","l":"TF2-3","c":"三金","g":1,"p":1},{"i":14437,"t":"向上管理","l":"TF1-1","c":"万敏","g":1,"p":1},{"i":12566,"t":"用STAR模型，打动面试官","l":"TF2-2","c":"张蕾Emma","g":1,"p":1},{"i":11466,"t":"好的开头是成功的一半","l":"TF1-2","c":"徐丹丹","g":1,"p":1},{"i":10820,"t":"提高对情绪颗粒度的感知","l":"TF1-2","c":"岳兴彦","g":1,"p":1}],"ms":[{"id":19830,"topic":"有共鸣的故事才能赢得人心","learn_goal":"","remark":"故事力","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"谢尚袁","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>【自我介绍+分组】2分钟\u003cbr>各位老师、各位同学，大家好！我是尚袁，广结善缘\u003cbr>今天用两个标签，让大家快速认识我。\u003cbr>第一个标签，我是一名广告创业者，专注文化墙设计与物料制作，至今19年有余。到了中年上有老下有小的年纪，我深刻领悟到：我们既要敢创业，更要会守业；而能守住事业根基的，从来不是金钱，而是健康。\u003cbr>21 年我开始学习中医，用小儿推拿、刮痧、艾灸等方法，帮孩子调理好了鼻炎、日常感冒发烧咳嗽等问题，也为父母调理好了颈肩腰腿疼痛、结节、四高等问题，正因为这份收获，中医养生成了我人生的第二个标签。\u003cbr>广告设计和中医养生两个并不交集的领域，一个给我生活的底气，一个给我生命的底气，两者恰好平衡了我生命的重量和质量，一手抓工作，一手抓健康。\u003cbr>今天是我的 2-4 拆书晋级，全程预计 50 到 60 分钟。\u003cbr>为了方便大家后续讨论，我们进行一下分组，两边为一组结成2组学习小组，我们一起交流！\u003cbr>【FAB法介绍图书】\u003cbr>【F：特点，核心是“书”用于满足好奇心】作者是谁，什么职业，成果是什么？\u003cbr>我拆解的是《故事力》这本书，作者高琳是一位留美理科博士，拥有多年世界 500 强企业管理与咨询实战经验。她擅长分析数据与逻辑思考，结合职场经验总结出一套用故事提升沟通和影响力的方法，写成《故事力》这本书，本书是在帮助我们普通人学会讲故事、讲好故事，来解决理性沟通中难以解决的问题。\u003cbr>【A：优势，重点是“比较”，用于建立安全感 】\u003cbr>与其他沟通类书籍相比，这本书的核心优势是凝聚了演讲、职场、创业、销售等多个领域的实战经验，提炼出6个可直接套用的故事模型，是一本实用型工具书。书中详细介绍了每个故事模型的应用方法，通俗易懂。\u003cbr>【B1：利益，强调的是你，用于引发兴趣。可能是讲学习者能够解决哪些痛苦，突破哪些障碍，实现什么梦想，获得什么价值】\u003cbr>当下我们恰逢又处在了人工智能的时代，\u003cstrong>讲故事的能力就显得尤为重要\u003c/strong>。如果说论讲道理，摆数据，谁都讲不过 AI；但论讲故事，讲那些独属于我们自己的、亲身经历的故事，ai是无法做到的，因为它有经验却没有经历。这也是我们不被ai所取代的，人类最本能的终极能力。\u003cbr>【B2】：那么问题来了。日常为什么我们平时在沟通的时候，明明是出于好心，却往往越说越累，越说越说不通。甚至有可能你在讲，对方根本不想听也不想和你回应，搞得你不知所措。原因就在于我们陷入了讲道理中，讲的都是我们自己想讲的道理，而非对方想听的情理，如何讲出对方想听的话，这就要用到故事的思维和方法。\u003cbr>【学习总目标和片段关系】2分钟\u003cbr>今天拆书的总目标解决两个问题：第一个折页是教大家讲出别人愿意听，沟通快，有互动有共鸣的故事；第二个拆页教大家讲出有灵魂、有价值观的故事，对方不但愿意听还能记得住同时吸引人。这两个片段，是递进关系。\u003c/p>\u003cp>\u003cbr>【片段1学习目标】\u003cbr>好，现在我们正式进入第一个片段的学习。本次学习目标：跟随我完成本次RIA现场学习后，学习者能够回到过往沟通失败的场景中，【运用】\u003cstrong>共鸣三步法，重新设计一套能与对方建立共情的沟通文案。\u003c/strong>\u003cbr>接下来，请大家用 2 分钟时间阅读手中的片段 1，读完后举手示意。\u003c/p>","ratings_count":3,"texts":[{"id":24263,"quote":"\u003cp>R原文片段：\u003cbr>《故事力》共鸣的3个层次\u003cbr>共鸣从哪儿来的？共鸣的3个层次\u003cbr>那么共鸣是从哪儿来的呢？很简单，共鸣来自“共”。通常来讲，共鸣有3个层次，我们可以跟他人实现一些浅层次的共鸣，也可以实现一些更深层次的共鸣。\u003cbr>第一层，最简单的共鸣来源于共同的经历、背景、目标，所谓有共同语言说的就是这个。比如我们都有相似的留学背景，或者同样都是“北漂”，抑或像我一样都因为想工作忘了孩子。这些经历都在我们的生活中留下了烙印，因此当我们讲到类似的故事时，就会引发共鸣。\u003cbr>第二层，更高级一点的共鸣来自共同的感受。比如，喜悦、愤怒、难过、痛苦。说到这儿，我想问问你，你觉得是讲自己成功的故事还是讲自己失败的故事更能引起共鸣呢？答案是“失败的故事”。因为每个人对成功的定义不一样，你讲的成功别人未必都能感同身受。你跟我讲你爬上珠穆朗玛峰的兴奋，然而对我这种最高只爬过香山的人来讲，是很难想象那有多兴奋的。但\u003cu>\u003cem>失败大家都有过，大家都知道沮丧的感觉，懊悔的感觉，所以如果你跟我讲你爬珠穆朗玛峰的时候遇到天气不好，差点无法登顶时那种失望沮丧的感觉，我就很容易有共鸣，因为我也体会过特别期待的一件事情却以毫厘之差没有达成的失落。\u003c/em>\u003c/u>\u003cbr>第三层，最高级的共鸣来自价值观层面的共鸣。价值观听起来像是个大词，但千万别被它吓住，其实没那么神秘，它指的是什么对你来讲很重要。比如，爱、坚持、努力、目标导向等。价值观看似很虚，它却左右着我们每个人每一天的每一个选择。\u003cbr>当你被别人的故事触动，或者对一个故事印象深刻的时候，往往是因为它与你最底层的价值观产生了共鸣。比如“泰坦尼克号”里的杰克和罗丝的绝世爱情之所以动人，就是因为它触动了每个人内心深处的爱与奉献。所以虽然你从来没有过沉船的经历，也可能没有过生离死别的感受，但仍然会因为人类底层价值观的共通性而被深深地触动。\u003cbr>所以，一个好的故事是有灵魂的，这个灵魂就是价值观，当你能在价值观层面跟他人产生共鸣时，那么这种共鸣就是高级的共鸣。\u003c/p>","explains":"\u003cp>拆书家讲解引导：\u003cbr>好的，我看到大部分伙伴已经读完了，还没看完的伙伴也不用着急，接下来就听听我对拆页 1 的理解。\u003cbr>WHAT：\u003cbr>拆页里告诉我们，共鸣的核心，就在于一个「共」字。比如相同的身份，相似的经历、相同的情绪，乃至契合的性格与品质。而要让共鸣更有深度，最终还要落到体现个人价值观的内容上，这也是我们下半场第二个拆页重点拆解的部分。\u003cbr>WHY：\u003cbr>\u003cem>&lt;一般做法&gt;\u003c/em>\u003cbr>很多人在沟通表达时，习惯一上来就讲道理、谈成功、说喜悦。比如有位销售经理给新员工培训，一上台就侃侃而谈：自己专业扎实、话术熟练、沟通能力强，靠着这些赚到人生第一桶金，一步步晋升为今天经理的位置。结果台下员工只是安静聆听，既不交流，也不回应。\u003cbr>\u003cem>&lt;不那么做的坏处&gt;\u003c/em>\u003cbr>这样做的弊端十分明显：他完全忽略了，新人当下并没有类似的成功经历，很难对他的付出与成果产生共鸣，也无法真正体会他的喜悦与自信，甚至还会让新人陷入自我怀疑，觉得这些事自己目前根本做不到。这位销售经理是沉浸在自己的成功事件里，听众也只是听听而已，更谈不上有互动的话题。\u003cbr>&lt;反面例子&gt;\u003cbr>我自己也有过这样的翻车经历。之前在 2-1 拆书的现场做故事演练，我分享了一款改善女性肌肤的面膜。当时我拿着产品展示，全程都在讲：这款面膜成分温和纯净，有修护作用、能深层滋养补水，对敏感肌非常友好。把产品优点说了个遍，最后还不忘补充一句：“正是因为我用了这款面膜，皮肤才这么好！”\u003cbr>虽然我说的都是事实，可现场听众却很无感。因为在场女生大多都在用面膜，我说的效果究竟好不好，她们无从判断，单靠罗列优点根本吸引不了人。再加上我全程只讲产品本身，听众既不懂复杂成分，也没有产品的使用体验，只会觉得我说的内容和自己的需求并无关联。\u003cbr>毫无疑问，这是一次非常失败的分享。\u003cbr>HOW：\u003cbr>后来我才明白，问题就出在我根本没和听众建立「共」字，只是沉浸在产品有多好里自说自话。\u003cbr>那到底怎么做，才能真正和听众产生共鸣？我从折页中提炼出一套由外到内的 \u003cstrong>「三共法」\u003c/strong>：\u003cbr>\u003c/p>\u003col>\u003cli>\u003cstrong>外共\u003c/strong>：聚焦外在经历与身份。比如我们女性，既是女儿、妻子、母亲，也是职场人、学生、创业者；除此之外还有共同的职业、爱好、习惯等。先通过这些共性，找准对应人群的心理需求，明确要解决什么问题、达成什么目标，以此确定沟通方向。\u003c/li>\u003cli>\u003cstrong>内共\u003c/strong>：侧重内在感受与情绪共鸣。有了外共的方向，再去呈现出遇到的困难挫折，以及由此产生的负面情绪，让听众有同理心。\u003c/li>\u003cli>\u003cstrong>神共\u003c/strong>：上升到精神层面，也就是价值观共鸣。在情绪共情之后，给出面对困境的你持有态度和选择，传递你的价值观，深入人心。\u003c/li>\u003c/ol>\u003cp>学会这套共鸣三步法之后，再回头看我 2-1 定级的分享，我会这样重新设计：\u003cbr>&lt;正面例子&gt;\u003cbr>\u003cstrong>第一步，先做外共，锚定共同身份与习惯。\u003c/strong>\u003cbr>我会先问现场的女生：“大家都用过面膜吧？是不是都想让自己的皮肤白皙有光泽，年轻精致的状态？在场的同学有没有这样的想法？”先通过提问，确认我们的共同身份和共同需求，快速拉近距离。\u003cbr>第二步，\u003cstrong>内共\u003c/strong>—— 情绪共鸣。\u003cbr>我是 80 后，很多人说我看起来像 90 后，皮肤状态还算不错。但在这之前，我曾被一款面膜坑惨了。当时商场做活动，我买了一套国外品牌的化妆品，对他是满心期待，结果却出了问题。半夜里脸奇痒无比，忍不住去抓，第二天早上你们猜怎么样？两眼红肿，脸上全是不均匀的红疙瘩，整张脸都肿得变形，红点是又刺又痒，想抓又不能抓，简直又难受又揪心。当时我满脑子都是完了，毁容了，毁得肠子都青了，气急败坏地打电话骂无良商家，价格卖得这么贵，东西却这么坑人，没有预想的效果，只有严重毁容的后果，真的是恨得牙痒痒。\u003cbr>到了这里，就算你没有经历过一模一样的事情，被坑的气愤、骂街，焦虑，是不是也能感同身受？\u003cbr>好，继续，后来我偶然认识了这款面膜的创始人，他是一名退伍军人，退伍后自主创业做产品研发。从原料选择、生产工序到质检细节，他都严格把关，所有产品都会先在内部反复试用，才推向市场。主打成分纯净，安全有效，修复与抗衰的功效。\u003cbr>我抱着试试的心态用了他们的产品，价格是我之前买大牌的十分之一，可想而知这里面的价格水分有多大。大概一周的时间，脸上的红肿就基本消退，红点也消失了，皮肤状态甚至比以前更好，真是不幸中的万幸。\u003cbr>换作以前，问题解决了这事也就过了。在这次经历后我会主动帮他们分享。因为我踩过的坑，不希望别人再跳，不希望大家花冤枉钱、受冤枉罪。只要有朋友遇到护肤难题，我都会把避坑经验分享出去，教大家怎么选到即亲民又真正的好产品，打破贵就是好的误区。\u003cbr>更重要的是，这位创始人有良心、有工匠精神，还带着军人的担当与血性，他的人品和产品都值得被更多人看见。中国品牌正在崛起，我们也该对自己的文化自信。如果有同学感兴趣，我可以把他们的后台分享给大家。\u003cbr>这就是第三步，\u003cstrong>神共\u003c/strong>—— 让大家看到，我是一个嫉恶如仇，把避坑的经验分享给身边的人。\u003cbr>就这样，通过外共、内共、神共三个层次，搭建起了与听众的共鸣。不难发现，有了共鸣，你说的话、讲的事才更真实，就能自然唤起听众的相似经历和情绪呼应，而不是干巴巴地讲理论、讲道理。\u003cbr>WHERE：\u003cbr>这套三共法适用场景十分广泛，无论是公开演讲、培训授课，还是产品发布、销售沟通，甚至是想要提升个人影响力与说服力，都可以直接套用，实用性极强。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：【A1激活经验—显像提问】\u003cbr>&lt;提问设计&gt;\u003cbr>刚刚分享的是我自己踩过的坑，相信大家多多少少也有过同款无奈。接下来给大家三个的画面，邀请大家一起回想一下：最近半年里，你有没有遇到过这些类似场景？\u003cbr>第一个，关于亲密关系：\u003cbr>你有没有过这样的时刻？和父母、伴侣或是孩子沟通，明明是出于好心、为对方着想，却只站在自己的角度讲道理、提要求，最后话不投机、越说越僵，闹得不欢而散？\u003cbr>第二个，关于公开表达：\u003cbr>你有没有过这样的尴尬？上台分享、工作汇报时，自己在台上讲得认真，台下却听得云里雾里、毫无反应，没人互动、没人接话，尴尬到脚趾抠地？\u003cbr>第三个，关于价值传递：\u003cbr>你给别人推荐产品、分享方法、介绍机会时，明明觉得特别适合对方、能真正帮到他，可不管你怎么说优点、摆事实，对方就是听不进去，甚至还对你反感、充满质疑？\u003cbr>请大家在小组内讨论分享，时间为3分钟，时间到我会邀请两组各派一位伙伴上台分享。\u003cbr>\u003cem>&lt;学习者案例&gt;\u003cu>分组讨论，2min\u003c/u>\u003c/em>\u003cbr>时间到，下面由请左边小组派一个代表，用1-2分钟时间分享一下她的案例，先不做解决。\u003cbr>案例1：黄老师是关于亲密关系的案例\u003cbr>儿子在期中考试的时候，考了80几份。发现孩子是记不住，于是就孩子讲道理，用间隔重复法。但是孩子听不进，沟通说道理失败\u003cbr>\u003cbr>\u003cbr>案例1：露锦老师是关于公开表达\u003cbr>在一次学校推行数学阅读的分享，认为阅读分享是非常好的，能提升学习的智力和表达。她在台上说的很多好处，很有激情，家长们听的没有回应，自己感觉到非常的尴尬。\u003cbr>【A1+反思加工】\u003cbr>感谢两位老师的分享，刚才大家也都分享了自己曾经失败经历。假如给你机会修正，结合3步共鸣的步骤，我们重新把失败经历变为成功的经历。\u003cbr>请大家继续在小组内讨论，3分钟后我会再一次邀请刚刚分享过的伙伴。\u003cbr>\u003cem>\u003cu>分组讨论， 2min\u003c/u>\u003c/em>\u003cbr>时间到，由请黄老先分享，用3分钟时间继续分享修正后的案例。\u003cbr>\u003cem>&lt;学习者案例&gt;\u003c/em>\u003cbr>案例1：黄老师\u003cbr>外共：先和孩子外共一个身份，自己小的时候考试考不过的经历。记不住是不是有其它的原因，再到自己小的时候记不住贪玩，没考好。找到共鸣相似\u003cbr>内共：共情他的感受，没考好自己是不是很着急，背不下来的心情。\u003cbr>神共：说明着急转化成积极的心态，要么不做，要做就做好。\u003cbr>\u003cbr>\u003cbr>案例2：露锦\u003cbr>外共：先从自己的经历出发，和大家确认是妈妈这个身份\u003cbr>内共：和大家分享心在的感受和情绪。不指责不批评放心心态\u003cbr>神共：让大家知道阅读是家长送给孩子一个礼物而不是压力\u003cbr>【折书家总结】\u003cbr>拆书家：感谢XX的精彩分享，她把自己的案例结合3步共鸣法，解决了沟通难，听不懂，不想听的问题\u003cbr>【总结过渡】\u003cbr>我们总结一下三步共鸣法的核心，其实就在于一个 「共」字 。从外在的身份、背书、经历，到内心真实的情绪，尤其是挫折与困境的情绪，再到深层的精神品质与价值观，这三个层次层层递进。目的就是把你想说的内容，转化成即说的轻松又真情实感，别人爱听并且能感同身受的内容，真正实现高效沟通。\u003cbr>【预防异议】\u003cbr>讲到这里，可能有人会问：“这三步听起来很好，但需要时间去设计、去分析听众。如果是临时场合或者是即兴发言，根本来不及准备，该怎么办？”\u003cbr>这是一个非常好的问题。这里给大家一个实用技巧：只要你抓住第三步 ——\u003cstrong>价值观\u003c/strong>，就能应对。\u003cbr>带着这个问题，我们一起进入第二个片段的学习。\u003c/p>\u003cp>\u003cbr>【片段 2 学习目标】\u003cbr>本片段学习目标：跟随我完成本次RIA现场学习后，学习者能够在亲子冲突的场景中【运用】故事证明价值观的三步模型，完成角色扮演并传递出核心价值观。通过具体事件、情绪细节和内心选择过程、传递核心价值，把抽象的过程，变成有画面感，有说服力，有灵魂的真实故事。\u003cbr>接下来，请大家用 1–2 分钟时间阅读片段 2，阅读完成后请举手示意。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":24264,"quote":"\u003cp>R原文片段：\u003cbr>我在之前公司的时候，有一次因为一个历史遗留问题，公司有可能被罚款几百万，但在公司看来这样的处罚是缺乏足够依据的。当时我被老板派去解决这个问题，看能不能不罚或者少罚一些。那时候，我和团队几乎每周都要一大早坐上高铁去和当地相关部门沟通，交涉了很久，但问题都像皮球一样被踢来踢去，大家都很绝望。其中有一个下属就提出，要不然给经手的人点好处，把这事儿打点得了。\u003cbr>我当时就对他说：“我理解你的心情，我也很烦，天天到处求人。但是老板曾经跟我说过这么一句话：‘如果明天报纸的头版头条登的就是你做的这件事，你觉得可以登吗？如果可以，你就去做，如果不可以就不要做。’所以，你好好想想，刚才你建议能达到这样一个标准吗？” 那个下属说 “肯定不能”，我说：“那不就完了，咱继续想办法解决吧。” 最后我们通过各种沟通，反复游说，找相关证据，总算是把问题完美解决了。\u003cbr>这件事情背后体现的是什么呢？既是我的价值观，也是公司的企业文化。这个故事看似没有提到 “选择” 这两个字，但是你能看出来背后的选择。\u003cbr>所以讲故事的最大作用之一就是证明。最好的证明，就是因为你觉得这个 “价值观” 重要，所以不管发生了什么困难，无论结果如何，你都会坚守这个价值观。说到价值观就一定会涉及选择。讲故事就是不仅要告诉别人你的选择是什么，还讲述了你选择的过程。在那个过程中，你的纠结，你的痛苦，你的努力，说明了你为什么做出那个选择，那个 “为什么” 就是你的价值观。而如果没有那些选择上的冲突，你就无法体现你的价值观。\u003c/p>","explains":"\u003cp>拆书家讲解引导：\u003cbr>好的，我看到有伙伴已经读完了！接下来，我们就一起拆解这个片段的内容。\u003cbr>WHAT：\u003cbr>首先我想先问大家一个问题：看完这个故事，你对主人公最深刻的印象是什么？\u003cbr>「坚守底线、原则性强」。大家有没有发现一个特别神奇的事：主人公从头到尾，都没有说过一句 “我是个讲原则、有底线的人”，但我们会从他的故事里感受到了他的价值观。这，就是我们今天第二个片段要讲的核心 ——\u003cstrong>用故事证明价值观，而不是用口号喊出价值观。\u003c/strong>\u003cbr>WHY：\u003cbr>\u003cem>&lt;一般做法&gt;\u003c/em>\u003cbr>那么我们平时表达时，最容易踩的坑是什么？我相信大家都见过，甚至自己也这么做过：做自我介绍时，给自己贴的的标签可能是 ——“我是个守信、负责、能扛事的人”；或者有创业者说的：“我以客户为中心，甘愿付出。”\u003cbr>大家不妨品一品：就算这些话都是真的，你听完会发自内心地相信吗？大概率不会。因为这些只是一堆空泛的标签，没有具体事件，没有两难冲突，没有内心挣扎，更没有真实的选择过程。\u003cbr>\u003cem>&lt;不那么做的坏处&gt;\u003c/em>\u003cbr>这样的表达，问题非常明显：没有画面感，没有说服力，听众听不进去、记不住，更不会真心认同。价值观无法被证明，就只是空喊口号，显得苍白又无力。\u003cbr>那到底怎样才能讲出一个能证明价值观、让听众真正信服的好故事呢？我从拆页的案例里，提炼出了一套可以直接套用的三步模型。\u003cbr>HOW（细化行动步骤）：\u003cbr>✅ 第一步：\u003cstrong>造难\u003c/strong>—— 制造两难冲突。就像拆页中的主人公，一边是几百万罚款的压力，一边是违规打点、走捷径的诱惑，这就是典型的两难冲突。\u003cbr>✅ 第二步：\u003cstrong>对话\u003c/strong>—— 呈现内心挣扎。加入真实的对话、内心的纠结与思考。比如拆页里，下属提议去打点疏通，主人公和下属的这段对话，就是在展现挣扎。\u003cbr>✅ 第三步：\u003cstrong>选择\u003c/strong>—— 明确最终决定。说出你的最终选择，并讲清楚 “为什么这么选”。这个 “为什么”，就是你的价值观。拆页里主人公的理由是：“坚守底线，不做不能登报的事”，这正是他的核心价值观。\u003cbr>就这三步，把抽象的价值观，变成了有冲突、有温度、有说服力的真实故事。\u003cbr>&lt;意译案例&gt;\u003cbr>光说方法大家可能没概念，为了加深理解，我分享一个自己的真实案例。\u003cbr>一几年的时候我有一位客户遇上了审计查账。他之前在一家茶叶店买了不少茶叶，当时既没要发票，也没开收据。他性格比较腼腆，跟店家沟通了好几次，可对方一听账务检查就很敏感，始终不配合。实在没办法，他就找到我，请我帮忙去沟通。\u003cbr>我先去茶叶店找店员协商，结果对方是各种推诿：要么说时间太久查不到记录，要么说经办人不在。我来回跑了好几趟，一点进展都没有。回来跟同事聊天吐槽，一位同事说：“这本来就不是咱们的工作，客户自己都搞不定，你直接回绝就是，何必在这受气还白费力？”\u003cbr>当时我跟同事说：“我懂你的意思，确实跑得又累又憋屈。但你想想，别人找到你帮忙，一是自己确实没招了第二也确实非常的信任你；而我既然是答应了人家，再难，我也得再试试，轻易放弃不如一开始就不要答应了。\u003cbr>后来我又前前后后跑了四五趟，找门店、找经办人、找会计，好言好语软磨硬泡，终于帮客户补开了收据和发票。\u003cbr>客户特别开心，问我：“咦，你是怎么做到的？”我笑着跟他说：“你太斯文了，我比较武夫，他们怕。”\u003cbr>大家对照这个三步模型来看：\u003cbr>第一步造难：客户的紧急需求、店家不配合、多次沟通无效。再加上同事劝我放弃，构成了 “坚持还是放弃” 的两难冲突；\u003cbr>第二步对话：我和同事的对话，真实展现了我当时的想法，让故事更有画面感；\u003cbr>第三步选择：我最终选择坚持帮忙，核心原因就是 “受人之托，忠人之事”，这就是我要传递的价值观。\u003cbr>一个真实的故事深入人心，远比你空口说十句 “我是个靠谱的人” 更有说服力。\u003cbr>Where：\u003cbr>而这套方法可以说，适用场景也非常广泛。\u003cbr>\u003cstrong>演讲，\u003c/strong>产品销售宣讲、个人 IP 影响力打造，晋升面试等等，需要传递你个人理念、增强说服力的场景，这套方法都能直接套用。\u003cbr>不适用：\u003cbr>当然了没有任何一个方法能吃遍天下，这套方法也有明确的适用边界，有两种情况，它是不适用的：\u003cbr>第一，面对不讲规则、没有底线的人，不要用这套方法。\u003cbr>价值观共鸣的前提，是双方有基本的价值共识。对这类人而言，你的原则和真诚毫无意义，最好及时避开，换其他方式应对。\u003cbr>第二，需要严格出示事实、数据、证据的正式场景，不要用故事替代证据。\u003cbr>比如审计对账、法庭举证、学术报告等，必须是客观有依据，故事只能作为辅助，绝不能当成核心证明。\u003cbr>预防异议\u003cbr>讲到这里，不知道大家有没有想过一个问题：我们刚才说的 “造难、对话、选择” 这三步，强调的是要遵从自己真实的内心感受，那是不是意味着，我们必须做出普罗大众公认的、积极向上的 “标准答案”？如果我内心的真实想法，是带有私心的嫉妒的那这套方法还能用吗？\u003cbr>答案是肯定的：可以用\u003cstrong>，\u003c/strong>只要不犯法就不用刻意塑造完美人设。\u003cbr>我们用故事传递价值观，从来不是要演一个 “圣人”“完人”，而是鲜活、立体地展现最真实的自己。你越勇敢的直面自己的丑陋，越敢表露内心真实的纠结与选择，反而越接地气、越走心；听众会觉得你我都是个有血有肉的普通人，不是一个刻意包装的 完美主义的人。正是因为我们都是一半天使一半恶魔般存立，每一个合法真情的选择，都值得被尊重。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：\u003cbr>【A3促动参与】\u003cbr>\u003cem>&lt;场景设计&gt;\u003c/em>\u003cbr>好，现场的天使们我们来练练吧，大家可以想象这样一个场景：\u003cbr>假期，老师布置了一项作业，要求是用ppt或者用手绘的方式做一个汉字的由来。到了开学的时候看到有的同学用了ppt分享，生动有趣内容丰富。这时妈妈就想手绘搞也费劲的做好，就这样上交算了。但为了让孩子知道情况就把现状也告诉了孩子，让孩子自己做主。可孩子坚持要重新做ppt。请用造难，对话，选择体现出孩子精益求精的精神。最后妈妈配合孩子完成了ppt。\u003cbr>\u003cstrong>内容规划\u003c/strong>:\u003cbr>\u003c/p>\u003cul>\u003cli>\u003cstrong>造难 (制造两难冲突)\u003c/strong>:\u003cbr>\u003c/li>\u003cul>\u003cli>\u003cstrong>压力\u003c/strong>: 时间紧迫（马上要开学），孩子已经完成了手绘版，重做意味着额外的工作量和时间投入。\u003c/li>\u003cli>\u003cstrong>诱惑\u003c/strong>: 妈妈提出的 “捷径”—— 直接交手绘版，省事省力，也完全符合老师要求。\u003c/li>\u003cli>\u003cstrong>两难\u003c/strong>: 是选择轻松省事地交上手绘版，还是选择更难但效果更好的 PPT 版？\u003c/li>\u003c/ul>\u003c/ul>\u003cul>\u003cli>\u003cstrong>对话 (呈现内心挣扎)\u003c/strong>:\u003cbr>\u003c/li>\u003cul>\u003cli>妈妈和孩子之间的对话是关键。妈妈提出建议，孩子表达坚持。\u003c/li>\u003cli>通过对话，展现孩子内心的思考过程：他看到了差距，不满足于 “完成”，而是追求 “更好”。\u003c/li>\u003cli>对话要体现出孩子的决心和对 “精益求精” 的朴素理解。\u003c/li>\u003c/ul>\u003c/ul>\u003cul>\u003cli>\u003cstrong>选择 (明确最终决定)\u003c/strong>:\u003cbr>\u003c/li>\u003cul>\u003cli>孩子最终选择坚持做 PPT。\u003c/li>\u003cli>在讲述选择时，要点出他选择背后的原因，即 “精益求精” 的价值观。例如，他会说 “我想做得更好”、“我想让我的作业更生动” 等等。\u003c/li>\u003c/ul>\u003c/ul>\u003cp>\u003cem>&lt;角色扮演&gt;\u003c/em>\u003cbr>接下来，按照之前的分组，1人扮演孩子，一人扮演妈妈。在小组内交流和演练。5分钟后，我会请两组伙伴上台演练。\u003cbr>\u003cem>\u003cu>分组讨论 5min\u003c/u>\u003c/em>\u003cbr>（5分钟后）时间到，下面我们请二排的两组同学，用角色扮演的形式呈现对话。每组有5分钟的时间。\u003cbr>\u003cem>&lt;学习者案例一&gt;\u003c/em>\u003cbr>学习者案例：\u003cbr>学习者1:\u003cbr>妈妈：你这手稿做完了，做的挺好的，就这样教上去学可以了。\u003cbr>孩子：老师说了用ppt展示的好，所以我改成用ppt了\u003cbr>妈妈：你看现在都9点了，时间来也及了，如果坚持用ppt万一讲不怎么办，前面手稿也白费工功夫\u003cbr>孩子：因为我就想用ppt，大家都有，我也想要，同学们都这样做，老师也夸了这样做的好，做不好也没关系，说明我会了两个方法我都会了。\u003cbr>妈妈：你打算ppt怎么样做呢\u003cbr>孩子：你跟我一起做吧\u003cbr>拆书家：感谢两组伙伴的精彩演绎。掌声再次送给他们。\u003cbr>【A2催化应用】\u003cbr>\u003cem>&lt;提问设计&gt;\u003c/em>\u003cbr>如果未来如果类似的沟通问题，你会如何应用。\u003cbr>\u003cem>&lt;学习者案例一&gt;\u003c/em>\u003cbr>学习者1应用：\u003cbr>未来在做演讲的时候，传达自己的价值观。先讲出两难的困境，加上与人对话或者与自己的心里对话，强后强调我的选择，并讲出选择背后的原因。\u003cbr>\u003cem>&lt;拆书家回应&gt;\u003c/em>\u003cbr>总结点评：感谢两个的分享\u003cbr>【强有力的结束语】\u003cbr>到这里，今天的拆书分享就接近尾声了。最后，我们用 1 分钟快速回顾一下今天的内容。\u003cbr>今天整场拆书围绕《故事力》展开，核心学习了两套故事模型：\u003cbr>第一套，是建立共鸣的 「三共法」，核心就是一个\u003cstrong>共字\u003c/strong>。\u003cbr>第一步\u003cstrong>外共;\u003c/strong>第二步\u003cstrong>内共;\u003c/strong>第三步\u003cstrong>神共;\u003c/strong>\u003cbr>第二套，是传递价值观的 「三步故事模型」核心是真字。\u003cbr>第一步\u003cstrong>造难\u003c/strong>；第二步\u003cstrong>对话\u003c/strong>；第三步\u003cstrong>选择\u003c/strong>。\u003cbr>未来的日子里，我们依然会面临无数的两难和选择：是迎难而上，还是绕道而行？是迎合标准答案，还是坚守真实的自己？\u003cbr>我想说的是：迎难而上是勇气，绕道而行是智慧，迎合标准是稳妥，坚守真实是突破。怎么选，都没有绝对的对错。我们不必刻意塑造完美人设，不必逼自己活成标准答案。真实、鲜活、有血有肉、独一无二的你，本身就足够动人。\u003cbr>最后，送大家一句话：\u003cstrong>共鸣让我们相知，价值观让我们相吸。同心者同路，同路者共赢！\u003c/strong>\u003cbr>好了，我今天的 TF2-4 拆书晋级分享，到此全部结束。再次感谢各位老师的专业指导，感谢各位伙伴的全程陪伴，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1776353910000,"updated_at":1780017273000,"ria":true},{"id":19579,"topic":"掌握邀功三步法，让你的辛苦被看见","learn_goal":"","remark":"你将获得： \n1️⃣ 一套公式： 报功劳+诉苦劳+要酬劳 ，让每一滴汗水都算数。\n 2️⃣ 一种思维： 学会填补领导的“视觉盲区” ，消除“这事很容易”的错觉 。\n 3️⃣ 一份底气： 不再做默默受气的“老好人”，做发光发热的“职场人” ！","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"kkk-cq","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>开场白\u003c/strong>\u003c/p>\u003cp>大家好，欢迎大家来到今天的拆书活动。我是KKK，我用三个标签介绍一下自己。\u003c/p>\u003cp>一级拆书家——我来自重庆山城分舵，现在在佛山工作。\u003c/p>\u003cp>零碳”规划师”——在一家500强企业，做新能源相关业务，项目复杂、跨部门协调多。\u003c/p>\u003cp>职场”老好人”——活是我干的，但功劳好像总落不到我身上。\u003cbr>\u003c/p>\u003cp>【过渡】后来，我在《故事力》里，找到一个特别适合像我这样‘会做但不会说’的人，今天想分享给大家。\u003c/p>\u003cp>\u003cstrong>【图书及作者介绍（FAB介绍法）】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F（特点）\u003c/strong>\u003cem>：\u003c/em>这本书是高琳博士和她老公写的，他们长期服务世界500强企业，擅长用讲故事的方式去影响别人，这本书也获得了杨澜和潘石屹等大佬推荐。\u003c/p>\u003cp>\u003cstrong>A（优势）\u003c/strong>\u003cem>：\u003c/em>市面上很多讲故事的书，大多侧重于文学或演讲，实用性不足。而这本书最大的优势在于提供了大量的“场景”和“工具”，例如工作汇报、销售、演讲等，让我们学了就能用得上。\u003c/p>\u003cp>\u003cstrong>B（益处）\u003c/strong>：\u003c/p>\u003cp>B1:如果你觉得自己表达能力、影响力差，这本书能让你通过讲故事的方式，轻松影响别人。\u003c/p>\u003cp>B2：如果你和曾经的我一样，是个只会干，不会说，经常吃哑巴亏，学习这个片段后，我们就能把“苦劳”变成“功劳”，让自己不再是默默受气的“老好人”！\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次学习后，学习者能够运用“邀功三步法”，在“克服困难完成任务”的模拟场景下，完成一次既展示成果又体现价值的工作汇报。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了更好地练习，下面先进行分组，就按现在的座位2个人1组，待会就按分好的组进行演练。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>接下来，让我们先来阅读一下原文片段。我给大家1分半钟时间，大家看完后可以抬头示意。\u003c/p>","ratings_count":1,"texts":[{"id":23977,"quote":"\u003cp>一个完美的工作汇报能够照顾到理性目标和感性目标两个层面，如果只有理性目标，话倒是说清楚了，但是你的价值没有凸显，而如果只有感性目标，老板的问题没有得到答案，你还一直说你多不容易，老板一定觉得你就知道摆花架子，同事也会觉得你就知道显摆（见表2）。\u003c/p>\u003cp>理性目标可以摆事实讲道理，感性目标通常是一种感受，因此需要用故事来实现感性目标。那么如何才能在一个汇报中完美地呈现两个目标呢？\u003c/p>\u003cp>你需要在汇报前明确自己的两个目标，也就是准备好前面几章讲到过的——故事的红绳，你的故事主线。接下来，你需要做的，就是根据工作内容，给这条红绳串上珍珠。\u003c/p>\u003cp>正如案例中的小张，她的理性目标就是让老板知道，我们团队圆满地完成了招聘任务。她的感性目标是希望老板理解并且认可团队为了达成这个目标而付出的辛苦努力。所以，如果结合她老板为人处世的风格，她的故事就可以这么讲：\u003c/p>\u003cp>我们这次现场\u003cstrong>签约80人，比往年的结果都好\u003c/strong>；\u003cstrong>还有50人一周内签订合同寄回，估计85%可以签约\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>不过，这次招聘还真的不容易\u003c/strong>，扩招之后毕业生比预计的多了近一倍，我们团队4个人，连吃饭喝水的时间都没有……最后回来的时候，我们的飞机还两次发生故障，迫降太原。我都差点儿以为不能回来了。\u003c/p>\u003cp>这次团队的所有人都辛苦了，\u003cstrong>您可得请大家吃饭犒劳犒劳\u003c/strong>。\u003c/p>\u003cp>这么一说，既\u003cstrong>让老板知晓自己想要的结果\u003c/strong>，也\u003cstrong>让他了解到团队付出的艰辛\u003c/strong>，继而\u003cstrong>点明了自己期望得到的认可方式\u003c/strong>。如果我是老板，一定立刻就会请团队吃大餐。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这个片段介绍了一个在我们完成一项比较有难度或挑战的任务后，给领导进行汇报的方法，即“邀功三步法”。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>大家有没有想过，为什么我们明明干得脱了一层皮，领导却觉得理所当然？ 其实，这不是领导冷漠，而是因为我们之间存在“信息不对称”。\u003c/p>\u003cp>我们经历了九九八十一难，但领导只看到了最后取回真经的结果。正如书中说的，如果我们只汇报了结果（满足了理性目标），却隐瞒了过程中的波折（缺失了感性目标），领导就会陷入一种“错觉”——他会以为这事儿本来就很简单，你干成是“应该的”。\u003c/p>\u003cp>【过渡】一次好的汇报，其实要同时满足两个目标：\u003cbr> 一个是把事情讲清楚（理性目标）， 一个是让对方理解你的付出（感性目标）。接下来这个方法，就是一步一步把这两个目标补齐。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>原文中没有给出具体的行动步骤，我们来根据案例进行了\u003cstrong>细化行动步骤\u003c/strong>：\u003c/p>\u003cp>第一步：\u003cstrong>报功劳，\u003c/strong>汇报时，先说结论或数据，证明“搞定了”。\u003c/p>\u003cp>我们看原文说的是“签约80人，还有50人一周内签订合同寄回，估计85%可以签约”，上来就把用数据把“理性目标”告诉领导，说明事情“搞定了”。\u003c/p>\u003cp>第二步：诉苦劳，讲过程中的波折，体现“不容易”。\u003c/p>\u003cp>对应原文“扩招之后毕业生比预计的多了近一倍”“飞机故障，迫降太原”。通过意外，让领导明白我们背后的艰辛。\u003c/p>\u003cp>第三步：要酬劳，通过轻松口吻，提个小要求，让领导认为“值得赏”。\u003c/p>\u003cp>对应原文“这次团队的所有人都辛苦了，\u003cstrong>您可得请大家吃饭犒劳犒劳\u003c/strong>。”\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>给大家举个我最近的真事儿。领导让我测算一个项目数据，他嘴上说得很简单：“就分析两种情况就行”。结果我一上手发现全是坑，背后是16种情况。做完之后，我是这么汇报的：\u003c/p>\u003cp>第一步：报功劳， 我先给领导汇报结果：“廖总，数据我们已经分析好了，报告在这儿。”\u003c/p>\u003cp>第二步：诉苦劳， 我接着汇报过程的不容易：“这活可没这么简单，实际一做，不止两种情况，细分下去，一共包含了 16 种工况。我还找了两个兄弟配合，花一整天才搞定，现在看电脑屏幕，眼睛都是花的。”\u003c/p>\u003cp>第三步：要酬劳，要个小奖励。我就说：“廖总，为了分析者数据，我们的脑细胞可是阵亡了一大半。您可得请咱们项目组喝杯咖啡，给大家补补脑啊！”\u003c/p>\u003cp>结果领导当时就乐了，不仅买了咖啡，还给我们买了下午茶。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>适用场景：完成高难度、有挑战的任务，特别需要他人给资源、给认可时。\u003c/p>\u003cp>慎用场景：\u003c/p>\u003cp>①看人：如果你的老板是那种“只看结果、完全不在乎过程”的人，这招慎用，直接报结果就好，免得他觉得你矫情。\u003c/p>\u003cp>②看脸：观察老板的脸色。如果他正心情不好或者焦头烂额，千万别去凑热闹，否则邀功不成反被怼。\u003c/p>\u003cp>注意，我今天不是教大家‘多诉苦’，而是教大家在汇报里补上‘领导原本看不到的难度’。\u003c/p>","interaction":"\u003cp>【\u003cstrong>场景设计\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>背景:\u003c/strong>我们来设想一个场景，小张是一个公司销售，一天你们领导王总让你去找客户收款，王总觉得事情很容易。\u003c/p>\u003cp>困难：但小张去了之后，发现根本不是这么一回事，对方就是以各种理由不给钱。\u003c/p>\u003cp>结果：最后费尽千辛万苦，终于把钱要回来。\u003c/p>\u003cp>目标：小张通过“邀功三步法”获得王总认可。\u003c/p>\u003cp>【\u003cstrong>小组演练\u003c/strong>】\u003c/p>\u003cp>现在，请每两个人一组，在组内进行演练。\u003c/p>\u003cp>一个人扮演小张，应用邀功三步法来汇报成果，你可以丰富更多细节；\u003c/p>\u003cp>一个人扮演王总，你现在的心理状态是，你真心觉得这事儿很容易。演练开始后，请你先开口。 \u003c/p>\u003cp>演练时间3分钟，现在开始。\u003c/p>\u003cp>【\u003cstrong>角色扮演\u003c/strong>】\u003c/p>\u003cp>下面我请两个伙伴，来给我们展示一下。\u003c/p>\u003cp>小张（开心）：王总，年尾那几笔款我们收回来了（报功劳）。不过真不容易呀（诉苦劳），我们几个兄弟，天天泡在客户公司，各种软磨硬泡，给客户端茶递水，有的还帮客户接娃，终于把钱都收回来了。王总，这段时间，大家都累坏了，你可得请大家吃个饭呀（诉苦恼）。\u003c/p>\u003cp>美惠（王总）：大家确实不容易，就今晚吧，大家一块聚聚。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>以上就是今天的全部内容，“不要让100分的汗水，因为30分的汇报而打了折。” 今天我们学的“报功劳、诉苦劳、要酬劳”这三招，就是为了打破这个魔咒。 汇报不是炫耀，而是对工作的负责。\u003c/p>\u003cp>希望回到职场后，大家都能大胆运用这套方法，不再做默默无闻的“老好人”，而是做发光发热的“职场人”！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1766751580000,"updated_at":1766800736000,"ria":true},{"id":19541,"topic":"不冲突无价值-—用冲突显现你的价值观","learn_goal":"","remark":"不冲突无价值-—用冲突显现你的价值观","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"谢尚袁","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>各位老师、各位拆友，大家下午好！我是尚袁。\u003c/p>\u003cp>上善若水，广结善缘，很开心和大家共度一下午的学习时光。\u003c/p>\u003cp>我是一名广告设计师，深耕文化墙设计与制作，这是我的第一份事业。\u003c/p>\u003cp>人到中年，上有老下有小，20年疫情我深刻感悟到，没钱人生健康是底牌；有钱人生健康是王牌。前半生，我为设计事业拼搏；后半生，我更想为自己和家人的健康拼力。\u003c/p>\u003cp>21 年开始学习中医，靠着推拿、刮痧、艾灸，帮二宝调理好了鼻炎、腺样体肥大、脾胃虚弱的问题；最有成就感的是6岁儿童的小儿疝气在医学上是必须手术解决，在我的调理下孩子现在已经完全恢复。即省下不少钱孩子也避免了手术带来的伤害。同时也为父母调理好了肩腰腿疼痛结节四高等困扰。\u003c/p>\u003cp>也正因如此，养生调理和教会他人养生，成为我人生的第二份事业。\u003c/p>\u003cp>广告设计和中医养生这两个看似毫无交集的领域，却恰好平衡了我生命的重量与质量 ， 一手抓工作，一手抓健康。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>以上是我的个人介绍，现在开始进入拆书环节，前面老师已经做了分组，我们就保持这个组型，方便后面小组讨论\u003c/p>\u003cp>【FAB】介绍本书：【1-2】\u003c/p>\u003cp>F: 今天我拆的这本书，书名是《故事力》，作者高琳，一位留美理科生博士。\u003c/p>\u003cp>这里特别强调理科生的身份，主要有两层意思：一是理科生通常更专注于分析和研究，较少需要去讲故事；二是连理科生都开始讲故事了，足以说明讲故事的能力真的很重要。\u003c/p>\u003cp>尤其是AI技术飞速发展的今天，许多技术性工作正面临被替代的挑战，但讲故事这种融合了情感、共情与人文温度的能力，恰恰是目前AI难以企及的。\u003c/p>\u003cp>书中既有心理学知识，也有实际案例，会告诉你该怎么讲故事，以及如何在工作生活中通过讲故事达成自己的目标。\u003c/p>\u003cp>A:这本书好就好在，提炼了多个可直接套用的故事模型，把晦涩的理论拆解成了一步步能落地的实操方法。让我们能把故事讲得生动有趣，真正引发听众的共鸣。\u003c/p>\u003cp>但再好的书，若不能落地到我们的生活中，又有什么意义呢？\u003c/p>\u003cp>B：比如你说我有爱心，别人感受不到；你讲我坚守初心，也打动不了别人。通过今天我拆解的内容，学会它就能帮你解决这些问题同时还能落地在生活里，用一个有真实冲突的故事让你脱颖而出，让对方瞬间读懂你的价值，精准吸引同频的伙伴，少走无效的弯路。\u003c/p>\u003cp>【学习目标】今天学习的目标是在跟随我完成本次RIA现场学习后，学习者能够在讲故事中，用三步挖掘冲突，彰显你的价值观，让人更加立体的了解你\u003c/p>","ratings_count":2,"texts":[{"id":23933,"quote":"\u003cp>如何选择冲突来彰显你的价值观\u003c/p>\u003cp>前面讲过，价值观和内在动力，需要通过冲突和解决冲突的过程来展现。然而这里隐藏着一个很大的坑，那就是很可能你选取的冲突，也就是你的论据，在逻辑上根本不能支持你的论点和价值观。\u003c/p>\u003cp>我们的讲故事训练营里有一个作业，就是让同学讲一个“我为什么选择现在这份工作”的故事。不止一个同学在表达对现在工作和公司的“热爱”时，给我们讲的故事是：“我毕业后就一直在做这份工作。十年如一日，不论外部环境怎么变，我都忠于我的公司。”\u003c/p>\u003cp>乍一听觉得没问题，可仔细一想，时间长等于热爱吗？万一是你除了现在的工作，别的什么都干不了呢？新闻里那个高速路收费站大姐被裁员后哭天喊地，感叹她除了收费什么都不会，日后可怎么办啊！她十五年如一日地守在那个岗位上，就能够证明她热爱自己的工作吗？未必。\u003c/p>\u003cp>那你的故事中的冲突怎么足以证明你的动力呢？故事只是生活的提炼版本。当你面对困难时，是什么让你坚持下去，你自己知道。所以，你只需要仔细回忆当时的感受，到底是什么原因让你即使面对着这个冲突，还选择了坚持没有放弃？这个原因，才是你的内在动力和价值观。比如：曾经有猎头高薪挖你，但是你依旧选择了现在的工作，这是为什么？在某次销售的过程中，本来有某个捷径可以走，你却依旧选择了按照规矩办事，为什么？作为职场妈妈，当你产假还没休完的时候，有工作需要你，你立刻投入工作，那又是为什么？\u003c/p>\u003cp>这些个“为什么”的答案就是你的价值观，面对这些选择时挣扎的心情，就是能够证明你价值观的冲突。\u003c/p>","explains":"\u003cp>接下来，请大家翻开手中的拆页，我们一起走进内容一探究竟。\u003c/p>\u003cp>【阅读原文折页】选择冲突来彰显你的价值观（2-3分钟）\u003c/p>\u003cp>【I】复述原文【3-4】\u003c/p>\u003cp>what:\u003c/p>\u003cp>我们来看拆页中说：想要通过冲突彰显价值观，容易陷入论据无法支撑论点的误区。\u003c/p>\u003cp>比如职场里有人说：我连续三年盯同一个项目，想证明自己有担当。但干得久和有担当根本是两码事啊！就像餐厅服务员做了五年，不代表他就爱干服务这行，可能只是没别的选择。\u003c/p>\u003cp>故事是从生活里提炼出来的，真正能看出一个人心里怎么想、做事有什么底线的，看他碰到两难时的选择，以及为什么这么选？\u003c/p>\u003cp>简单来说他告诉我们：别用熬出来的经历证明价值，要用选出来的冲突、冲突越真实，选择越两难，你的价值观就越有说服力。\u003c/p>\u003cp>why:\u003c/p>\u003cp>选择用冲突会有什么好处呢？\u003c/p>\u003cp>增加故事的丰富性和彰显主人公的独特价值观和人格魅力。\u003c/p>\u003cp>HOW：\u003c/p>\u003cp>这里我提炼出三个实操步骤\u003c/p>\u003cp>第一步：选。选有效案例，避免单纯时长的经历，要有主动选择的场景。\u003c/p>\u003cp>比如不要说我创业5年了，换成当年我放弃了朝九晚五的稳定工作，咬牙选了有风险的创业。一下子就不一样了，能看出来是你主动做的选择，不是被动熬时间。\u003c/p>\u003cp>第二步：说。说纠结细节，好的经历分享是有那种左右为难的感受。\u003c/p>\u003cp>比如下班前遇到事儿，想违规走个捷径早点走，又觉得坏了规矩心里不踏实。把这种两难的纠结讲出来，你的例子就鲜活，别人才能感同身受。\u003c/p>\u003cp>第三步：问。为什么这么选，这是核心的一步，你最终选了A没选B，到底是图啥？这个答案就是你的做事原则。\u003c/p>\u003cp>比如你没走捷径还是按标准完成工作，理由是我觉得规矩比捷径更金贵。把这个理由和前面的纠结结合起来说，你的价值观不用喊口号，别人也能听得明白，还特别佩服。\u003c/p>\u003cp>where：这个方法适用哪些场景，我总结出5个\u003c/p>\u003cp>职场面试、个人品牌塑造、谈判、演讲、写作\u003c/p>\u003cp>【举例说明】通过以上三个步骤，用在我自身的一个真实故事中\u003c/p>\u003cp>去年夏天，我老公丢了一部手机。\u003c/p>\u003cp>刚开始打过去，电话通了没人接听。接着打后来手机直接关机了。我老公尝试最后一次努力。他通过苹果的iCloud服务锁定手机，并发送一条短信：手机里有我孩子从出生以来成长的珍贵照片和视频，还有我的工作资料。希望你还给我，有酬感谢，说到做到\u003c/p>\u003cp>短信发出后如同石沉大海没有回应。\u003c/p>\u003cp>时隔一年，好巧不巧！我捡到一部手机。\u003c/p>\u003cp>一个粗声粗气的男人打来电话带着油腻腔调说：哎，你怎么拿我手机的？\u003c/p>\u003cp>我一愣：我没听错吧，我在路上捡到的手机，你不说谢也就算了，还反咬一口？\u003c/p>\u003cp>他说：哦哦，那对不起，那你在哪儿？我来拿。\u003c/p>\u003cp>我说：中山北路252号。\u003c/p>\u003cp>过了一会电话来了：我到中山路52号，你人呢？\u003c/p>\u003cp>我说：是中山北路252号。\u003c/p>\u003cp>他一下怒了：你存心耍我是不是？一会变一个地址。你什么意思？耍我到处跑？\u003c/p>\u003cp>我毫不客气的回道：你自己听错了，你倒发起火，手机在我手里，你爱要不要，就你这态度，我现在把它砸了也不给你。啪，我直接挂断电话。\u003c/p>\u003cp>心想既然地址没听清，干脆一不做二不休把手机扔了，或者砸了，又或者卖了。\u003c/p>\u003cp>去年我老公手机丢了的时候，我们愿意酬谢，对方还是不还，想到这捡手机的人也真是可恨。\u003c/p>\u003cp>今天我捡到手机有心还回去，对方态度还这么差。那我为什么要还？不还！下定决心不还！\u003c/p>\u003cp>就在我快要说服自己的时候，心中有一念闪过，我的良知告诉我不能这么做，因为我知道丢了手机，失去手机里的东西，是有遗憾的。即然有遗憾，我又何必再去传递这种感受呢？这样一来不就和捡我们手机的人一样可恨吗？于是我想到一个既不想与对方纠缠，又能把手机还给他的方法，于是就送到派出所去了。 \u003c/p>\u003cp>所以大家看，这个故事里我正好用了“三步选择冲突法”彰显价值观：\u003c/p>\u003cp>第一步选 有主动选择的场景\u003c/p>\u003cp>比如捡到手机没有被失主的恶劣态度带偏，坚持选择还给他\u003c/p>\u003cp>第二步说 纠结的劲，左右为难的感觉。\u003c/p>\u003cp>被失主气的想砸手机，还吧情理过不去，不还吧心理过不去，陷入赌气不还与坚守良知的两难。\u003c/p>\u003cp>第三步问 为啥这么选，让价值观落地。\u003c/p>\u003cp>选择归还的行为，恰恰让换位思考、不违背同理心的价值观变得更加真实。\u003c/p>\u003cp>简单三步，既理清了自己的选择，也让别人看到了背后的价值，这就是这个方法的实用之处！\u003c/p>","interaction":"\u003cp>【A3】场景应用【10-15】\u003c/p>\u003cp>好，光说不练假把式，接下来我就来练一练。我这准备了一个场景，就用刚刚学习的三步挖掘出冲突彰显价值观。\u003c/p>\u003cp>周末你和闺蜜约好晚上吃饭。可偏偏这时，因同事失误导致标书出现关键错误，领导找你，要求今晚必须修改好明天就要用，你和同事留下来加班。你心里满是不爽，正想发火，这时得知同事的孩子发烧。\u003c/p>\u003cp>一边是和闺蜜的约会，一边是同事孩子生病的急事，再加上标书必须完成的工作责任，你该如何决定？请大家用“有选择-说纠结-问为什么”的逻辑，讲清你做选择背后的原因，让听众理解你的价值观。\u003c/p>\u003cp>演练要求：\u003c/p>\u003cp>对应三步法核心：先明确个人约会vs同事急事+工作责任的核心冲突，再挖掘换位思考、责任担当等内在动因，最后凸显选择时不满与体谅的挣扎过程。\u003c/p>\u003cp>各小组先分工选好角色，讨论时间2-3分钟，时间到我就会玲；之后请一个小组上台演练，既要讲清冲突，又要凸显价值观；其他小组负责观察并做好反馈。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>分享者1：不好意思我突然接到电话，孩子发烧了，我得马上回去\u003c/p>\u003cp>分享者2：啊，那你回去我一个怎么搞啊，而且这本来也不是我负责的，我也是约了朋友临时被你个标书给耽误了，我还推一会议。\u003c/p>\u003cp>分享者1：实在是抱歉，我老婆不在家，老人在家也不会去医院，我去去就回\u003c/p>\u003cp>分享者2：那那怎么办，要不你就去吧，但是有一点你手机一直开着，好有什么问题能找到你。\u003c/p>\u003cp>非常感谢两位伙伴的精彩演练！今天我们核心掌握了一个关键方法，一共三步：一是选有主动选择的场景；二是说出纠结的两难选择；三是问自己为什么这么选。这样就能让你的价值观落地，让表达更有力量。\u003c/p>\u003cp>最后我想说的是：\u003c/p>\u003cp>不是你的故事平淡，而是缺少冲突彰显价值观\u003c/p>\u003cp>没有主动选择，你的坚持就容易被质疑，是不是没得选\u003c/p>\u003cp>无冲突不深刻，无价值不分享\u003c/p>\u003cp>希望大家以后不管是日常沟通、公开分享，还是塑造个人品牌，\u003c/p>\u003cp>都能用这个方法让自己的价值观被看见、被认可、被共鸣！谢谢大家～\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1765810250000,"updated_at":1777466748000,"ria":true},{"id":19540,"topic":"成人达已的卖自己","learn_goal":"","remark":"在《故事力》的视角里，“不会讲故事” 从来不是单纯的 “表达技巧欠缺”，而是背后 “自我为中心” 的思维在作祟 —— 我们总下意识地关注 “我想传递什么”，却忘了问 “对方需要什么”“我的表达能为对方带来什么”。\n在做提案或介绍一款产品，若只站在 “我的产品多好” 的角度，很容易变成生硬的 “推销”；但若是切换到 “这能帮对方解决某个痛点”“能为对方创造某种价值” 的视角，说服力自然加强。再比如争取资源、把握机会时，《故事力》强调的 “知己知彼、成人达己”，本质也是用 “故事” 搭建桥梁：让对方看到 “我们的合作能实现共赢”，而非 “我只是来要资源的”。这种 “以对方为中心” 的故事思维，正是这本书最有价值的地方。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"谢尚袁","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>各位老师、各位拆友，大家好！我是尚袁，上善弱水，广结善缘。\u003c/p>\u003cp>特别开心能站在这里，完成我的 2-3 拆书晋级。\u003c/p>\u003cp>我是一名广告创业者至今已有19年，深耕平面设计领域。\u003c/p>\u003cp>工作之外，我有两个爱好，帮我解决了不少实际问题，第一个是学习中医，从21年开始学习中医小儿推拿、刮痧、艾灸。为二宝调理体质弱问题以及调理父母的慢病问题。第二个爱好是皮肤管理达人：生活里熬夜造成脸垮、皮肤粗糙、显老。我用刮痧+面部精油做护肤，这才让40+的我常被人当成30+的人。\u003c/p>\u003cp>这看似两个并不交集的职业，却恰好平衡了我生命的重量和质量，一手抓工作，一手抓健康。\u003c/p>\u003cp>【分组】一个桌子为一组\u003c/p>\u003cp>前面XX老师已做了分组，我们就保持这个组型\u003c/p>\u003cp>【FAB】介绍本书：\u003c/p>\u003cp>\u003cu>现在开始介绍我今天要讲的书《故事力》\u003c/u>\u003c/p>\u003cp>F:作者是高琳，一位留美理科生博士。这里特别提到“理科生”的身份，主要有两个信息：一是因为理科生通常更专注于分析和研究，较少需要去讲故事。二是理科生都开始讲故事了，说明这讲故事能力真的很重要。更加证明了这项能力并非是少数人的天赋，人人都能学的会。\u003c/p>\u003cp>书里有心理学知识，还有实际例子，告诉你怎么编故事、不管工作还是平时聊天，都能通过故事达成目标。\u003c/p>\u003cp>A:这本书好就好在，给了多个“故事模型”，把那些难懂的理论变成了能直接套用的步骤。\u003c/p>\u003cp>\u003cu>书再好它与我们有什么关系？\u003c/u>\u003c/p>\u003cp>B \u003c/p>\u003cp>我相信每个人都有过这样的体验：有人在做汇报的时候说个不停，让人不耐烦听不进去；费劲吧啦的埋头干活，到了升职的时候却不是你？在公众场合发表进话时，语无伦次没有逻辑和重点，听众听的是一头雾水？\u003c/p>\u003cp>其实这都是因为不会“用故事想事”。人天生就爱听故事。要是因为说话太硬错失机会，因为只会干不会说而不被看见，因为说不明白没说服力，你就会发现：不是你不够努力，是你不不知道，卖力不等于说服力，说服力要有故事力，这本书就是唤醒我们尘封已久的故事思维，打开对表达认知的封印。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>今天学习的目标是带着大家学会，如何用“雪中送炭”式故事模型的4步法，成人达已卖自己。\u003c/p>","ratings_count":2,"texts":[{"id":23932,"quote":"\u003cp>\u003cstrong>雪中送炭的故事：将你的提案说到对方的心里\u003c/strong>\u003c/p>\u003cp>每个人都生活在自己的故事里，当你试图“卖”一个观点给对方的时候，就意味着你的故事和对方的故事需要有一个交集。否则你再怎么讲你的故事也是自说自话。在这个交集里，你需要讲一个以对方为中心的故事，这个故事模型，我们叫它“雪中送炭”，这个模型几乎适用于任何销售场景，包括给老板“卖”自己的观点。\u003c/p>\u003cp>所谓雪中送炭，就是听众本来一切顺利，有一天突然发生了什么，导致他面对困难，然后你来帮助他的故事。这个故事和其他故事最大的不同就是，讲故事的你不是故事的主人公，听的人才是。在下雪天，你是那个送炭的人。\u003c/p>\u003cp>所以，雪中送炭的故事模型具体来讲是这样的（见图6）：\u003c/p>\u003cp>- 背景：主人公本来有的一个目标\u003c/p>\u003cp>- 冲突：达成这个目标遇到了或者会遇到什么样的阻碍\u003c/p>\u003cp>- 解决冲突：雪中送炭，提出克服阻碍的解决方案\u003c/p>\u003cp>- 完美结局：这个方案能够带来什么样的结果\u003c/p>\u003cp>在之前几章的故事里，我们都在讲你是如何克服万难成为英雄的。可是在这个故事里，你的老板，你的利益相关者，才是那个英雄，你只是帮他们克服冲突、实现目标的那个人。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>WHAT:不过，在讲方法之前，我想先跟大家互动一下：大家刚才看的拆页，有没有觉得有点绕？或者某个地方没看明白的？可以举手示意一下 —— 没关系，有疑问很正常。​\u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>大家是不是有这样的疑问，如果一个方案好或者一个产品本身也很棒，咱们把它讲清楚不就行了吗？对方难道不会自己判断吗？还怕他不选吗？​\u003c/p>\u003cp>能这么想，说明你已经是个合格的 “解说员” 了 —— 把观点、产品讲明白，这是基础。再往深处想一想：人家凭什么要听你讲？你的方案再好、产品再棒，那是你认为，跟我有什么关系？ ​\u003c/p>\u003cp>今天通过这个拆面，就是把 “凡事只想着自己” 的沟通习惯给改过来，转成 “为对方着想”这最是拆页里讲的 “交集”。要是你的故事和对方的需求没交集，你说再多，都是自说自话，都是 “我觉得好”，可对方根本不感兴趣。\u003c/p>\u003cp>​\u003c/p>\u003cp>打个比方这种 “以对方需求为中心” 的逻辑，其实很像古代君臣之间的关系：辅佐皇帝的大臣，写的每一份奏折、提的每一条建议，核心都是帮皇帝排忧解难。最常见的场景就是：国家边境被匈奴侵犯，作为大臣，你要建议皇帝如何知人善用、招贤纳才，或是直接举荐人才。皇帝采纳你的建议后，结果胜利了赶走了匈奴、守住了疆土，百姓得以安居乐业。而皇帝的声望也因这份功绩更高，百姓更拥戴这位君主，大臣的建议最终帮皇帝成就了千秋霸业 ， 这正是 “以对方需求为核心”，最终在成就对方。\u003c/p>\u003cp>在学习中也常听人说 “最好的成交就是成就对方”，以前我总不明白这句话的意思，直到看了《故事力》里这个片段，才彻底懂了。说白了，就是三句话：“找到对方的问题，帮对方解决问题，最后成就对方”。也称之为“以对方为中心的共赢三步法”：​\u003c/p>\u003cp>HOW：举个例子，我现在手里有款面膜，我现在用向你们销售。\u003c/p>\u003cp>第一步，找到问题（产品多，没效果，敏感机，泛红，干痒）\u003c/p>\u003cp>您是不是也有这种感觉？现在市面上的面膜太多了，挑的时候特别费劲，而且大家对功效的要求也越来越高。想找一款真正适合自己、用着放心又有效的面膜太难，有时候试了好几款，不是没效果，就是用着不舒服。其实我们这款新出的面膜，不少敏感肌的朋友用了都特别惊喜，说终于找到合适的了。”—— 你看，这样说，就是先跟客户的痛点对齐。​\u003c/p>\u003cp>第二步，解决问题。（深层修护、舒缓敏感，解决泛红干痒，稳定皮肤的耐受度，皮肤水润）\u003c/p>\u003cp>咱们这款面膜主打的就是‘深层修护、舒缓敏感’，里面有专利的修护成分，您皮肤泛红、干痒的时候，敷一片就能明显感觉到舒服；而且它特别温和，敏感肌用着也安全。您要是用了，每次敷完都会觉得皮肤水润润的，状态特别稳定；长期用下来，皮肤的耐受度也会提高，以后再用其他功效型的护肤品，也不容易出问题了。”—— 这里不说 “我们的产品多好”，只说 “能帮你解决什么问题”。​\u003c/p>\u003cp>第三步，成就对方。（省钱，安心，年轻）\u003c/p>\u003cp>客户得到什么好处，您之前肯定也试过不少面膜，要么没效果，要么用着还刺激皮肤，糟心又浪费钱。但咱们这款面膜，能让您不用再瞎折腾，安心护肤，慢慢拥有健康稳定的好皮肤，谁看到你都觉得你皮肤好人年轻，不像实际年龄的人，比如你看我。\u003c/p>\u003cp>其实不管是卖面膜，还是跟人沟通、做销售，核心都一样：多观查问题是什么？咱们的目标，是帮对方解决问题，帮助对方扫除障碍，让对方获益。这就是雪中送炭模型。\u003c/p>\u003cp>这里也要特别强调一下其中的一个细节，就是你的初心一定是与对方的需求是匹配，不带半点虚假。不然就像早期的卖保险的阿姨们为了销售而销售，不惜吹高产品的功能，最后的结果是成就了自己，害了别人，让人对保险失去了信任，这不是保险不好，而说的人不对，一是先成人后达已。​\u003c/p>","interaction":"\u003cp> 【分步催化】\u003c/p>\u003cp>1. 现在请大家想想，马上中秋国庆了，你准备给你的闺蜜推荐一款礼品，或是一条旅游线路，现在请大家想好场景，记住先是想场景，在小组内交流一下。\u003c/p>\u003cp>2. 或者是你身体出现了什么亚健康，你推荐他如何去调理。好，现在请大家运用今天学习的“以对方为中心的共赢三步法”来进行分享。\u003c/p>\u003cp>到时我请一个小伙伴来分享一下。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>分享者1：我最近脖子有点不舒服，酸痛\u003c/p>\u003cp>分享者2：我知道有一家养生的店对治疗这块有很好的效果，你是不是做的太久了，这种情况非常常见我也是这样\u003c/p>\u003cp>分享者1：靠谱吗？没做不太敢做\u003c/p>\u003cp>分享者2：我就是做了现在恢复了，身上一点也不痛了，他就是以找准穴位，精准按压，很快就能解决你的问题。正好我这里还有卷送给你。\u003c/p>\u003cp>分享1：那太谢谢了\u003c/p>\u003cp>好的感谢大家的分享，希望今天的“雪中送炭”式的故事模型，看到问题，解决问题，成就他人共赢三步法，在你行径的途中带来意想不到的惊喜。谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1765810113000,"updated_at":1777466760000,"ria":true},{"id":19539,"topic":"故事力","learn_goal":"","remark":"《故事力》：3步讲好故事，被看见！","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"谢尚袁","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>大家好，我是尚袁\u003c/p>\u003cp>今天是我的2-1的拆书晋级，感谢现场所有伙伴们的陪伴\u003c/p>\u003cp>我是一名广告创业者，已有19年，从事平面设计行业，现在开始用AI+品牌设计。\u003c/p>\u003cp>工作之外我也是一位中医爱好者：学习中医4年,我用推拿艾灸为二宝调理体质，解决因体质弱引起的感冒发烧咳嗽等情况。最近又用中医办法，不手术，慢慢把小儿疝气也调回来了。在生活里我是个爱美的皮肤管理达人：\u003c/p>\u003cp>生活里，我还爱臭美。熬夜脸垮、粗糙、显老？我靠面部刮痧加护肤，40 多岁常被当成 90 后。这套方法也帮了不少身边朋友，皮肤眼见着变亮起来。\u003c/p>","ratings_count":2,"texts":[{"id":23931,"quote":"\u003cp>故事的黄金原则：如何让故事的3个层次服务于核心思想\u003c/p>\u003cp>故事之所以不容易讲好，因为它是有层次，多维度的。一个好的故事应该有这样3个层次：表现形式、表现内容和价值观\u003c/p>\u003cp>- 价值观（Why）：故事的核心就是它所体现的中心思想以及所代表的价值观。这才是一个故事的灵魂。相信大家都听说过这样一句话：好看的皮囊太多，有趣的灵魂太少。其实很多人骨子里是很有趣的，只是自己的故事没讲好，没有让人看出来。\u003c/p>\u003cp>- 表现内容（What）：故事的内容指的就是讲了什么，它们是如何通过一定的架构和逻辑层次呈现出来的，使得听众理解故事的价值观。\u003c/p>\u003cp>- 表现形式（How）：故事的表现形式指的是这个故事是怎么讲的，它主要体现在讲故事的人在讲述过程中的语音语调、眼神、肢体语言等的使用是否支持了讲故事的目的。\u003c/p>\u003cp>很多来找我们教练演讲的高管客户都希望我们能帮他们把演讲变得很精彩，甚至成为乔布斯那样的。他们理解的精彩基本是通过故事的外在表现形式体现出来的。这固然重要，但故事的表现内容和它的核心价值观才是决定一个故事是否能真正影响到它的受众的关键。\u003c/p>\u003cp>因此，故事的表现内容和表现形式一定需要服务于这个核心思想，并且以终为始地选择相应的故事素材。这就是讲故事的黄金原则。\u003c/p>\u003cp>很多人的故事之所以讲不清楚，产生歧义，没有实现想要的影响目的，是因为他们构思故事的顺序反了，也许他们是先有了一个故事素材，然后再想自己要表达什么，或者根本就是随机地选取一些故事素材，按照时间发生顺序罗列一下。这样对讲的人来说倒是很容易，但是对听的人来说，他们很难理解背后的中心思想。\u003c/p>\u003cp>故事的中心思想固然重要，但好的故事一定是鲜明地树立了观点且不点破观点，让听众自己得出结论。\u003c/p>","explains":"\u003cp>what：\u003c/p>\u003cp>想要讲好一个故事，讲的生动，必须包含三个层次：价值观、表现内容和表现形式。价值观是决定一个好故事的灵魂， 也就是故事的中心思想，通过设计内容案例和表现形式来完成价值观的传递，最终影响听众。\u003c/p>\u003cp>可以这样理解：价值观如同身体的主干，表现内容和表现形式则像左右双腿，只有双腿协同行走，才能抵达价值观的目标。\u003c/p>\u003cp>不那么做的坏处： \u003c/p>\u003cp>【通常做法】你会发现，一般人一开口就容易犯两种毛病：要么东拉西扯，没重点；要么像报流水账，听众听完还是一头雾水。\u003c/p>\u003cp>【这么做的坏外】这样做导致自己思路不清晰讲不清楚，听众也听不清楚，达不到沟通的效果。\u003c/p>\u003cp>【A1反例】我有一次参加育儿讲座，被点名发言：“怎么把‘不写作业母慈子孝，一写作业鸡飞狗跳’变成‘母慈子孝’？”\u003c/p>\u003cp>我当时是这么说的：\u003c/p>\u003cp>“我也有这痛点。那天我让儿子写字，他死活不动笔，我火一上来，甩门就走。孩子当场大哭。晚上回家，他跑来跟我道歉，我也觉得自己太冲动，毕竟是亲生的，不能总发火，得先改自己。”\u003c/p>\u003cp>说完我自己都觉得空： 我想表达的核心是啥？没点明。 听完大家能学到啥？没有。\u003c/p>\u003cp>这就是典型的“无效发言”：没价值观、没提炼、没方法，只剩一腔情绪和一段流水账。\u003c/p>\u003cp>那到底如何做呢，原文提供了讲故事三层次的方法就非常有用。\u003c/p>\u003cp>【how】： \u003c/p>\u003cp>讲故事三层次方法是这样的：\u003c/p>\u003cp>1. 定价值观-中心思想（想表达啥）\u003c/p>\u003cp>2. 选内容-内容细节（咋说）\u003c/p>\u003cp>3. 呈现方式-语音语调＋动作（咋演）\u003c/p>","interaction":"\u003cp>【A1反例】我有一次参加育儿讲座，被点名发言：“怎么把‘不写作业母慈子孝，一写作业鸡飞狗跳’变成‘母慈子孝’？”\u003c/p>\u003cp>我当时是这么说的：\u003c/p>\u003cp>“我也有这痛点。那天我让儿子写字，他死活不动笔，我火一上来，甩门就走。孩子当场大哭。晚上回家，他跑来跟我道歉，我也觉得自己太冲动，毕竟是亲生的，不能总发火，得先改自己。”\u003c/p>\u003cp>说完我自己都觉得空： 我想表达的核心是啥？没点明。 听完大家能学到啥？没有。\u003c/p>\u003cp>这就是典型的“无效发言”：没价值观、没提炼、没方法，只剩一腔情绪和一段流水账。\u003c/p>\u003cp>那到底如何做呢，原文提供了讲故事三层次的方法就非常有用。\u003c/p>\u003cp>【how】： \u003c/p>\u003cp>讲故事三层次方法是这样的：\u003c/p>\u003cp>1. 定价值观-中心思想（想表达啥）\u003c/p>\u003cp>2. 选内容-内容细节（咋说）\u003c/p>\u003cp>3. 呈现方式-语音语调＋动作（咋演）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1765809133000,"updated_at":1777466798000,"ria":true},{"id":18532,"topic":"邀功三步法","learn_goal":"","remark":"掌握“邀功三步法”，让领导和同事看到你的付出\n让你的辛勤工作得到应有的认可和回报，不再默默无闻","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"kkk-cq","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>开场白\u003c/strong>\u003c/p>\u003cp>大家好，欢迎大家来到今天的拆书活动。我是KKK，我用数字法123来介绍一下自己。\u003c/p>\u003cp>1——一门心思提升自己学习能力\u003c/p>\u003cp>2——两个身份，新能源行业售前工程师+拆书帮1级拆书家\u003c/p>\u003cp>3——三个爱好，看书、炒股、跑步\u003c/p>","ratings_count":1,"texts":[{"id":22840,"quote":"\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>如果结合\u003cstrong>她老板为人处世的风格\u003c/strong>，她的故事就可以这么讲：\u003c/p>\u003cp>我们这次现场\u003cstrong>签约80人，比往年的结果都好\u003c/strong>；\u003cstrong>还有50人一周内签订合同寄回，估计85%可以签约\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>不过，这次招聘还真的不容易\u003c/strong>，扩招之后毕业生比预计的多了近一倍，我们团队4个人，连吃饭喝水的时间都没有……最后回来的时候，我们的飞机还两次发生故障，迫降太原。我都差点儿以为不能回来了。\u003c/p>\u003cp>这次团队的所有人都辛苦了，\u003cstrong>您可得请大家吃饭犒劳犒劳\u003c/strong>。\u003c/p>\u003cp>这么一说，既\u003cstrong>让老板知晓自己想要的结果\u003c/strong>，也\u003cstrong>让他了解到团队付出的艰辛\u003c/strong>，继而\u003cstrong>点明了自己期望得到的认可方式\u003c/strong>。如果我是老板，一定立刻就会请团队吃大餐。\u003c/p>","explains":"\u003cp>\u003cstrong>【过渡语】\u003c/strong> \u003c/p>\u003cp>现在，正式进入今天的拆书环节。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>我们今天的\u003cstrong>学习目标是：应用“邀功三步法”，演练费劲千辛万苦收回账款后给领导汇报的情景。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了更好的练习，下面先进行分组，就按现在的座位2个人1组，待会就按分好的组进行讨论演练。\u003c/p>\u003cp>\u003cstrong>【图书及作者介绍（FAB介绍法）】\u003c/strong>\u003c/p>\u003cp>这个片段来源于《故事力》这本书。\u003c/p>\u003cp>\u003cstrong>F（特点）\u003c/strong>\u003cem>：\u003c/em>这本书是高琳博士和他老公写的，他们长期给世界500强做咨询工作，擅长用讲故事的方式去影响别人，杨澜和潘石屹都在推荐这本书。\u003c/p>\u003cp>\u003cstrong>A（优势）\u003c/strong>\u003cem>：\u003c/em>案例丰富，通俗易懂，在微信读书里面推荐值78.8%，而另外一本关于讲故事的书，也是罗胖强烈推荐的《故事课》的推荐值只有68%。\u003c/p>\u003cp>\u003cstrong>B（益处）\u003c/strong>：书中的方法可以方便的迁移到我们工作或生活中，通过讲故事的方式比干巴巴的谈数据或讲道理更能影响别人。学习这个片段后，可以让我们的辛苦得到领导的认可。\u003c/p>\u003cp>\u003cstrong>知识点重述（I环节）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这个片段介绍了一个在我们完成一项比较有难度或挑战的任务后，给领导进行汇报的方法，即“邀功三步法”。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>在工作中，当我们完成一项比较有挑战或高难度任务，但当我们满怀欣喜向领导汇报，如果希望获得他的肯定。如果我们只告诉领导一个结果，他可能只会简单的回复“知道了”。我们会认为领导不通人情，不理解我，会觉得委屈。根本原因在于领导感受不到我们背后所经历的艰辛和痛苦，所以打动不了领导的。\u003c/p>\u003cp>那么“邀功三步法”具体要怎么做呢？\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>原文中没有给出具体的行动步骤，我们来根据案例进行了\u003cstrong>细化行动步骤\u003c/strong>：\u003c/p>\u003cp>第一步，原文说的是“签约80人，还有50人一周内签订合同寄回，估计85%可以签约”，这一步可以细化为“报功劳“”，就是告诉领导事情结果，就是告诉他，这个事儿“搞定了”。\u003c/p>\u003cp>第二步：他告诉领导“”这次招聘还真的不容易，差点回不来了“，可以细化为“诉苦劳“，就是告诉领导我们背后遭遇的困难和挫折，告诉领导“出事了”，让领导明白事情的不简单，过程中的不容易。\u003c/p>\u003cp>第三步：他给领导说“您可得请大家吃饭”，这步可以细化为“要酬劳“，就是告诉领导，需要给我一些奖励了。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>我给大家举个案例，我最近在做一个项目，当时领导让我帮忙测算一个项目数据，他说得很简单，“帮我分析两种情况：单班和双班，夏季和冬季“，看起来工作量不大，其实这事非常复杂，花了我好多时间。这事做完后，我给他的汇报。\u003c/p>\u003cp>第一步：报功劳，我对领导说：“廖总，这个数据已经测完了，各种情况都给你分析好了，数据都在这个文件里面”。\u003c/p>\u003cp>第二步：诉苦劳，这个事儿好复杂，其实是要考虑16种情况下的测算，单班与双班，冬季与夏季，有光伏与没光伏，现在和明年增加负荷后的情况。这样组合下来，其实有2的4次方，一共16种情况，我花了10个小时，才全部弄出来了，头都大了。”\u003c/p>\u003cp>第三步，要酬劳，我说“这事搞得我精疲力竭，能不能让我休息一下？把华能那项目的标书让其它同事做一下。”\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>这个方法适合我我们认为自己完成了一个有难度或挑战的工作，想要获得领导认可和激励。\u003c/p>\u003cp>但具体应用中也需要根据老板风格来用，如果老板只管结果不管过程就不适合。同时需要结合具体情景，如果领导心情不好，他就认为他自己都不容易，你也不适合去邀功劳。\u003c/p>","interaction":"\u003cp>【\u003cstrong>场景设计\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>背景:\u003c/strong>我们来设想一个场景，小张是一个公司销售，一天你们领导王总让你写去找客户收款，老板轻描淡写的说“他们公司老板和我是兄弟伙，我已经和他谈好了，你直接去找他们要钱就行了”。\u003c/p>\u003cp>困难：但小张去了之后，发现根本不是这么一回事，对方就是以各种理由不给钱。\u003c/p>\u003cp>结果：最后费劲千辛万苦，终于把钱要回来。\u003c/p>\u003cp>目标：小张想让王总知道他背后付出的艰辛和努力，去王总那里邀功。\u003c/p>\u003cp>【\u003cstrong>小组讨论演练\u003c/strong>】\u003c/p>\u003cp>现在，请每两个人一组，在组内进行演练。一个人扮演小张，你主动找领导王总，应用表功三步法来汇报成果，你可以丰富更多细节；一个人扮演王总。\u003c/p>\u003cp>演练时间3分钟，现在开始。3分钟后，我会选一位“小张”和一位“王总”，大家一起听听他们是怎么应用表功“三步法”。\u003c/p>\u003cp>【\u003cstrong>角色扮演\u003c/strong>】\u003c/p>\u003cp>下面我请两个伙伴来演练一下。由寒睿扮演小张，涛涛扮演王总，你们来演练这个方法。\u003c/p>\u003cp>寒睿（小张）：（报功劳）王总你好，A公司的200万账款我收回来了。（诉苦劳）这次收款可真不容易呀，我去了之后，对方就是不给钱，我天天上门催，天气又冷，天寒地冻的我去送礼请客，有次还差点出车祸了。（要酬劳）年底我的绩效您可得帮我打高点。\u003c/p>\u003cp>王总（涛涛）：辛苦了，真不容易。年底绩效的是我会考虑的，我到时候给人资部门说一下。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>以上就是我分享的全部内容，主要介绍了通过“邀功三步法””模型来汇报成功。希望以后工作中能用这个方法，让我们的付出都能得到应有\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1735897269000,"updated_at":1735996248000,"ria":true},{"id":18349,"topic":"塑造故事三步法","learn_goal":"","remark":"塑造故事三步法","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"kkk-cq","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp> 大家好，欢迎大家来到今天的拆书活动。我是KKK，我用三个标签来介绍一下自己。\u003c/p>\u003cp>爱吃-爱吃各种好吃的，无肉不欢；\u003c/p>\u003cp>爱看-爱看各种有趣的书，尤其历史类的；爱跑-爱跑步锻炼身体，每周都要跑。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong> \u003c/p>\u003cp>现在，正式进入今天的拆书环节。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>我们今天的\u003cstrong>学习目标是：大家能应用雪中送炭模型，现场加工出一个工作或生活场景中，争取领导/同事/爱人支持的话术\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>为了更好的练习，下面先进行分组，就按现在的座位2个人1组，待会就按分好的组进行讨论。\u003c/p>\u003cp>\u003cstrong>【图书及作者介绍（FAB介绍法）】\u003c/strong>\u003c/p>\u003cp>这个片段来源于《故事力》这本书。\u003c/p>\u003cp>\u003cem>\u003cstrong>F（特点）\u003c/strong>：\u003c/em>书中介绍了3种常见的故事模型，并针对面试、工作汇报、销售、教导等8个关键应用场景提供了具体指导。\u003c/p>\u003cp>\u003cem>\u003cstrong>A（优势）\u003c/strong>：\u003c/em>这本书的优势在于理论与案例的结合。作者是留学博士，并且长期给世界500强做咨询工作，有大量与人沟通经验，很少能像这本书一样，将力量与案例如此紧密地结合在一起，让我们学了之后立马能应用到实际工作生活中。\u003c/p>\u003cp>B（益处）：通过学习这本，我们可以显著提升自己的表达和说服能力。学习这个片段后，可以让别人心甘情愿的支持我们的建议。\u003c/p>\u003cp>【过渡语】\u003c/p>\u003cp>接下来，让我们先来阅读一下原文片段。我给大家1分半钟时间，大家看完后可以抬头示意。\u003c/p>","ratings_count":1,"texts":[{"id":22634,"quote":"\u003cp>每个人都生活在自己的故事里，当你试图“卖”一个观点给对方的时候，就意味着你的故事和对方的故事需要有一个交集。否则你再怎么讲你的故事也是自说自话。在这个交集里，你需要讲一个以对方为中心的故事，这个故事模型，我们叫它“雪中送炭”，这个模型几乎适用于任何销售场景，包括给老板“卖”自己的观点。\u003c/p>\u003cp>所谓雪中送炭，就是听众本来一切顺利，有一天突然发生了什么，导致他面对困难，然后你来帮助他的故事。这个故事和其他故事最大的不同就是，讲故事的你不是故事的主人公，听的人才是。在下雪天，你是那个送炭的人。\u003c/p>\u003cp>所以，雪中送炭的故事模型具体来讲是这样的（见图6）：\u003c/p>\u003cp>◆ 背景：主人公本来有的一个目标\u003c/p>\u003cp>◆ 冲突：达成这个目标遇到了或者会遇到什么样的阻碍\u003c/p>\u003cp>◆ 解决冲突：雪中送炭，提出克服阻碍的解决方案\u003c/p>\u003cp>◆ 完美结局：这个方案能够带来什么样的结果\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>这个便签是一个我们向领导要资源或同事要支持的沟通模型-“雪中送炭”。\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>我们在工作中做提案的时候，最容易出的问题是站在自己的立场来说，比如，想去参加一个培训，往往给领导说“培训机构多厉害、培训师多厉害”，但领导感觉不到你去培训之后他有什么关系，他能从中得到什么好处，能帮他解决什么问题，所以很难说服他同意你去。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>那应该怎么做呢？我用医生看病过程来比方，介绍雪中送炭模型的四个步骤。\u003c/p>\u003cp>第一步：望“初心”，对方最初的期望或目标是什么？比如想业绩增长，利润增加或降低成本。\u003c/p>\u003cp>第二步：探“病症”，给他介绍目前遭遇到什么困难或麻烦，让最初的目标难以实现。\u003c/p>\u003cp>其实就是告诉对方“你有病”，接下来就是第三步。\u003c/p>\u003cp>第三步：开“药方”，这步就是“我有药”，抛出我们的方案去克服前面困难。\u003c/p>\u003cp>第四步：谈“疗效”，描绘“药到病除”的效果，吃了我的药之后，腰不痛了，腿不酸了，把美好结果给他描绘出来。\u003c/p>\u003cp>\u003cstrong>【案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我想这个月末去苏州参加一个行业培训，需要3天时间，和差旅费，但又担心领导不让我去，因此我准备用雪中送炭模型来申请。\u003c/strong>\u003c/p>\u003cp>第一步：望“初心”，我首先回顾了公司的目标：想把工商业储能业务当做我来发展的重点。\u003c/p>\u003cp>第二步：探“病症”，然后，我指出了我们面临的挑战：我们搞了一年多，对于这块业务到底怎么做还很模糊，因此这块业务始终没有起色，这就是我们需要解决的问题。\u003c/p>\u003cp>第三步：开“药方，我参加培训，了解别人是如何做的。\u003c/p>\u003cp>第四步：谈“疗效”，我描绘结果，有可能给公司找到业务打法，或找到新的市场方向。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>书中说的是这个方法适合于各种销售场景，包括销售自己的观点。\u003c/p>\u003cp>我认为在对方“没有义务支持”我们的场景下比较适合，而对于对方有义务支持我们的情况，只需要提出需求即可。\u003c/p>\u003cp>比如我一个朋友在一个汽车零部件企业公章，他负责公司的生产运营，手下有500来号人，他对他的手下要求的跨部门沟通的方法就是“不要有站在对方立场考虑问题，直接提出需求，然后大家来想办法解决即可“。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>这个方法最关键的核心是我们考虑问题要站在对方的角度，\u003cstrong>有人可能会说：“我确实不知道知道对方的需求，在第一步“望初心”的时候就不知道，那咋办？”。\u003c/strong>\u003c/p>\u003cp>这种情况下，根据书中的方法可以采用三种方法了解对方的需求：\u003c/p>\u003cp>第一沟通了解，就是聊天过程中问。\u003c/p>\u003cp>第二，是研究资料法，查找领导的KPI是什么？为了达成目标你能帮他做什么。\u003c/p>\u003cp>第三，综合验证，综合前两种方法，反复验证自己想法。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2分步催化-场景】\u003c/strong>\u003c/p>\u003cp>在我们开始之前，\u003cstrong>我想请大家思考一下，未来一个月内工作或生活中可能遇到需要别人帮助或支持我们的场景\u003c/strong>。比如：\u003cstrong>申请经费、汇报提案、教育孩子\u003c/strong>等。请大家花一分钟时间，将这些场景写在便签上。\u003c/p>\u003cp>\u003cstrong>【学习者芳芳分享场景】\u003c/strong>\u003c/p>\u003cp>申请调岗，换新岗位位后有些不适用，希望领导让她回到原工作岗位。\u003c/p>\u003cp>\u003cstrong>【A2分步催化-加工案例】\u003c/strong>\u003c/p>\u003cp>现在，\u003cstrong>请大家根据刚才想到的场景，应用雪中送炭模型的四步法，去说服对方，大家把话术写下来\u003c/strong>。\u003c/p>\u003cp>我给大家准备好了表格，大家可以参考我前面分享的案例，来加工自己的话术。大家把关键词写在自己纸上，我给大家2分钟时间。\u003c/p>\u003cp>好了，时间到了，我们请个朋友来分享一下，1分钟时间。\u003c/p>\u003cp>\u003cstrong>【学习者芳芳分享案例】\u003c/strong>\u003c/p>\u003cp>第一步：望“初心”，领导进行岗位调整是为了发挥每个人的价值，让公司更好的发展；\u003c/p>\u003cp>第二步：探“病症”，方方换到新岗位之后，并没有带来预期中的价值；\u003c/p>\u003cp>第三步：开“药方”，转回原岗位；\u003c/p>\u003cp>第四步：谈“疗效”，之前的经验加上最近的经验，能更大化发挥自己的价值，帮助公司发展。\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>以上就是我分享的全部内容，主要介绍了通过“雪中送炭”模型来兜售我们的“观点”。希望以后工作或生活中能用这个方法，帮到大家提高说服力，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1731840736000,"updated_at":1734440013000,"ria":true},{"id":17959,"topic":"如何讲动力故事？","learn_goal":"","remark":"故事是成本最低的说服方式，社交场合、求职面试、述职演说、创业路演、转型转行、甚至相亲都需要我们具备故事力，会讲故事的人将会统治世界，如何用故事决胜人生关键时刻，只需这几步……","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"醉人书香","city":"鹤壁市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>各位亲爱的小伙伴，我叫魏士军，我的三个标签是小学老师、八段锦爱好者、写作探索者。\u003c/p>\u003cp>在今天的学习中，会有讨论环节，因此我们在场的小伙伴，我们先进行一下分组（腾讯会议系统完成分组）左手边的分为1组，右手边的分为1组，便于后面的交流。\u003c/p>\u003cp>今天我给大家分享的内容来自高琳的《故事力》这本书中的片段。\u003c/p>\u003cp>故事力体现了人类的高度智慧，它是一个人情商、沟通力、领导力，战略性思维等综合能力的体现，两位作者拥有20年的世界500强的咨询实战经验。\u003c/p>\u003cp>这是一本实战性而非理论性的书，这本书运用了大量实例阐述讲故事的重要性。提炼出了讲故事的3大标准和6大要素。总结出了6个人人都需要故事模型，落实到8大职场应用场景。\u003c/p>\u003cp>这本书适合以下人阅读，有进取心的职场人，想打造个人IP的人，想要转型、转行或重新出发的人，创业者，领导者，企业家，高管，父母及教育工作者等。\u003c/p>\u003cp>今天我给拆解的片段出自高琳的\u003cstrong>《故事力》-\u003c/strong>-----如何讲动力故事。下面大家先看一下片段原文，时间为2分钟，看完之后可以在对话框页面打出数字“1”。\u003c/p>","ratings_count":2,"texts":[{"id":22197,"quote":"\u003cp>如何讲动力故事--------《故事力》p344----345\u003c/p>\u003cp>“我为什么......”的故事模型（动力的故事）应用场景：社交场合，求职面试，述职演说，创业路演，转型转行。\u003c/p>\u003cp>因为发生了 （触发事件）\u003c/p>\u003cp>所以 成为我的动力\u003c/p>\u003cp>让我热爱（想要） \u003c/p>\u003cp>即使面对 （困难/冲突）\u003c/p>\u003cp>让我感觉 （负面情绪）\u003c/p>\u003cp>我还是坚持 （体现这个动力的行为和结果）\u003c/p>\u003cp>例1（简单粗暴版）：因为我出生在一个偏僻的小山村，所以好好学习走出大山成了我的梦想。这也让我爱上了读书，即使图书馆的资源非常有限，我需要步行10公里到县城图书馆才能借到书，感觉非常不方便，也很累，但我还是坚持每个周末去图书馆借书学习，所以最后才考上了大学。\u003c/p>\u003cp>例2（自然版）：我家里有5个妹妹，我们一家8口人挤在纽约皇后区的贫民区。（触发事件）为了改善全家的生活（动力），我念大学的时候就开始创业挣钱，开发了这款产品。有一段时间，资金链出了些问题，我们全家把所有的存款都拿出来垫上了，全家人一顿就吃一个比萨。（困难/冲突）但我们坚信，这个公司是我们全家的希望，它一定能够好起来。后来，经过产品迭代，公司再次走上正轨。这个公司对于我和我的家人真的非常重要。（体现这个动力的行为和结果）\u003c/p>\u003cp>\u003cstrong>（所选拆页中包含有具体的行动或做法）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>练习\u003c/strong>\u003c/p>\u003cp>第一步：确定我想要凸显的动力。 （选择内在动力）\u003c/p>\u003cp>第二步：反思自己为什么会有这样的动力？它是由什么触发的？ \u003c/p>\u003cp>第三步：选择哪个冲突能很好地体现这个动力？ \u003c/p>\u003cp>第四步：那个冲突给我带来的负面感受是什么？ \u003c/p>\u003cp>第五步：你最后做了什么？实现了什么结果？ \u003c/p>","explains":"\u003cp>What：上述片段主要讲了如何讲好“动力故事”\u003c/p>\u003cp>Why：掌握了这种方法，面试时讲好故事，面试官认为你就是他要找的那个人；销售时讲好故事，客户就能心甘情愿地埋单；工作汇报时讲好故事，能让领导立刻认可你，甚至能给你升职加薪的机会，这种方法能提高他人对你的信任度，且具有较强的操作性。\u003c/p>\u003cp>\u003cstrong>1）行动建议步骤\u003c/strong>\u003c/p>\u003cp>How：片段给出的具体方法步骤如下：\u003c/p>\u003cp>第一步：叙述自己的动机，并解释动机的来源是什么？为什么自己会有这样的动机。\u003c/p>\u003cp>第二步：在达成自己动机的过程中遇到的困难或冲突是什么，这个冲突给我带来的负面感受是什么？ \u003c/p>\u003cp>第三步：你做了什么，后来达到什么样的结果？\u003c/p>\u003cp>Where：这种方法适合以下应用场景：社交场合，求职面试，述职演说，转型转行，创业路演。\u003c/p>\u003cp>\u003cstrong>2）与行动各步骤对应的案例\u003c/strong>\u003c/p>\u003cp>今年3月份，在入会之前，我参加了拆书帮的面试，我是这样讲自己的动力故事。\u003c/p>\u003cp>第一步，在读书的过程中，一直有一个困惑，如何把读到的书转化成生产力，如何通过读书提升解决问题的能力，让自己变得更好。通过了解拆书帮的理念与方法正好能满足我这种需求，为了解决这种困惑，我决定加入拆书帮。\u003c/p>\u003cp>第二步，要加入拆书帮需要满足一定的条件，要参加训练营，并且按时提交作业，那段时间，家中遇到了一些突发事件需要去处理，既要做好自己的本职工作，又要学习新内容并提交作业，让我有点难以招架，在以上动力的支持下，我克服各种困难，终于坚持下来了。\u003c/p>\u003cp>第三步，经过自己的努力，我终于通过了面试，成了拆书帮会员。\u003c/p>","interaction":"\u003cp>刚才我们一起探讨了如何讲一个“动力故事”，那么请各位小伙伴想一想自己有没有经历过类似情境、失败或成功的经验，比如在考公考编面试的时候、求职的时候，竞争某个岗位的时候，请你按照刚才的分组，和组内的伙伴交流分享，时间为3分钟，时间到之后，我会邀请一位代表为大家分享。好的，现在计时开始。\u003c/p>\u003cp>越分享越有收获，哪位小伙伴能分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>案例记录1：\u003c/p>\u003cp>按照这步骤我说一下，我这个也是便签营里面学习的动力，实际上我现在还在14天便签营里面，应该属于是第九天了，说一下自己的动力，和刚才老师一样，也是读书很长时间，反思日记也写了很多，但是感觉到收效甚微，生活中的困难压力，中年人的痛苦，就是让我怎么说，是虽然读了很多书，写了很多日记，仍然解决不了，然后很困惑。\u003c/p>\u003cp>也是有一次偶然机会，读到了《就这样读书就够了》这本书，并且看到后面的二维码，然后我就尝试扫了一下，然后进入，最后了解到郑州有个分舵，还有最近有一个活动，然后就去参加了，并且经一个人的介绍，然后说要想学得更好，还是需要参加14天的便签营，就这样进入了。\u003c/p>\u003cp>在这个学习的过程中就遇到了困难，就是前两天家里来了客人，这是然后耽误了我白天很多时间。我本人的眼睛有严重的干眼症，实际上晚上是不能熬夜写作业的，平常手机都不能超过半个小时观看，然后只能白天写，并且是只能写、停，写个40分钟就要休息一会儿，眼睛要不然是很崩溃。\u003c/p>\u003cp>曾经也想到勉强写，然后简单写交了就算了。但后来考虑到我的初衷就是为了学到真经，取到真经，学以致用，最后解决生活的问题。所以说我就是坚持咬牙坚持的，然后有时候白天完不成我就不去吃饭，早上有几次都没有吃饭，一直熬到了中午，还有，有时候也想多学点东西，有时候晚上晚上到10点多，大家都提交完作业之后，我又专门看看其他同学的优秀作业，吸取营养，最终达到的效果。暂时是9次提交的作业，全部是五星，然后有4次精选，上一周7天的排名，我是全部积分榜的第一名，精选也是积分榜，不过是第二名，就达到这个效果。\u003c/p>\u003cp>非常感谢这位小伙伴的分享，非常感人，非常励志。\u003c/p>\u003cp>案例记录2：\u003c/p>\u003cp>当时参加22期变迁营的时候，动力很大，我原因就是我想的是我要把这个东西给学会，我在参加第一堂课的时候，我哭了掉眼泪了，我觉得我这活了几十年，我白看书白学习了，我觉得我没有学好。当我知道了这个方法之后，我就在想，哪怕咱说这14天我跪着，我也得把这课给学完，我把这个能力给掌握了。在这个过程当中确实也有很多难处，因为要写好每个便签至少也得投资两小时三小时去写，真的是挑战也挺大的，但是我就把我家娃放到我妈，然后我去我妈那个地方，然后没跟我老公在一块，这时间我会更多，然后去学习去写作业，完成便签，我的要求是我写了必须五星，这是最低标准，然后是多少场？我一共说我就有一回是得了4星，其他全部都是5星，12次作业11次5星。对，所以给我的一个要求就是什么，只要你想你就能得到。\u003c/p>\u003cp>感谢2位小伙伴的分享。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】：1分钟\u003c/strong>\u003c/p>\u003cp>接下来请大家根据今天学习的内容，规划一下在未来的一周或者一个月内，你可能会在哪个场景用到以上所学的方法，用1分钟请大家在便签纸上写下各自的应用或行动步骤，写的时候，要有具体的做法，有明确的时间，要有可衡量或可观测预期的、量化的结果。\u003c/p>\u003cp>学习者案例1：\u003c/p>\u003cp>在下周三的健康管理培训会上，有一个自我介绍，我将这样讲述自己的动机故事：\u003c/p>\u003cp>第一步：我的动机。我决定踏上学习健康管理的旅程，源自目睹身边亲人因忽视健康管理而遭遇的健康问题，我意识到预防胜于治疗的重要性。希望通过学习专业知识，为家人及未来可能帮助到的人，制定个性化的健康管理计划，促进健康、预防疾病。\u003c/p>\u003cp>第二步：遇到的困难\u003c/p>\u003cp>在追求健康管理知识的道路上，我遇到到了两大挑战。一是时间管理，工作与生活琐事可能挤压学习空间；二是知识体系的庞大与复杂，需要耐心与毅力去逐步攻克。这些困难我给带来焦虑与挫败感。\u003c/p>\u003cp>第三步：最后的结果\u003c/p>\u003cp>为了克服这些困难，我制定了详细的学习计划，确保每天至少有一小时专注于健康管理的学习，最后终于获得了健康管理证书。\u003c/p>\u003cp>学习者案例2：\u003c/p>\u003cp>在下一个月有一个高考报考交流会，我将这样来介绍自己为什么要成为高报职业规划师\u003c/p>\u003cp>第一步：动机与来源\u003c/p>\u003cp>作为家长，我深感高考报考对孩子未来的重要性。每一次选择，都可能成为孩子人生轨迹的转折点。因此，我下定决心要深入学习高考报考的相关知识，希望能为孩子提供最有力的支持和指导。我的动机来源于对孩子未来的深切期望，希望通过自己的努力，帮助孩子找到最适合自己的道路，开启精彩的人生篇章。\u003c/p>\u003cp>第二步：困难与冲突\u003c/p>\u003cp>在成为高考报考“专家”的过程中，我面临着诸多挑战。首先，高考政策年年更新，专业信息纷繁复杂，我需要不断跟进学习，才能确保信息的准确性和时效性。其次，孩子的兴趣和特长是多方面的，如何在众多选项中做出最适合孩子的选择，是我需要深思熟虑的问题。此外，我还需要平衡孩子的意愿与家长的期望，确保最终的决定既能满足孩子的个人发展，又能符合家庭的期望。\u003c/p>\u003cp>第三步：行动与结果\u003c/p>\u003cp>为了克服这些困难，我采取了积极的行动。我参加了各种高考报考讲座和咨询会，与专家面对面交流，获取最权威的信息和建议最后，顺利通过考试，并取得了从业证书。\u003c/p>\u003cp>\u003cstrong>【结束语】：1分钟\u003c/strong>\u003c/p>\u003cp>最后总结一下今天的拆书内容，当您带着故事思维，去看待世界，理解世界，用故事讲出你的影响力，你一定会发现另一个全新的自己。 \u003c/p>\u003cp>祝愿小伙伴都能成为讲好故事的人，通过讲好故事来完成自己更大的目标，拥有更广阔的未来。\u003c/p>\u003cp>今天的分享到此结束，希望能对各位小伙伴有帮助。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1723597411000,"updated_at":1724765426000,"ria":true},{"id":17857,"topic":"故事力：从感动到行动","learn_goal":"","remark":"好故事带来影响力\n\n但没有行动号召的故事会让听众感到迷茫\n\n不知道接下来应该做什么\n优秀的故事讲述者\n不仅能引发共鸣和启发思考\n还会提出具体的行动指导\n帮助听众将启示转化为行动\n为社会或自己带来积极的变化","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"喜春","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍+分组】\u003c/p>\u003cp>大家好，我是喜春，我的3个标签是：\u003c/p>\u003cp>1.新鲜出炉的二级拆书家；\u003c/p>\u003cp>2.喜欢收纳“套路”的逻辑派；\u003c/p>\u003cp>3.非著名故事教练\u003c/p>\u003cp>今天是我TF3-2拆书，预计时长为20～25分钟，为方便后续讨论演练，我们就近2人一个小组。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【事件】最近，我们团队来了个新销售，热情开朗，与客户建立关系时特别顺畅，产品故事、行业八卦聊的很愉快，客户也很喜欢他，但就是迟迟不成交。\u003c/p>\u003cp>【提问】他很纳闷：是故事失灵了？还是故事缺少一些关键要素？大家遇到过类似的情况吗？你们觉得问题出在哪里？\u003c/p>\u003cp>【影响】故事往往能激发听众的情感和共鸣，但如果讲故事的我们没有及时引导听众将情感转化为实际行动，听众的行动意愿便难以被激发，我们故事的影响力也会大打折扣。\u003c/p>\u003cp>【解决】《故事力》告诉我们：故事讲完了，不代表讲故事的你完工了。正相反，真正有意义的事情才开始。你需要利用好最后的机会把自己想表达的观点提炼出来，并发出行动的号召。\u003c/p>\u003cp>【设定学习目标】\u003c/p>\u003cp>本次的学习目标是，在跟随我完成现场学习后，当学习者想要通过讲故事号召行动、争取资源和支持时，可以运用行动号召三步法设计故事结尾，让听众明确行动方向，并激励他们付诸实践。\u003c/p>\u003cp>【A1倾听自测】\u003c/p>\u003cp>在阅读原文片段前，请进行一个简短的测试，以评估我们的故事号召力。请仔细审视下面的表格，每道题都基于您的实际情况打分（1表示“完全不符合”，6表示“非常符合”）。请在对应的分数上打“√”，整个测试大约需要1分钟。完成后，请统计您的总分。\u003c/p>\u003cp>【I解释自测题】\u003c/p>\u003cp>时间到，这个自测能帮助我们对自己当前的“故事号召力”有个初步判断。\u003c/p>\u003cp>\u003cstrong>有哪些小伙伴的总分是21分以上的？\u003c/strong>\u003c/p>\u003cp>你们已经掌握了用故事激励听众行动的高超技巧，拥有“一呼百应”的影响力。不妨看看今天的拆页能否给你带来新的启发和收获；\u003c/p>\u003cp>\u003cstrong>有哪些小伙伴的总分是11-21分？\u003c/strong>\u003c/p>\u003cp>你们已经有意或无意中使用故事激励听众行动，拥有“举足轻重”的影响力。但离完全掌握还有一定距离，通过今天的学习，你会得到进一步提升；\u003c/p>\u003cp>\u003cstrong>有哪些小伙伴的总分是10分及以下？\u003c/strong>\u003c/p>\u003cp>你们的故事号召力有待发掘，但请放心，通过今天的现场学习，我们将一起探索并掌握一个简单有效的方法，这将帮助你开启故事号召行动的旅程。\u003c/p>\u003cp>下面，请大家用1分钟时间阅读原文片段，完成后请举手示意。\u003c/p>","ratings_count":1,"texts":[{"id":22091,"quote":"\u003cp>我儿子14岁，他2018年在一个为EGRC（Educating Girls of Rural China，一家资助中国西部山区女学生上学的公益组织）募捐的慈善晚会上，当着200多人的面，讲了一个他跟我去甘肃农村支教，看到当地学生艰苦的学习环境后非常震惊的故事。\u003c/p>\u003cp>故事讲完以后，他是这么说的：“一会儿，就在我现在站着的这个舞台上，将会有一个拍卖，我希望你们能够慷慨解囊。当然我知道，那是你们的钱，你们能决定怎么花，但我邀请你们尽自己的微薄之力，改变这些女学生的命运，改变这个世界。”\u003c/p>","explains":"\u003cp>检验下大家的阅读情况，我来问大家几个关于原文的小问题。\u003c/p>\u003cp>「问」案例的主人公，作者14岁儿子，在慈善晚会上讲了一个什么故事？\u003c/p>\u003cp>答案：和妈妈到甘肃农村支教，被当地艰苦的学习环境震惊到的故事\u003c/p>\u003cp>「问」讲完故事后，他还做了什么？\u003c/p>\u003cp>答案：提出了行动号召—请慷慨解囊\u003c/p>\u003cp>「问」如果你是台下的听众，听完他的行动号召，你是否能清楚接下来自己可以做什么？\u003c/p>\u003cp>答案：是\u003c/p>\u003cp>〈回应式反馈〉\u003c/p>\u003cp>太棒了，把掌声送给我们自己。正如案例主人公做的那样，在一个以募捐为目的的慈善晚会上，山区艰苦的学习环境能打动听众的恻隐之心，但具体的、有同理心的行动号召，才是让听众慷慨解囊的法宝。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>：\u003c/p>\u003cp>当我们被故事打动时，那瞬间的共鸣和感动非常珍贵。但若我们只沉浸在感动中，而不尝试将其转化到行动层面，那这份感动就会像烟花一样转瞬即逝，徒留空虚和遗憾。\u003c/p>\u003cp>\u003cstrong>WHAT\u003c/strong>：\u003c/p>\u003cp>拆页案例给我们做了一个用故事号召行动的示范，在故事的结尾处明确提出我们希望对方做的事，并赋予这些行动巨大的价值，这样不仅为故事画上圆满的句号，还能深深触动听众的心灵并激发他们的行动欲望。\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>：\u003c/p>\u003cp>那如何在故事结尾号召行动？根据拆页案例，我提炼了一个“行动号召三步法”。\u003c/p>\u003cp>第一步，设定\u003cstrong>场景\u003c/strong>，明确指出你希望对方在什么时候什么地点什么事件等条件下做出行动。\u003c/p>\u003cp>原案例中设定的场景是“一会儿，就在我现在站着的这个舞台上，将会有一个拍卖会”\u003c/p>\u003cp>第二步，明确\u003cstrong>行为\u003c/strong>，号召的行动一定是具体的、可行的，最好能具象成一个小的行为动作。比如说呼吁讲究卫生，大家可能会迷糊。但如果提醒大家饭前便后要洗手，大家就会清楚知道怎么做。\u003c/p>\u003cp>原案例中明确的行为是“慷慨解囊”---掏钱，而不是请帮帮他们这种很模糊的表达。\u003c/p>\u003cp>第三步，升华\u003cstrong>意义\u003c/strong>，为行动赋予意义是激发人们自发行动的关键，当人们意识到自己的行为具有深远的影响和价值时，他们更有可能主动采取行动。\u003c/p>\u003cp>原案例中，让台下的听众知道自己的微薄之力可以改变一个山区女学生的命运，进而改变世界的话，他们一定会慷慨解囊。\u003c/p>\u003cp>〈举例子〉\u003c/p>\u003cp>为了让大家更好地理解，我举一个自己的例子。\u003c/p>\u003cp>去年年底，我辅导的几名学员，分别拿到了所在俱乐部、小区的比赛冠军。应俱乐部的邀约，我做了一个10分钟的分享。在分享中，我讲了自己如何从一个以理服人的辩论选手，转型为一个以情动人的故事教练，转型路上的心酸和痛苦收获了大家的笑声和掌声，在结尾处我很煽情地引用了金句“讲故事的人改变世界”。掌声雷动中我满意回到台下，迎来大家的热心提问：我感觉自己没有故事怎么办？人家说我讲故事像流水账？你拆解故事的素材是从那里找到的……\u003c/p>\u003cp>众人的疑问，让我明白，我把故事讲成事故。\u003c/p>\u003cp>如果时间能重来，我一定用行动号召三步法来替代煽情金句。\u003c/p>\u003cp>第一步，设定场景，我们俱乐部每周一期线下例会、 三期即兴晨会，请大家每周至少参与一次\u003c/p>\u003cp>第二步，明确行动，讲一个与会议主题有关的2分钟小故事\u003c/p>\u003cp>第三步，升华意义，这样一年下来，你将拥有至少52个珍贵的小故事，将这些故事串联起来，就能编织出一本丰富多彩的人生故事册。\u003c/p>\u003cp>相信这样的行动号召之后，我的听众伙伴一定能够积极行动起来。\u003c/p>\u003cp>\u003cstrong>WHERE\u003c/strong>：\u003c/p>\u003cp>行动号召三步法适用于：\u003c/p>\u003cp>1. 社会公益类故事\u003c/p>\u003cp>2. 教育启发类故事\u003c/p>\u003cp>3. 商业营销类故事\u003c/p>\u003cp>不适用：\u003c/p>\u003cp>1. 学术讨论或理论研究的场景，故事可用于阐述观点、支持论点或提供案例，提出行动号召可能会分散听众注意力，影响对内容的理解和接受\u003c/p>\u003cp>2. 有关情感或心理敏感的议题，往往涉及复杂的情感和道德考量，不适合简单通过行动号召来解决\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>好的，以上就是我的讲解。现在我们来学以致用。\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>请大家设想一个场景：\u003c/p>\u003cp>小智是拆书帮的三级拆书家，通过过去2年在拆书帮不断输出、沉淀，他已成为一个小有名气的培训师，并建立了自己的知识IP，拥有百万粉丝。毕业季，母校邀请小智为即将毕业的学弟学妹们做分享。小智分享了自己成长的心路历程，从最初的迷茫到后来的坚定。他鼓励学弟学妹，即使离开学校，也不要放弃学习，每天学习一点新知识，就是种下一颗希望的种子，终有一天，这些种子会生根发芽，长成参天大树。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>如果你是小智，你将如何应用“行动号召三步法”在故事结尾处发出行动号召，把听众从感动导向行动。请大家在小组内示范演练。5分钟后我邀请一位伙伴上台演练。\u003c/p>\u003cp>\u003cem>\u003cu>分组演练，5min，\u003c/u>\u003c/em>\u003c/p>\u003cp>（5分钟后）时间到，下面我想请粉黑同学发出她的行动号召。\u003c/p>\u003cp>\u003cem>&lt;学习者案例&gt;\u003c/em>\u003c/p>\u003cp>粉黑\u003c/p>\u003cp>我和我的同组伙伴共同讨论出我们的做法，按照行动号召三步法：\u003c/p>\u003cp>第一步，设定场景：学弟学妹们，一个月后，你们即将正式踏入职场，你们可能会遇到很多的挫折，在需要用在学校中没有学到的知识去解决问题时。\u003c/p>\u003cp>第二步，明确行动：希望你们无论多忙多累，都别忘了给自己挤出一点读书的时间，坐在书桌前，打开一本能让你心灵安静、或增加你技能的一本书。\u003c/p>\u003cp>第三步，升华意义：学弟学妹们，现在大家以深大为荣，希望未来深大都以你们为荣。就像富兰克林说的那样：不要问社会能给我们什么，我们要给社会更多的东西，谢谢！\u003c/p>\u003cp>反馈：感谢优秀学长【粉黑】对我们的期待，把读书和为社会做贡献建立了关联，号召力特别强。\u003c/p>\u003cp>【A2布置任务】\u003c/p>\u003cp>为巩固学习，我给大家布置一个课后作业。\u003c/p>\u003cp>接下来的一周时间，你有没有希望通过故事号召行动、获得资源支持的场景，比如：\u003c/p>\u003cp>1.孩子有不好的习惯，和他讲一个故事并提出改变建议\u003c/p>\u003cp>2.向领导汇报项目进展，在结尾处请求资源支持\u003c/p>\u003cp>3.组织一场公益活动，号召社区居民为偏远地区儿童捐赠图书\u003c/p>\u003cp>请大家回去后试着运用行动号召三步法，向你的听众发起行动的呼吁。看看能获得怎样的回应。完成任务的小伙伴，请在下周五前将你的案例通过微信发给我，我会针对你的实践做出反馈，非常期待大家的作业。\u003c/p>\u003cp>【有力结尾】\u003c/p>\u003cp>没有升华和行动号召的故事就像烟花，看起来很热闹，但很快就会消散。你的故事应该是一份礼物。能触动人心，能引发思考，还能激发行动。用故事号召行动，就用行动号召三步法，大家还记得吗？第一步设定场景，第二步明确行动，第三步升华意义。感谢大家的共学共创，期待大家都能拥有一呼百应的影响力。\u003c/p>\u003cp>附件：课后作业收集如下：\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1721187770000,"updated_at":1721394902000,"ria":true},{"id":17759,"topic":"故事介绍法","learn_goal":"","remark":"好的销售都会讲故事\n\n听众可能记不住你的标签\n\n记不住产品的配料表\n\n记不住产品的功能卖点\n\n记不住到底多少钱买的......\n\n但他们一定会记得住一个好故事！","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"喜春","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍+分组】\u003c/p>\u003cp>大家好，我是喜春，我的3个标签是：\u003c/p>\u003cp>1.正在挑战三级的拆书家；\u003c/p>\u003cp>2.喜欢收纳“套路”的逻辑派；\u003c/p>\u003cp>3.非著名故事教练\u003c/p>\u003cp>今天是我TF3-1拆书，预计时长为15～20分钟，为方便后续讨论，我们就近2人一个小组。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【事件】去年年底，我带着团队的新人小慧参加一个行业聚会，小慧问我要做什么准备，我说准备好一个自我介绍就好。聚会当天，小慧做了一个非常详细的自我介绍，学历、经历、爱好、特长应有尽有。下台后他很失落，过来问我：为什么我讲的那么卖力，台下的人都在玩手机？\u003c/p>\u003cp>【提问】大家是否也遇到过类似的场景？精心准备的自我介绍，根本引不起大家的兴趣。\u003c/p>\u003cp>【影响】自我介绍不仅是陈述个人信息，更是展示个性、秀出能力的大好机会。一个平淡的自我介绍很难给人留下深刻的印象，也会让我们错失很多机会。\u003c/p>\u003cp>【解决】《故事力》告诉我们：故事比简历、名片更吸引人。想要 让别人认识你、记住你，靠发名片和强行表白，是很难做到的，但是一个应景的好故事可以。\u003c/p>\u003cp>【设定学习目标】\u003c/p>\u003cp>本次的学习目标是，在跟随我完成现场学习后，学习者可以区分叙述和故事，在做人物介绍、产品介绍、观点阐述时，能运用故事介绍三步法，抓住听众的注意力并获得回应。\u003c/p>\u003cp>下面，请大家用1分钟时间阅读原文片段，完成后请举手示意。\u003c/p>","ratings_count":1,"texts":[{"id":21980,"quote":"\u003cp>《故事力》\u003c/p>\u003cp>我先给大家讲一个真实的故事。\u003c/p>\u003cp>曾经一位全职妈妈创业找融资的时候给著名的投资人徐小平发了一条短信。\u003c/p>\u003cp>第一句：我是北大毕业的。\u003c/p>\u003cp>第二句：现在在开淘宝店，淘宝店的销售额已经3000万了。\u003c/p>\u003cp>第三句：但是我陷入了迷茫，您是一位心灵导师，您能不能开导开导我？\u003c/p>\u003cp>结果，徐老师看到这条短信后3分钟就把电话打了过去。当天下午他们就约好见面，谈了4个小时后，徐小平就打算投资她了。这位全职妈妈就是电商平台蜜芽的创始人刘楠。经过五轮融资，现在这家公司已经有了100亿元的估值。所有这些都源于一个三句话的自我介绍，这个介绍就是一个典型的故事。\u003c/p>\u003cp>为什么这么说呢？\u003c/p>\u003cp>你看，如果她的这个短信是这么说的：“徐小平老师你好！我叫刘楠，我从北大毕业，创业销售额达到3000万了，想要寻求融资，能见见您吗？”你觉得这么说还会有同样的效果吗？估计徐小平老师看一下就删了。只有“因为”+“所以”就不算一个故事——因为我想融资（目标），所以我想见你（结果），这只能算是一个叙述。那什么是故事呢？在“因为”和“所以”之间加一个“但是”，就变成了故事！\u003c/p>","explains":"\u003cp>所有伙伴都看完片段了，接下来我来说下我对拆页的理解。\u003c/p>\u003cp>\u003cstrong>WHAT\u003c/strong>：\u003c/p>\u003cp>拆页讲的是蜜芽创始人刘楠使用故事介绍法，获得了与投资人会面的机会并最终成功融资。作者讲到了两种表达方式：叙述和故事。\u003c/p>\u003cp>叙述是按照因果顺序罗列事实，我要出门办事，因为朋友突然到访，所以我只能先接待他。“因为-所以”结构交代“发生了什么”\u003c/p>\u003cp>故事则是由一系列冲突驱动的事件，我要出门办事，朋友突然到访，我火烧眉毛，但朋友也是迫在眉睫。想到朋友之前对我的支持，我决定先帮他。这解释了事情为什么会发生。\u003c/p>\u003cp>故事和叙述的本质差异，在于有没有这个“但是”，“但是”制造了冲突，无冲突不故事。\u003c/p>\u003cp>为方便理解，我举几个例子：\u003c/p>\u003cp>案例1:我是个盲人，请帮帮我\u003c/p>\u003cp>请问这是叙述还是故事？【学习者：叙述】\u003c/p>\u003cp>案例2:这真是美好的一天，而我却看不见\u003c/p>\u003cp>请问这是？【学习者：故事】\u003c/p>\u003cp>案例3:我和我的夫人坐在火车上，吃着火锅唱着歌，一路上开怀畅饮。\u003c/p>\u003cp>请问这是？【学习者：叙述】\u003c/p>\u003cp>案例4:我和我的夫人坐在火车上，吃着火锅唱着歌，突然就被马匪打劫了。\u003c/p>\u003cp>请问这是？【学习者：故事】\u003c/p>\u003cp>案例5:早上出门，门口有个小石子儿，还好我眼疾手快跳过去了。\u003c/p>\u003cp>请问这是？【学习者：叙述/故事】\u003c/p>\u003cp>拆书家：听到伙伴有说叙述的，又说故事的。我们来辨析一下。句子虽然有“但是”的意思，但一个小石子儿带来的矛盾、对抗称不上冲突，平淡的小摩擦会让听众觉得无聊，因此案例不是故事。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>：\u003c/p>\u003cp>通过以上5个案例，我们不难发现，对事件平淡的叙述，像白开水一样枯燥无味。而一个有冲突的故事，则能够抓住听众的注意力，引发听众的情绪。故事承载的情感价值，能够让听众放下评判标准，去接受一个未知的或曾经不认可的事物。\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>：\u003c/p>\u003cp>那如何像刘楠那样用故事来做介绍呢？根据拆页案例，我提炼了一个“故事介绍三步法”\u003c/p>\u003cp>第一步，交代\u003cstrong>背景\u003c/strong>，向对方提供必要的背景信息，可以是个人身份、产品信息等。这些信息可以让听众快速识别接下来的内容和他有关，并愿意听下去。\u003c/p>\u003cp>案例中“我是北大毕业的”，名校毕业加持更容易获得投资人的关注和信任。\u003c/p>\u003cp>第二步，制造\u003cstrong>冲突\u003c/strong>，利用“但是”来设计一系列冲突，引发听众的好奇心。冲突可以是外部的阻碍，也可以是内心的纠葛。\u003c/p>\u003cp>北大毕业生很多，但北大毕业生怎么去开淘宝店了？这是第一个冲突；一个淘宝店销售额竟然做到了3000万，大家是不是更好奇了；紧接着“我陷入了迷茫”--3000万还迷茫？这是第三个冲突。层层递进，紧紧抓住听众的注意力。\u003c/p>\u003cp>第三步，请求\u003cstrong>回应\u003c/strong>，提一个让对方觉得是举手之劳的小要求。原文中“您是一位心灵导师，您能不能开导开导我”，让投资人可以立即做出反应。假如狮子大开口-“请您投资我吧”，就容易引起对方的戒备，造成沟通失败。\u003c/p>\u003cp>〈反例〉\u003c/p>\u003cp>为了让大家更好的理解，我举一个自己的例子。\u003c/p>\u003cp>上周，朋友看到我分享拆书帮活动，发信息给我“喜春，你在做读书会吗？我最近也在读书”。作为分舵的会员长老，我立马来了精神，把什么是拆书法、拆书帮，怎么过三级……给他详细介绍了一遍。朋友说“挺好的”。然后，就没有然后了。\u003c/p>\u003cp>〈反例变正例〉\u003c/p>\u003cp>如果再给我一次机会，我一定用故事介绍三步法，把我和拆书帮的故事讲给他听。\u003c/p>\u003cp>第一步，交代背景：我参加的组织是拆书帮，一个累计影响百万人的全球组织。\u003c/p>\u003cp>第二步，制造冲突：和读书会细细品味不一样。拆书帮强调的是把书中的知识转化为能力。拆书法虽棒，但新手开始学一定要慎重！！因为拆书真的会上瘾，我学拆书法本来是为了提升阅读速度，节省时间，但开始学习后，每天写作业写到凌晨.现在我开始拆书过级，拆书名额很难抢，为了抢名额我每周都设2个闹钟,但还是百拆不厌。\u003c/p>\u003cp>第三步，请求回应：我说的再多，不如你感受一次，周三我们有现场活动，你来听我拆书吧。\u003c/p>\u003cp>相信他一定有兴趣到现场体验。\u003c/p>\u003cp>\u003cstrong>WHERE\u003c/strong>：\u003c/p>\u003cp>故事介绍三步法不仅适用于自我介绍，也适用于：\u003c/p>\u003cp>1. 人物介绍\u003c/p>\u003cp>2. 产品介绍\u003c/p>\u003cp>3. 观点阐述\u003c/p>\u003cp>不适用：\u003c/p>\u003cp>1. 信息要求精确的紧急通知、技术说明或法律条款\u003c/p>\u003cp>2. 讲解敏感或争议性话题\u003c/p>\u003cp>&lt;预防异议&gt;\u003c/p>\u003cp>我们说无冲突不故事，那冲突是不是越极端越好？卖惨有用吗？\u003c/p>\u003cp>卖惨、强行煽情，听众会尴尬。个人故事，商业故事，要想让听众买账，不能人为制造虚假的冲突，而是要去挖掘听众真实的渴望和障碍。唯有真实的冲突，才能引发共鸣。\u003c/p>","interaction":"\u003cp>好的，以上就是我的讲解。现在我们来拆为己用，做一个练习：\u003c/p>\u003cp>请大家设计一个未来需要做介绍的场景。比如：\u003c/p>\u003cp>1. 出席一个重要活动，做自我介绍；\u003c/p>\u003cp>2. 作为活动主持人，介绍一位出场嘉宾；\u003c/p>\u003cp>3. 朋友正在为孩子的教育问题头疼，你向他推荐一本书/一个方法。\u003c/p>\u003cp>请大家设计一个小剧本，几百字即可，要求有人物、对话、情节变化（包括：起因、经过、结果）。注意：对话需应用“故事介绍三步法。接下来，请大家分组讨论剧本，并将摘要写在拆页背面的表格中。五分钟后我会请1位伙伴上台分享。\u003c/p>\u003cp>\u003cem>\u003cu>设计剧本\u003c/u>\u003c/em>\u003c/p>\u003cp>（5分钟后）时间到，下面我想请王强老师分享一下他的剧本。掌声有请！\u003c/p>\u003cp>\u003cem>&lt;学习者案例记录&gt;\u003c/em>\u003c/p>\u003cp>感谢王强老师的精彩分享，也期待下周三伟杰老师的微课堂。\u003c/p>\u003cp>【有力结尾】\u003c/p>\u003cp>无论是为新工作面试，给客户推销产品还是输出自己的影响力，好故事就是金名片，讲好故事，才有机会让他人记住、认同、埋单。以上就是我的分享，感谢大家的聆听共创！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1718857759000,"updated_at":1718864383000,"ria":true},{"id":17608,"topic":"讲好故事，助你升职加薪","learn_goal":"","remark":" 讲故事，是一项非常重要的职场技能。\n 提案时讲好故事，不仅可以争取到领导的支持，还能反向给领导画大饼。\n工作汇报讲好故事，不仅能把事情说清楚，还能让领导认可你的能力。\n 规划能力强、执行能力棒、何愁不升职加薪","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"喜春","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>【自我介绍+分组】\u003c/p>\u003cp>大家好，我是喜春，我的3个标签是：\u003c/p>\u003cp>1.一级拆书家；\u003c/p>\u003cp>2.喜欢收纳“套路”的逻辑派；\u003c/p>\u003cp>3.非著名故事教练\u003c/p>\u003cp>今天是我TF2-4拆书，预计时长为50-60分钟。为方便后续讨论、演练，我们就近两人一个小组。\u003c/p>\u003cp>【FAB法介绍图书】\u003c/p>\u003cp>【F】今天我要拆解的这本书叫《故事力》，作者高琳和林宏博，是夫妻搭档。他们拥有共40年世界500强管理和咨询实战经验，根据多年经验，他们开发了一套有趣、实用、完善、专业的故事力思维训练方法，帮大家找到属于自己的故事力。\u003c/p>\u003cp>【A】和其它沟通类书籍相比，本书凝聚了情商、沟通力、领导力和战略思维等综合能力，是一本实战型工具书，本书运用大量的实例阐述讲故事的价值，并总结出6个故事模型，落实到8大应用场景。\u003c/p>\u003cp>【B1】你是否有这样的困扰：觉得自己没故事；讲的故事让人昏昏欲睡；不知道如何讲职场故事。书中不仅给了模型，还讲述了模型背后的原理。书中大量普通人的故事，借鉴性极强。\u003c/p>\u003cp>【B2】今天我拆解的2个片段将教会大家在提案、汇报时讲好故事，不仅让老板在理性上认可你的方案和成果，也让老板在感性上认可你的努力和付出。\u003c/p>\u003cp>【学习总目标和片段关系】\u003c/p>\u003cp>片段1教我们讲好提案故事，拿下项目和资源；片段2教我们在项目开始后做好工作汇报，展示成果并获得老板的肯定。\u003c/p>\u003cp>2个片段，在时间上有先后，在逻辑上属于递进关系。\u003c/p>\u003cp>【片段1学习目标】\u003c/p>\u003cp>我们开始第一个片段的学习，本片段的学习目标是：\u003c/p>\u003cp>在跟随我完成上半场现场学习后，学习者在做提案时，能运用“雪中送炭”模型，获得对方的认可和支持。\u003c/p>\u003cp>下面请大家花1分钟时间阅读片段1，完成后请举手示意。\u003c/p>","ratings_count":1,"texts":[{"id":21803,"quote":"\u003cp>《故事力》，主题：雪中送炭模型\u003c/p>\u003cp>每个人都生活在自己的故事里，当你试图“卖”一个观点给对方的时候，就意味着你的故事和对方的故事需要有一个交集。否则你再怎么讲你的故事也是自说自话。在这个交集里，你需要讲一个以对方为中心的故事，这个故事模型，我们叫它“雪中送炭”，这个模型几乎适用于任何销售场景，包括给老板“卖”自己的观点。所谓雪中送炭，就是听众本来一切顺利，有一天突然发生了什么，导致他面对困难，然后你来帮助他的故事。这个故事和其他故事最大的不同就是，讲故事的你不是故事的主人公，听的人才是。在下雪天，你是那个送炭的人。所以，雪中送炭的故事模型具体来讲是这样的：\u003c/p>\u003cp>◆ 背景：主人公本来有的一个目标\u003c/p>\u003cp>◆ 冲突：达成这个目标遇到了或者会遇到什么样的阻碍\u003c/p>\u003cp>◆ 解决冲突：雪中送炭，提出克服阻碍的解决方案\u003c/p>\u003cp>◆ 完美结局：这个方案能够带来什么样的结果\u003c/p>","explains":"\u003cp>所有伙伴都看完片段了，接下来我来说下对拆页1的理解。\u003c/p>\u003cp>WHAT：\u003c/p>\u003cp>本片段教给我们一个能赢得老板认可的提案框架-雪中送炭模型，就是讲述一个老板面对困难，你来帮他的故事。\u003c/p>\u003cp>WHY：\u003c/p>\u003cp>\u003cem>一般做法：\u003c/em>\u003c/p>\u003cp>很多人在提案时，出发点往往是基于自身或团队的需求，即“我想要”，然而老板不会因为“你想要”，就把资源给你。\u003c/p>\u003cp>\u003cem>不那么做的坏处：\u003c/em>\u003c/p>\u003cp>资源有限，若不把“你想要”变成“老板需要”，你的提案就无法打动老板的心，你也只能怪老板“偏心”。\u003c/p>\u003cp>&lt;反面例子&gt;\u003c/p>\u003cp>去年，我负责公司的电商业务，我规划了一个精准推送功能，于是向老板提案：老板，我建议我们后台增加一个精准推送的功能，比如客户买了拖把，我们就给他推送“拖把桶”……\u003c/p>\u003cp>在我开始讲细节时，老板打断我说：我再考虑考虑。\u003c/p>\u003cp>很明显我把故事讲成了事故。\u003c/p>\u003cp>HOW：\u003c/p>\u003cp>那如何把提案说到老板的心坎上，有4个步骤：\u003c/p>\u003cp>1.目标，说老板的目标，将你的提案与公司、团队或老板个人的目标关联起来\u003c/p>\u003cp>2.挑战，实现这个目标遇到了什么困难，比如遭遇竞争对手、增长放慢等\u003c/p>\u003cp>3.方案，讲你的方案，告诉老板：您采用这个方案，就可以解决公司、团队、和您遇到的问题\u003c/p>\u003cp>4.结局，带着老板畅想美好未来，成功画面就是他拍板决策的临门一脚\u003c/p>\u003cp>&lt;正面例子&gt;\u003c/p>\u003cp>回到刚才我提案失败的案例，如果再给我一次机会，我会用雪中送炭模型重新应对。\u003c/p>\u003cp>1.目标，说老板的目标：“老板，年初您制定了营业额20%的增长目标。”\u003c/p>\u003cp>2.挑战：“我们今年尝试了多种促销活动来刺激购买，短期有效，但长期来看，促销不仅造成了利润率下降，效果也在逐渐减弱，这样下去肯定完不成业绩目标。”\u003c/p>\u003cp>3.方案：“经过调研我想到了一个方案，那就是给用户精准推送商品，比如客户买了拖把，我们就给他推送拖把桶。很多客户在我们这里购买后又到其他地方买配套，这是非常大的损失”\u003c/p>\u003cp>4.结局：“这样预计能把客单价从60提高到90，月营收预计提高30%”\u003c/p>\u003cp>这样的提案，相信老板一定会点头同意。\u003c/p>\u003cp>WHERE：\u003c/p>\u003cp>雪中送炭模型不仅适用于向老板提案，也适用于：\u003c/p>\u003cp>1. 制定销售方案\u003c/p>\u003cp>2. 制定家庭计划\u003c/p>\u003cp>3. 为社团社群提案\u003c/p>","interaction":"\u003cp>【A1激活经验—显像提问】\u003c/p>\u003cp>&lt;提问设计&gt;\u003c/p>\u003cp>请大家回忆最近半年，你是否有过提案失败的经历？\u003c/p>\u003cp>比如业务流程繁琐、效率不高，于是你做了一个流程精简的方案，却被领导的“这个不急，先放一放”而搁置；\u003c/p>\u003cp>比如为社团做活动方案，你滔滔不绝讲述方案的具体执行安排，但大家却兴致缺缺；\u003c/p>\u003cp>比如口若悬河地向客户介绍产品的功能卖点，但客户却不置可否；\u003c/p>\u003cp>比如宝爸宝妈精心为孩子制定了暑假学习计划，但孩子根本不愿意听。\u003c/p>\u003cp>请大家在小组内讨论分享，时间为2分钟，时间到我会请一位伙伴上台分享。\u003c/p>\u003cp>\u003cem>\u003cu>分组讨论，2min\u003c/u>\u003c/em>\u003c/p>\u003cp>时间到，下面我想请莉莉同学，用1分钟时间分享一下她的案例。\u003c/p>\u003cp>\u003cem>&lt;学习者案例&gt;\u003c/em>\u003c/p>\u003cp>\u003cem>莉莉：最近半个月我有一个向客户分享产品失败的一个场景：我想做有机安全食品分享，于是我在4月23日拉了一个群分享，可是我遇到了一个困境，那就是没有了解客户的需求而是一直发产品。\u003c/em>\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>感谢莉莉的分享，刚才大家也都分享了自己提案失败经历。假如给你机会修正，结合雪中送炭模型，你会如何重新提案？请大家继续在小组内讨论，2分钟后我会请一位伙伴分享。\u003c/p>\u003cp>\u003cem>\u003cu>分组讨论， 2min\u003c/u>\u003c/em>\u003c/p>\u003cp>时间到，我想请莉莉同学，用2分钟时间继续分享她的案例。\u003c/p>\u003cp>\u003cem>&lt;学习者案例&gt;\u003c/em>\u003c/p>\u003cp>莉莉：（反思）经过讨论，我发现从4月23日建群，我从来没有进行过私聊这个动作，因此我根本不知道别人的目标是什么。对方也只知道我把大家拉到群里，我在卖东西。可是我每天在群里一顿输出，咔咔发图片、视频……我感觉有点跑偏了。\u003c/p>\u003cp>结合雪中送炭模型，我觉得我可以：\u003c/p>\u003cp>（1） 目标，私聊问大家的目标，我能提供的是安全有机的食品，你的目标是什么？你是否需要安全有机的食品？你对安全有机的理解是什么样的？\u003c/p>\u003cp>（2） 挑战，你在日常购物的时候是不是闭着眼就买了水果、食品？你有没有了解过配料表？比如给孩子吃的水果有没有用激素、农药、化肥？你有没有了解有没有问过？还有你买的有机食品贵不贵？看到商场里有机蔬菜几十块一斤，你是不是就放弃了？觉得有心无力……\u003c/p>\u003cp>（3） 方案，我来帮你，因为我提供的安全有机的食品，可以追溯到商家、产品种植地、生长过程……我都可以到现场给你拍视频；你的任何疑问我都可以帮你找到生产链条上的负责人；价格，你可以对比；每个产品我们都可以提供配料表……\u003c/p>\u003cp>（4） 结局，坚持吃我们的安全有机食品，不仅你和家人感冒发烧等生病的频率都会大幅度降低；也会让让家人的味蕾更加敏感，让家庭的生活更美好。\u003c/p>\u003cp>拆书家：感谢莉莉的精彩分享，她把自己的案例结合雪中送炭模型分享，真是一位热爱产品、热爱顾客的好销售，也让大家对模型有了更深的了解。掌声再次送给她。\u003c/p>\u003cp>【片段过渡】\u003c/p>\u003cp>雪中送炭模型，就是把“你想要”变成“老板需要”，当老板成为方案的最终受益人，他当然会说YES。\u003c/p>\u003cp>提案过了，接下来老板最关心的就是进展。当老板问起进展，而你没回答好，那你所有的努力都会大打折扣。\u003c/p>\u003cp>为了解决这个问题，我们就进入第二个片段的学习。\u003c/p>\u003cp>【片段2学习目标】\u003c/p>\u003cp>本片段的学习目标是：在跟随我完成下半场现场学习后，学习者做工作汇报时，能运用“三劳”汇报模型，不仅让老板了解项目进展，也让老板知道你工作的辛苦。\u003c/p>\u003cp>下面请大家花1分钟时间阅读片段2，完成后请举手示意。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":21804,"quote":"\u003cp>《故事力》，主题：“三劳”汇报模型\u003c/p>\u003cp>“我们这次现场签约80人，比往年的结果都好；还有50人一周内签订合同寄回，估计85%可以签约。不过，这次招聘还真的不容易，扩招之后毕业生比预计的多了近一倍，我们团队4个人，连吃饭喝水的时间都没有……最后回来的时候，我们的飞机还两次发生故障，迫降太原。我都差点儿以为不能回来了。这次团队的所有人都辛苦了，您可得请大家吃饭犒劳犒劳。”\u003c/p>\u003cp>这么一说，既让老板知晓自己想要的结果，也让他了解到团队付出的艰辛，继而点明了自己期望得到的认可方式。如果我是老板，一定立刻就会请团队吃大餐。\u003c/p>","explains":"\u003cp>所有伙伴都看完片段了，接下来我来说下对拆页2的理解。\u003c/p>\u003cp>WHAT：\u003c/p>\u003cp>本片段教给我们一个“三劳”汇报模型，通过事实、数据讲功劳，通过过程说苦劳，最后请老板犒劳自己，是一种既强调工作结果又关注工作过程的汇报方式。\u003c/p>\u003cp>WHY：\u003c/p>\u003cp>\u003cem>一般做法：\u003c/em>\u003c/p>\u003cp>“老板只看结果”这句话误导了很多人，他们在工作汇报时只说结果，没有一点过程，要不然就是把过程描述的一帆风顺。\u003c/p>\u003cp>\u003cem>不那么做的坏处：\u003c/em>\u003c/p>\u003cp>如果过程没有一点挑战，那你的价值何在？你克服的挑战、解决的问题才是你能力的体现。想当然地以为“我的辛苦老板都知道”，其实他们根本不知道。\u003c/p>\u003cp>HOW（细化行动步骤）：\u003c/p>\u003cp>那如何做好工作汇报？我从原文案例中提炼了一个“三劳”汇报模型。\u003c/p>\u003cp>第一步，\u003cstrong>讲功劳\u003c/strong>，用事实、数据汇报结果\u003c/p>\u003cp>原文中“现场签约80人，未来一周还有50人待签，预计签约率85%”让老板对局面一目了然。\u003c/p>\u003cp>第二步，\u003cstrong>说苦劳\u003c/strong>，讲述过程中的挑战和应对，让老板认识到你的价值\u003c/p>\u003cp>讲苦劳当然不是大吐苦水，我们这里细化为2个小步骤：\u003c/p>\u003cp>2.1.冲突，过程中遇到了什么困难，案例中“扩招之后毕业生比预计的多了近一倍，（而）我们团队（只有）4个人”\u003c/p>\u003cp>2.2.应对，我/团队是如何应对的，案例中“（我们一直工作）连吃饭喝水的时间都没有”\u003c/p>\u003cp>第三步，\u003cstrong>要犒劳\u003c/strong>，用一个小要求让老板表达认可：功劳苦劳那么大，要求这么一点点，这是什么神仙员工！\u003c/p>\u003cp>这个汇报模型，既体现了功劳，又展现了苦劳，还让老板给我们犒劳，所以我们把它称为”三劳”汇报模型。\u003c/p>\u003cp>&lt;意译案例&gt;\u003c/p>\u003cp>为了加深理解，我分享一个自己的案例：\u003c/p>\u003cp>去年，项目到了截止日期，但下班时还有几个问题没有解决。我带着团队加班，忙到23:00才发布新版本。\u003c/p>\u003cp>想着老板一直在等结果，于是我赶紧打电话过去，一接通，老板就问“怎么样？”我想着老板一贯喜欢开门见山，直奔主题。于是赶紧说：“老板，新版本经过测试验证，已成功发布。”想着团队刚才汗流浃背的样子，我又补充“多亏大家的配合。大楼21:30空调就停了，每个人都一身汗，还一遍一遍的测试。现在有点晚了，几位同事家比较远，请您批准他们打车回家吧？”\u003c/p>\u003cp>老板很爽快：“大家辛苦了，都打车回吧，路上注意安全。你和大家说一声，好好睡一觉，明早不用打卡”\u003c/p>\u003cp>Where：\u003c/p>\u003cp>“三劳”汇报模型不仅适用于时间不紧急的工作汇报场景，还适用于朋友托我们办事我们反馈进展的社交场景。\u003c/p>\u003cp>不适用：\u003c/p>\u003cp>1. 需要精确数据的科研、学术场景\u003c/p>\u003cp>2. 需要快速做决策的场景\u003c/p>\u003cp>\u003cem>&lt;预防异议&gt;\u003c/em>\u003c/p>\u003cp>可能有小伙伴疑问，都说“\u003cu>没有功劳就没有苦劳\u003c/u>”，工作进展不理想，“三劳”汇报模型还管用吗？\u003c/p>\u003cp>当然可以，项目遇到了困难，更应该及时向老板汇报。\u003c/p>\u003cp>讲功劳，实事求是汇报进度和困难，老板才能及时协调和决策\u003c/p>\u003cp>说苦劳，让老板知道形式的严峻性，并知晓团队正在积极应对，没有不当回事或躺平\u003c/p>\u003cp>要犒劳，展现排除万难最终取胜的决心，也是一个约定--等赶回进度，等项目成功，老板再犒劳大家。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>\u003cem>&lt;场景设计&gt;\u003c/em>\u003c/p>\u003cp>光说不练假把式，大家可以想象这样一个场景：\u003c/p>\u003cp>端午节马上到了，公司老板鲍总安排员工采青去准备端午节礼包。采青到了熙熙攘攘的农批市场，农产品琳琅满目。市场很大，采青跑完了整个市场，一路询问价格、比较品质、不停挑选品尝。最后腿跑断了，肚皮撑了，经过一番精心的挑选与协商，最终以8折优惠的价格，和一家店铺达成了礼包组合的购买协议。礼包组合不仅品类丰富，价格上完美地贴合公司的预算要求。礼包内精心囊括了五种口味各异的粽子，还搭配了五种时下热门的水果。\u003c/p>\u003cp>快到下班时间，鲍总打来电话询问情况，采青如何向他汇报工作呢？\u003c/p>\u003cp>\u003cem>&lt;角色扮演&gt;\u003c/em>\u003c/p>\u003cp>接下来，按照之前的分组，1人扮演鲍总，一人扮演采青。运用”三劳”汇报模型，在小组内交流和演练。5分钟后，我会请两组伙伴上台演练。\u003c/p>\u003cp>\u003cem>\u003cu>分组讨论 5min\u003c/u>\u003c/em>\u003c/p>\u003cp>（5分钟后）时间到，下面我们请二排的两组同学，用角色扮演的形式呈现鲍总和采青的对话。每组有5分钟的时间。\u003c/p>\u003cp>\u003cem>&lt;学习者案例一&gt;\u003c/em>\u003c/p>\u003cp>【鲍总】---雁子，【采青】---伟杰\u003c/p>\u003cp>鲍总：采青啊，最近不是要过端午节嘛，你去给公司员工采购一批端午节礼品，像粽子、水果之类的。\u003c/p>\u003cp>采青：可以。端午节礼品采购我上周就已经安排了，正好给您汇报下情况。虽然公司预算有限，但为了给大家更好的福利，我和商家争取到8折的优惠价格，采购了5种不同口味的粽子\u003c/p>\u003cp>鲍总：听起来为公司省很多钱啊！\u003c/p>\u003cp>采青：为帮公司节省预算，前期我做了大量的调研，考察了很多可以批量采购的批发商，一家一家地去问，讨价还价，最还让商家额外给我们送了一些粽子。之前我从来没敢这么做过，但为了公司的预算，我不要脸地去谈价格。\u003c/p>\u003cp>鲍总：难为你了\u003c/p>\u003cp>采青：我是尽我最大的努力去做这件事情。老板看能不能奖励我一张购物卡。\u003c/p>\u003cp>鲍总：你为公司省了这么多，一张购物卡没有问题。\u003c/p>\u003cp>\u003cem>&lt;学习者案例二&gt;\u003c/em>\u003c/p>\u003cp>【鲍总】---刑尧，【采青】---立鹰\u003c/p>\u003cp>鲍总：采青啊，给公司采购端午节礼包的事情，怎么样了？\u003c/p>\u003cp>采青：鲍总，礼包我已经谈妥了。我和采购商已经做好了一个约定，他们将以市场价8折的优惠给我们；而且礼品种类非常丰富，完全符合员工的需求；价格也完全在我们公司的预算之内。整个市场再也找不出比这个更好的品质和更低的价格了，性价比最高。\u003c/p>\u003cp>鲍总：那太好了，太棒了，你是怎么做到的？\u003c/p>\u003cp>采青：今天我把整个市场都跑了一遍，还打电话咨询了很多朋友，店里的每种粽子我都尝了一下，现在肚子还是胀的呐。每家每家地跑完，脚好痛啊。鲍总啊，现在也快到了下班时间，我能不能直接打车回家啊。今天我就不去公司了，明天再把具体的内容做成文件的给您汇报啊\u003c/p>\u003cp>鲍总：好的好的。辛苦了，你是我们的明星员工啊。\u003c/p>\u003cp>采青：谢谢鲍总。\u003c/p>\u003cp>拆书家：感谢两组伙伴的精彩演绎。掌声再次送给他们。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>\u003cem>&lt;提问设计&gt;\u003c/em>\u003c/p>\u003cp>职场上，干得好也要说得好，做好工作汇报，可以让我们在职场上如鱼得水。希望大家能在未来多多应用”三劳”汇报模型，助力升职加薪。接下来请大家思考一下，未来一个月内，有没有需要做工作汇报的场景。\u003c/p>\u003cp>比如公司重要项目出现紧急情况，你临危受命，经过2天不眠不休的工作终于把局面稳定住了，你怎么向老板汇报情况？\u003c/p>\u003cp>比如老家的朋友托你到香港买一个稀缺的药品，你跑了1天，走了很多店，终于找到了。你怎么告知他情况？\u003c/p>\u003cp>比如组织社群的户外活动，台风来临，你启动了应急预案，花费了很多工作重新定饭店定流程，你如何向大家汇报活动新安排呢？\u003c/p>\u003cp>\u003cem>&lt;指令&gt;\u003c/em>\u003c/p>\u003cp>请大家设想一下接下来可能会遇到的类似汇报情景，并在便签上记录一下时间、地点、人物，以及基本的事件关键词。只要预想一下可能发生的事情就可以了。时间有2分钟，2分钟后我们请一位伙伴分享一下。\u003c/p>\u003cp>\u003cem>\u003cu>思考+记录，2min\u003c/u>\u003c/em>\u003c/p>\u003cp>（2分钟后）时间到，我想请2位同学，来分享一下他设想的工作汇报场景。\u003c/p>\u003cp>\u003cem>&lt;学习者案例一&gt;\u003c/em>\u003c/p>\u003cp>Vicky：我要做一个正面管教的课程，下下周的家委联合会上，我要针对事前、事中的安排向组织者做一个汇报。\u003c/p>\u003cp>\u003cem>&lt;学习者案例二&gt;\u003c/em>\u003c/p>\u003cp>林歌：前几天一位酒吧老板给我推荐了一个驾校的客户（全国免费旅游卡），我计划去驾校后和推荐人汇报一下拜访的情况。\u003c/p>\u003cp>\u003cem>&lt;提问设计&gt;\u003c/em>\u003c/p>\u003cp>非常感谢两位同学的分享。学以致用是我们学习的目的，现在我们将”三劳”汇报模型应用到我们设想的场景中。请大家在小组内讨论分享，时间为2分钟，2分钟后我将邀请几位伙伴上台分享。\u003c/p>\u003cp>\u003cem>\u003cu>分组讨论，2min\u003c/u>\u003c/em>\u003c/p>\u003cp>（2分钟后）时间到，我想请刚才的两位同学用2分钟时间分享一下他的应用。\u003c/p>\u003cp>\u003cem>&lt;学习者案例一&gt;\u003c/em>\u003c/p>\u003cp>Vicky：\u003c/p>\u003cp>讲功劳：我用了一周的时间刻意练习和演练，发现课件初稿会超时二十到三十分钟，我计划删减掉不影响课程的完整度的那些不重要的内容。\u003c/p>\u003cp>说苦劳：我花了很多的时间和精力做课程的迭代，也非常重视这次课程。\u003c/p>\u003cp>要犒劳：希望举办方能推荐一位导师再帮我做一次现场磨课。\u003c/p>\u003cp>\u003cem>&lt;拆书家回应&gt;\u003c/em>\u003c/p>\u003cp>感谢Vicky的分享，按照功劳、苦劳、犒劳的顺序做了课程情况的汇报，非常清晰，如果能在每个段落前增加主题来分段，那你的汇报就会更加结构化。\u003c/p>\u003cp>\u003cem>&lt;学习者案例二&gt;\u003c/em>\u003c/p>\u003cp>林歌：\u003c/p>\u003cp>讲功劳：洽谈成功了！这次合作未来会帮驾校提升很多业绩。\u003c/p>\u003cp>说苦劳：洽谈过程不容易，驾校那边有很多疑虑，针对驾校老板会怀疑“可以免费全国旅游”的真实性，我还为他们提供了免费体验机会。\u003c/p>\u003cp>要犒劳：如果驾校那边的效果很好，到时候我还请你帮忙多介绍一些这样的企业家朋友。\u003c/p>\u003cp>\u003cem>&lt;拆书家回应&gt;\u003c/em>\u003c/p>\u003cp>感谢林歌的分享，那我们来看下林歌的分享。讲功劳-说他的产品可以带来的好处，节省的费用，带来的体验感。（说苦劳）冲突是由一些信任的问题，怀疑的问题，通过试用或其他口碑的方式去证明（应对），最后请老板多多介绍客户，是非常清晰的犒劳要求。让我们再次把热烈的掌声送给他。\u003c/p>\u003cp>【强有力的结束语】\u003c/p>\u003cp>在提案时用雪中送炭模型，想老板之所想，急老板之所急，老板的心腹干将就是你；工作汇报时用好”三劳”汇报模型，有功劳，有苦劳，让老板夸奖犒劳。期待大家升职加薪的好消息。以上就是我今天的拆书内容，感谢大家的共学。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1715845396000,"updated_at":1718881589000,"ria":true},{"id":16173,"topic":"学会讲故事，走心又动人","learn_goal":"","remark":"自我介绍、工作汇报、家庭沟通、朋友交流……\n你是否总是执着于讲述事实真相？\n致力于把道理说清楚、讲明白？\n然而事与愿违，你有理有据，对方却不买账，搞得关系紧张，事情进展也不顺利！\n\n你需要一种新技能：讲故事！\n故事四环节，帮你讲出走心的好故事，道理和事实都在故事里，也都进入听者的心里；\n激发共鸣法，帮你唤起听者的共鸣，让同频者惺惺相惜。\n\n学会讲故事，走心又动人；故事入人心，润物细无声。","level":"TF3-3","duration":70,"status":29,"type":0,"chaishujia":{"username":"美君grace","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】00’00”-01’21”，约1.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是美君，欢迎大家来参加我TF3-3的拆书过级。今天我的拆书主题是“\u003cstrong>学会讲故事，走心又动人\u003c/strong>”，时长大约70分钟。\u003c/p>\u003cp>我先用三个标签做个自我介绍：二级拆书家、终身学习者、成长型思维践行者。\u003c/p>\u003cp>\u003cstrong>【拆页间的逻辑关系】\u003c/strong>\u003c/p>\u003cp>今天的两个拆页来自于高琳老师的《故事力》，第一个是辨析故事的概念，初步学会讲故事的方法，第二个是在第一个讲故事方法的基础上叠加激发共鸣的方法，使故事具有更强的情感冲击力，让对话双方产生进一步的交流。两个拆页之间是递进关系。\u003c/p>\u003cp>\u003cstrong>【学习目标-总】\u003c/strong>\u003c/p>\u003cp>我们今天的学习目标是，在跟随我完成本次RIA现场学习后，学习者在想与他人产生深度连接时（WHERE），综合运用故事四环节法和共鸣激发法（澄清）讲出一个故事并获得对方回应（界定、行为）。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>结合今天的拆书内容，有需要分组讨论或者演练的环节，所以我们提前分组。我左手边的三位是一组，静静老师当组长，右手边的两位是二组，洁琼老师当组长。\u003c/p>\u003cp>接下来正式进入今天的拆书讲解。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】01’21” -03’04”，约1.5分钟\u003c/strong>\u003c/p>\u003cp>在阅读拆页前，大家先来看看这样一个场景，也是初次接触和了解拆书帮的一个必备环节。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>我的一位朋友听说我在拆书帮过级，就来问我拆书帮是什么，于是，我给她这样介绍：拆书帮是一个学习爱好者社群，是一个什么样的组织，在全国很多城市都有分舵。其中拆书法是一种什么样的方法论，强调学习要以自我为中心，而不是以知识为中心。\u003c/p>\u003cp>朋友听完，一脸冷淡地看着我。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>我先问问大家，在听我这样介绍的时候，你是什么感受？听完这个介绍，你觉得你了解拆书帮了吗？如果请你介绍拆书帮，你会怎么介绍来使更多新朋友加入拆书帮呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>朋友当时回了一句，“这是啥呀，没意思”，就转移话题聊别的了。\u003c/p>\u003cp>可见，我这样介绍拆书帮，朋友完全没有产生兴趣。\u003c/p>\u003cp>如果拆书帮的每个人都像我这样介绍拆书帮，那毫无疑问，加入的人也会越来越少，我们的影响力也会越来越低。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>如果我换一种方式来介绍拆书帮，讲讲我在拆书帮遇到了什么人、发生了什么事、有什么成长，效果就完全不一样了，具体怎么办呢？有意思教练创始人高琳老师的这本《故事力》介绍了一种通过有意识地组织语言向目标听众表达观点的方法，也就是讲故事。接下来，我们将对比讲故事和刚才场景中的方法的区别，一起感受讲故事是怎样走心地说理，让冷冰冰的道理和事实变成充满情感和温度的故事。\u003c/p>\u003cp>我们首先进入第一个拆页。\u003c/p>","ratings_count":1,"texts":[{"id":20260,"quote":"\u003cp>\u003cstrong>拆页一：总时长约21分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标-拆页1】03’04” -03’24” ，约20秒\u003c/strong>\u003c/p>\u003cp>在跟随我完成第一个拆页的RIA现场学习后，学习者能够在表达观点时（WHERE），运用故事四环节（澄清）讲出一个包含四个环节的故事（界定、行为）。\u003c/p>\u003cp>大家手上已经拿到拆页了，请用一分钟的时间阅读拆页一，完成后示意我。\u003c/p>\u003cp>\u003cstrong>【R原文片段】03’24” -04’25”，约1分钟\u003c/strong>\u003c/p>\u003cp>《故事力》PDF版第25页\u003c/p>\u003cp>我们每个人都喜欢听故事，因为我们就生活在无数的故事里面。人类通过故事去理解世界，解释事物的运作。从小到大，我们学习很多生存之道、人生哲理时都是通过故事来理解的。比如，当你两三岁的时候，父母告诉你不要玩火，他们一定不会说：“别玩火啊，玩火会导致三度烧伤。”因为这是事实，事实需要经验和知识的加持，才能被理解。但是如果父母说：“你别玩火啊，一会儿别把咱们家房子都烧了，再把你烧了，特别疼的！”你是不是就会马上停手？其实你爸妈就是编了一个故事让不懂事的你理解玩火的坏处。\u003c/p>\u003cp>故事之所以有那么大的冲击力，是因为我们无论有什么背景，都熟悉故事，都会很自然地用故事去解释一个不容易理解的情况。比如你突然听到办公室里两个同事大声嚷嚷，你脑子里就会开始编一个故事解释：为什么会这样呢？他俩有什么矛盾啊？我们都习惯用故事看待这个世界。\u003c/p>\u003cp>叙述，是按照逻辑顺序罗列事实，告诉你发生了什么。故事则帮助我们解释事情为什么发生，这个事件告诉我们一个什么道理，并且把这个因果和听者紧密联系起来。\u003c/p>\u003cp>叙述靠的是走脑，要有理有据。故事靠的是走心，需要情感和联想、想象的能力（见表1）。\u003c/p>\u003cp> 我看到大家都读完了。我来为大家拆解这个片段。\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】04’25” - 12’38”，约8分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页对比分析了两个概念：故事和叙述，以及二者的区别。\u003c/p>\u003cp>叙述是在掌握信息和证据后，通过罗列事实，告诉听者发生了什么，更讲求有理有据。\u003c/p>\u003cp>故事是阐释事情发生的原因，提炼事情背后的道理，针对性地为听者呈现具有画面感和情绪张力的内容，更走心。\u003c/p>\u003cp>为什么我们要学习讲故事呢？\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>在日常工作生活中，我们经常为了追求理性和客观，表达的内容全都是一条一条的事实，每一个观点都佐以证据来证明其可信度。\u003c/p>\u003cp>可是，这样冷冰冰的话语恰恰走不到人们的心里，更别提让人相信了。\u003c/p>\u003cp>比如，“不畏艰险、坚定地追寻梦想”这个话题，如果用叙述的方式讲出来，所有人一定会捂住耳朵立刻逃跑，但是，用故事的方式讲出来，就不一样了，最典型的就是《西游记》。可见，故事更能打动人心，让人信服。\u003c/p>\u003cp>我们再回到故事的概念，我已经写到白板上了，大家可以看到，故事的要点有三个：\u003cstrong>第一，阐释原因及道理；第二，针对性；第三，要走心。\u003c/strong>这三个要点之间没有明显的顺序关系，是并列的，经常以杂糅的形式出现。\u003c/p>\u003cp>光这样讲要点，还不够直观。下面，我们一起辨析四个案例。\u003c/p>\u003cp>\u003cstrong>【强化概念讲解——概念辨析】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（案例1-反例）\u003c/strong>\u003c/p>\u003cp>六岁的女儿晚上害怕做噩梦，不敢一个人睡觉。\u003c/p>\u003cp>妈妈说：首先，不是每次睡觉都会做噩梦，有时候也会做美梦啊，更多的时候什么梦都不会做；然后，一个人睡觉和妈妈陪着睡觉，对你做不做梦、做什么梦是没有影响的啊。\u003c/p>\u003cp>请大家说说，妈妈在讲故事吗？\u003c/p>\u003cp>学习者回答：不是。没有讲出背后的道理，也不够走心。\u003c/p>\u003cp>大家讲得很对。妈妈讲的话不符合故事概念的第一和三个要点。妈妈应该讲出女儿不敢一个人睡觉这个行为背后隐藏的原因，而且这些话听起来好像没有感情的机器人，非常冰冷，妈妈应该体会孩子的情绪，把情感讲出来。\u003c/p>\u003cp>\u003cstrong>（案例2-反例）\u003c/strong>\u003c/p>\u003cp>面试官请小王讲一个自己的成就事件。\u003c/p>\u003cp>小王：2022年，我个人的业务量是年初定的绩效指标的3倍，这让我充满成就感。\u003c/p>\u003cp>请大家说说，小王是在讲故事吗？\u003c/p>\u003cp>学习者回答：不是。\u003c/p>\u003cp>如果小王在公司内部年底述职的时候讲出这句话，那么效果比面试场合讲出来更好。因为面试官更想了解小王是怎样一个人，能力如何，显然这句话是实现不了的。所以，讲故事要有针对性。\u003c/p>\u003cp>\u003cstrong>（案例3-反例）\u003c/strong>\u003c/p>\u003cp>王主管汇报工作：我们小组负责的三个项目整体进展顺利，第一个项目最近开始做方案了；第二个项目方案改完第五稿，发给甲方了，不知道又会提什么意见，我们熬了好几个通宵了，要是再大改，就得麻烦领导亲自出马了；第三个项目的立项材料准备好了，明天送去相关部门报批。\u003c/p>\u003cp>请大家说说，王主管在讲故事吗？\u003c/p>\u003cp>学习者回答：不是。\u003c/p>\u003cp>王主管在第二个项目中遇到了难题，想争取领导关注和相应的资源。故事概念的第三个要点是“要走心”，所以，她应该重点把第二个项目中遇到的困难和小组成员们辛苦的付出都讲出来，那么争取资源也就顺理成章了。\u003c/p>\u003cp>\u003cstrong>（案例4-正例）\u003c/strong>\u003c/p>\u003cp>毕业二十年同学聚会。同学们互相介绍自己20年来的经历。\u003c/p>\u003cp>小强说：要是没有他，我今天就不会站在这里。5年前，我得了重病，恢复也不顺利，术后一年都不能正常走路，我因此抑郁了。非常幸运，我得到了一位同学的帮助，要是没有他，我不可能从抑郁中走出来。我要对他说一句：谢谢！他就是张大明。\u003c/p>\u003cp>这个案例是故事吗？\u003c/p>\u003cp>学习者回答：是。\u003c/p>\u003cp>这个案例\u003cstrong>很走心\u003c/strong>，充满情感，不是简单的罗列事实，\u003cstrong>有针对性\u003c/strong>，面对的是老同学们，讲的与之相关的内容，而且讲出了事情背后的\u003cstrong>原因\u003c/strong>。故事概念的三个要点都具备。\u003c/p>\u003cp>我观察到一点，大家在听这四个案例的时候，脸上的表情有很明显的不同，前三个，大家表现很平淡，第四个，大家的神色也变得很凝重，注意力也更集中。可见，故事的魅力显而易见。\u003c/p>\u003cp>现在，让我们的身份从读者转变为作者，我们怎么才能讲出一个具备三个要点的故事呢？\u003c/p>\u003cp>首先，要有个\u003cstrong>吸引人的开头\u003c/strong>，第一句话出口就要告诉听者，“这是你想听的”；第二步，讲主人公行事遭遇\u003cstrong>冲突\u003c/strong>，情节的起伏会带来\u003cstrong>情感的波动\u003c/strong>，紧抓听众注意力；第三步，面对冲突主人公采取\u003cstrong>行动\u003c/strong>，讲出\u003cstrong>这么做的原因以及依据的道理\u003c/strong>，把表象上的事情的\u003cstrong>底层逻辑\u003c/strong>展示出来；最后，讲行动带来的\u003cstrong>改变/收获\u003c/strong>，也就是\u003cstrong>故事的结局\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>所以，我在此基础上，拆解出一个讲故事的框架——故事四环节：\u003c/p>\u003cp>\u003cstrong>（1）开头。\u003c/strong>开头用来吸引听众，可以是交代背景，可以是核心主旨句，目的是用引人入胜的开头吸引听者的注意力。比如，案例4中的开头，“要是没有他，我今天就不会站在这里。”就是用主旨句吸引同学们的注意。\u003c/p>\u003cp>\u003cstrong>（2）冲突。\u003c/strong>讲主人公遭遇了怎样的冲突和困难，要突出强调冲突的激烈程度、困难程度。案例4中，主人公经历了重病、手术、抑郁等遭遇。\u003c/p>\u003cp>\u003cstrong>（3）行动。\u003c/strong>讲主人公采取了哪些行动来应对冲突，同时，讲出选择这么做的原因和道理，这部分的目的是引出人物的高光时刻。案例中，主人公得到了同学的帮助，听众也会推断出同学是一位怎样的人。\u003c/p>\u003cp>\u003cstrong>（4）结局。\u003c/strong>讲主人公的行动收获了怎样的结局，可以是完美的大结局，也可以遗憾的结局。结局给故事划上了句号，同时可以再把故事背后的“理”讲出来。案例中的主人公恢复身心健康、对同学充满感激、同学对主人公的倾力相助、人性光辉等等。\u003c/p>\u003cp>哪些情况下可以使用这个方法呢？\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>当你需要展示自己，让别人对你产生好奇时；当你需要表达观点、说服别人，想让对方受到启发或采纳你的观点做出行动时，你就可以使用故事四环节这个方法，给对方讲一个故事，让对方听进去、感兴趣、去行动。\u003c/p>\u003cp>当你不需要影响听者的时候，这个方法就不适用了。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>上个月，我想告诉一位刚认识的诺友婧同学当众开麦并不可怕。\u003c/p>\u003cp>我说：\u003c/p>\u003cp>经过这段时间的交流，你能想象我原来是个社恐吗？\u003cstrong>（开头）\u003c/strong>\u003c/p>\u003cp>去年参加读书营，我被拉去做《掌控习惯》前三章的分享，要在100多人面前开摄像头、开麦、共享PPT！我一下就慌了，这根本不可能！我紧张到没办法思考，连PPT都写不出来。\u003cstrong>（冲突）\u003c/strong>\u003c/p>\u003cp>后来，我想我不能退缩。于是，静下心花了一天的时间把书读了好几遍，做好了PPT，又演练了好几遍。\u003cstrong>（行动）\u003c/strong>\u003c/p>\u003cp>最后，成功地在既定时间里完成了分享。一位导师还加了我微信，说PPT写得好，我讲得也好。\u003cstrong>（结局）\u003c/strong>\u003c/p>","interaction":"\u003cp>回到我们今天的主题，接下来进入大家学以致用的环节啦。\u003c/p>\u003cp>\u003cstrong>【A学习者拆为己用】12’38”-24’30”，约12分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2编剧本】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>现在，请每位小伙伴独立编写一个小剧本，需要设计人物、情节变化（包括：起因、经过 、结果）和当时双方的对话、动作等。\u003c/p>\u003cp>故事背景和人物设计，可以是你未来有可能遇到的场景。记得用上我们今天分享的“故事四环节”，把能让你产生联想的关键词句写在我给大家的剧本框架表里，不需要写长篇大论。时间5分钟，5分钟后我会邀请一位小伙伴来分享他设计的故事。\u003c/p>\u003cp>请大家开始写吧，大家有疑问可以问我。\u003c/p>\u003cp>学习者：是写未来吗？\u003c/p>\u003cp>我：是的，是未来可能发生的情况，比如未来一周、明天。要写可能真实发生的场景，比如孩子写作业、夫妻沟通等等。在写剧本的时候，把故事四环节用起来，去设计你的沟通内容，写出来双方的对话，也写出你可能发生的心理活动、情绪、感受等等。\u003c/p>\u003cp>我看大家都写得差不多了，哪位伙伴来分享一下？洁琼老师，请你用一两分钟的时间分享你的剧本。\u003c/p>\u003cp>\u003cstrong>学习者洁琼案例记录：\u003c/strong>\u003c/p>\u003cp>洁琼分享完，我问洁琼：我想问一下，小A使用故事四环节对吗？\u003c/p>\u003cp>洁琼：对的。\u003c/p>\u003cp>我：那你可以把四个步骤再提炼一下吗？\u003c/p>\u003cp>洁琼：开头就是，小A找老板，“老板，二季度结束了，我来找您对一下KPI的得分情况。”冲突是“期初的目标是450万，现在二季度结束了，根本完不成，而且是有客观原因的。”行动是“小A主动找老板沟通，讲年初丢了项目，但是目标却没有修改，导致目前目标完不成，提出修改目标的请求。”\u003c/p>\u003cp>我：我的理解是，期初定了一个高目标，年初丢了项目，这里是冲突，因为这个项目在目标实现中占了很大的比重。\u003c/p>\u003cp>洁琼：对哦，这里也是冲突，是小A遇到的冲突。\u003c/p>\u003cp>我：那结局是什么呀？\u003c/p>\u003cp>洁琼：结局是“老板同意修改下季度目标，小A很满意。”\u003c/p>\u003cp>我：可见，小A提前用故事四环节法设计自己的沟通内容，她收获了一个令自己满意的结局。特别好。\u003c/p>\u003cp>感谢洁琼的分享！你很好地运用了故事四环节，剧本的编写也很生动形象，让人身临其境。\u003c/p>\u003cp>\u003cstrong>【过渡】\u003c/strong>\u003c/p>\u003cp>好，以上就是我们今天学习的第一个拆页。大家学习了一个讲故事的框架——故事四环节，知道了讲出一个好故事，可以让自己的话走到听者心里。那么，你想不想让你的故事力再上一个台阶呢？我们来看看第二个拆页能带给我们什么。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":20261,"quote":"\u003cp>\u003cstrong>拆页二：总时长51.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标到解释量表自测意义：24’30” - 27’05”，约2.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习目标-拆页2】\u003c/strong>\u003c/p>\u003cp>在跟随我完成第二个拆页的RIA现场学习后，学习者能够在需要与他人产生深度连接的社交场合（WHERE），运用共鸣激发法（澄清），讲述一个包含自己经历、感受、信念三个层次的故事，并获得他人的回应（界定、行为）。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】设计量表自测\u003c/strong>\u003c/p>\u003cp>在亮出第二个拆页之前，我们先来做一套自测题。课前已经发给大家了。\u003c/p>\u003cp>表格中有5条描述，每条对应有6个分值。表格上标注了分值的含义，1为非常不符合，6是非常符合。\u003c/p>\u003cp>请你用一分钟根据自己的第一感觉和实际情况阅读题目并打分，完成后把总分加起来。\u003c/p>\u003cp> \u003cstrong>【I解释量表自测意义】\u003c/strong>\u003c/p>\u003cp>我看到大家都完成了。我来解释一下这个自测题，这套题是用来测试大家的社交力的，在这里，我把社交力简化处理成共情力、沟通力、表达力的结合。\u003c/p>\u003cp>所以，总分在5-15分的小伙伴，你今天真是来着了，学完今天的拆页，你会get一个新方法，社交力也会大大提升。总分在16-25之间的伙伴，你的社交力非常棒呢，今天的拆页学习也会让你持续精进，助力你成为社交达人。有没有总分在26-30之间的呢？有一位！太棒了！你在生活中一定像太阳一样温暖着所有人，今天的课程对于你来说就是锦上添花，可以帮助你梳理自己太阳的行为背后的发心，使你未来在社交中更加游刃有余。\u003c/p>\u003cp>接下来，请大家带着自己的测试结果，进入第二个拆页。\u003c/p>\u003cp>请大家用一分钟时间阅读拆页二，完成后示意我。\u003c/p>\u003cp>\u003cstrong>【R原文片段】27’05” - 28’00”，约1分钟\u003c/strong>\u003c/p>\u003cp>第二个拆页来自《故事力》PDF版第174-175页\u003c/p>\u003cp>我有一个程序员朋友，兼职做精油芬芳师，她成功地把Hubert这个“钢铁直男”转化成了她的忠实客户，我们家现在到处都是他买来的精油。我这个朋友经常跟别人讲起她一个程序员为什么卖起精油的故事：\u003c/p>\u003cp>前年，我妈妈甲状腺结节突然发炎增大。我送她进手术室，换好衣服，妈妈对我说：“我一会儿就出来了，不用害怕。”我知道其实这话应该是她说给自己的。我看着她花白的头发，穿着手术服的背影消失在手术室的大门里，心里特别不是滋味，那是一种你想要保护却无能为力的无助。\u003c/p>\u003cp>虽然手术很顺利，但是术后妈妈一直不舒服，精神萎靡，唉声叹气，伤口也恢复得很慢，还有积液。医生建议开一些激素类的药膏涂，妈妈觉得不好。我咨询了我的精油老师，给她配了精油。一开始，她特别不爱用，觉得这都是在骗人。可也没有其他更好的办法，就试了试。神奇的事情就这样发生了，她的伤口很快消肿、结痂，长出了新肉。妈妈的心情也好了起来，看到她越来越好，我就想把这一份喜悦延续下去，传递给更多的人。\u003c/p>","explains":"\u003cp>好，我看到大家都读完了。接下来我为大家拆解这个片段。\u003c/p>\u003cp>\u003cstrong>【I拆书家讲解引导】28’00” - 34’50”，约7分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页讲了一个案例。一位程序员讲述自己跨界兼职销售精油的故事。\u003c/p>\u003cp>\u003cstrong>【和学习者简短互动】\u003c/strong>\u003c/p>\u003cp>首先，大家在这个故事有没有看到第一个拆页拆解的故事四环节呢？\u003c/p>\u003cp>学习者：有。\u003c/p>\u003cp>开头在哪里？第一句话，交代背景，同时也吸引我们听故事。\u003c/p>\u003cp>冲突是什么？学习者：妈妈做手术、我的无助、妈妈术后恢复慢。\u003c/p>\u003cp>行动是什么？学习者：我配置了精油，妈妈尝试。\u003c/p>\u003cp>结局是什么？学习者：妈妈伤口快速恢复，我想延续喜悦、传递给更多人。\u003c/p>\u003cp>特别好，可见大家对第一个拆页已经掌握了。\u003c/p>\u003cp>我要再问大家一个问题，大家在看这个故事的时候产生了哪些感受呢？\u003c/p>\u003cp>学习者：看到妈妈做手术以及术后恢复慢，很着急，很心疼。\u003c/p>\u003cp>说得特别好，看来这个故事非常走心，让我们也跟着感同身受了。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>这位程序员能讲出这么走心的故事，与她优秀的社交力是分不开的，能共情、会表达、善沟通。\u003c/p>\u003cp>很多人把社交力强狭隘地理解为能言善辩，于是，为了提升自己的社交力，要么是强迫自己多表达，见谁都能唠半小时；要么是奔走于各种场合，致力于广交天下好友。这样做的结果就是，看似朋友遍天下，实际上都是低质量社交，深度不够。\u003c/p>\u003cp>也就是说，我们真正需要的是有效社交、高质量社交，简单来说，当你需要帮助时，你知道找谁帮忙，而且TA一定会帮你；当你情绪低落，你知道找谁倾诉，TA一定会给你全然的倾听。\u003c/p>\u003cp>那怎么做才能提升社交力，让自己拥有有效的、高质量的社交圈呢？\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>结合拆页和我们的学习目标，我拆解出了共鸣激发法：\u003c/p>\u003cp>（1）共经历。讲述一个与对方经历类似的事件。用共同经历激发对方共鸣。拆页中，每个人都有妈妈，每个人都会头疼脑热、生病，妈妈也会生病，这样的共同经历吸引听者去听故事。\u003c/p>\u003cp>（2）共感受。讲述你对于某事的感受，而且是对方也可能会有的感受。用共同感受激发对方共鸣。拆页中，妈妈生病做手术，让子女很心疼，术后恢复慢，妈妈情绪低落，子女也很心疼，这也让听者跟着产生情绪的波动，产生同样的感受，妈妈用了精油恢复快，听者的心情也变得愉悦起来，发出“太好了”的感叹。\u003c/p>\u003cp>（3）共信念。讲述你的故事，传递鲜明的信念和观点，同样，这也是对方认同的。什么是信念？信念就是你说话做事的发心。比如，拆页最后，“看到她越来越好，我就想把这一份喜悦延续下去，传递给更多的人。”正是因为有了“传递喜悦、传递爱”的信念，才有了她销售精油的决定和纷至沓来的客户。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>可能会有小伙伴想，和人交谈需要这么复杂吗，经历、感受、信念，这也太多层次了吧？\u003c/p>\u003cp>我能理解，和人连接也太难了，不过，我们既然想和对方建立紧密的关系，就需要从表象上的经历深挖出TA不为人知的感受，告诉对方“你懂那种感觉”，再深一层次，两个人信念一致，才更有共同语言，也就是所谓的同频共振。共鸣激发法能让我们快速直达核心层，起到一个故事，三重功效的作用。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>大家从共鸣激发法中一定发现了，每一条都要求你讲出来的内容是和对方有一致性的，这就说明，你要对你的社交目标方有一定的了解，在原先的较浅层次了解的基础上，通过此次对话，再加深一层，逐渐形成深度连接。\u003c/p>\u003cp>所以，在表达和展示自己的个性、观点、需求并需要获得对方回应的时候，你需要先对社交目标方具备较浅层次了解，然后运用共鸣激发法去和对方对话、沟通。\u003c/p>\u003cp>当你完全不了解对方时，或者当你并不需要获得对方回应的时候，这个方法就不适用了。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>接下来，我举一个我自己的例子。\u003c/p>\u003cp>我在诺言社区（一个线上社群），阅读了一位诺友的动态，她组建了一个亲子阅读的读书会。我有孩子，我也和孩子每天保持亲子阅读的习惯，还给孩子和她的几个小朋友讲绘本，我想知道她是怎么组建起来这个读书会的，既能认识更多的优秀妈妈，又能让孩子和小伙伴一起读书、讨论。\u003c/p>\u003cp>为了了解她，我阅读了她的更多关于读书会的分享和读书会的记录文。\u003c/p>\u003cp>然后，有一天，我给她发了下面这条信息：\u003c/p>\u003cp>“荷荷，你好，我是美君。从上个月起，我每周给我的孩子和几个小朋友讲一次绘本，通过促进孩子们问问题和让孩子们回答问题，我成了收获最大的人\u003cstrong>（共经历）\u003c/strong>。孩子们对于书中主人公情绪的感知、细节的把握都特别准，看到伤心的地方，连最好动的孩子都安安静静地沉浸其中了，让我看了特别感动，我也更能理解孩子了\u003cstrong>（共感受）\u003c/strong>。看到孩子们那么热爱阅读，可是，我又实在是精力不够，想像你们的四季亲子悦读一样组建一个亲子读书会，带动更多的家长参与进来，一起共建\u003cstrong>（共信念）\u003c/strong>。请问你是怎么做到的呢？”\u003c/p>\u003cp>很快，荷荷就回复我了，表示她很开心看到我的信息，还约我的时间。最后，我们通过电话进行了联系。\u003c/p>\u003cp>从这个案例中，大家可以看到，我发出的这条信息里，包含了我的经历，我的感受，我的信念，这些也都是能唤起荷荷共鸣的经历、感受和信念，所以她能愉快地回应我，给我提供帮助，也就成了顺理成章的事情。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A学习者拆为己用】34’50”-75’15”，约41分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【模拟演练】34’50”-42’16”，约8分钟\u003c/strong>\u003c/p>\u003cp>拆页的讲解就到这里，在开始正式的讨论之前，我们先做一场模拟演练。\u003c/p>\u003cp>我先给定一个场景：你叫小强，对便签读书法很感兴趣，但是对于怎么高效写便签有疑问和困难；你得知青岛分舵的张老师是这方面的专家，就想向她咨询高效写便签的方法。\u003c/p>\u003cp>现在，请大家两两结对子，进行模拟演练，一个人扮演张老师，一个人扮演小强。请小强运用刚才学过的共鸣激发法和张老师交流，看能获得张老师怎样的回应。\u003c/p>\u003cp>模拟演练时长三分钟，结束后，我会邀请一对伙伴来现场演练。\u003c/p>\u003cp>请大家注意，我们的目的是学习使用共鸣激发法，而不是解决小强的问题。\u003c/p>\u003cp>请静静和熊瑛两位来现场演练。\u003c/p>\u003cp>静静扮演小强，熊瑛扮演张老师。\u003c/p>\u003cp>学习者现场演练：\u003c/p>\u003cp>小强：张老师好，我是便签营的新晋学员，我听说张老师在拆书帮是元老级的拆书家，很荣幸认识您，想跟您探讨怎么高效地写便签。因为我遇到了一个棘手的问题，就是我没有办法高效地用便签法去读书\u003cstrong>（共经历），\u003c/strong>我很着急\u003cstrong>（共感受）\u003c/strong>。如果能得到您的指点，我会感觉非常开心。如果我掌握了这种高效写便签的方法，就能像张老师您一样，把这个好方法推广给更多人，帮助更多的人得到提高\u003cstrong>（共信念）\u003c/strong>。\u003c/p>\u003cp>张老师：好的，我们详细讲一讲哈。\u003c/p>\u003cp>小强：谢谢张老师。\u003c/p>\u003cp>感谢两位。时间关系，另一组就不做分享了。\u003c/p>\u003cp>\u003cstrong>【A3微行动学习】42’16”-74’37”，约31.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 1.明确问题 42’16”-45’55”，约4分钟\u003c/strong>\u003c/p>\u003cp>大家在刚才给出的场景中已经练习使用过共鸣激发法了。\u003c/p>\u003cp>结合刚才的练习和自己的经历，你觉得共鸣激发法的三步里，哪一步比较简单，哪一步是最难的呢？\u003c/p>\u003cp>\u003cstrong>（讨论）\u003c/strong>请大家在我们最开始分好的两个大组内讨论，时长2分钟，然后每组组长来分享你们的讨论结果。\u003c/p>\u003cp>讨论纪要：\u003c/p>\u003cp>静静：我觉得是共信念，信念是与认知有关的。\u003c/p>\u003cp>熊瑛：我也觉得，而且不同的人有不同的经历，经历也会造成信念不同。\u003c/p>\u003cp>洁琼：共感受和共信念都挺难，相比之下，还是共信念难。我刚才演练的时候就感觉到了，经历和感受都比较容易，信念很难把握。\u003c/p>\u003cp>红艳：嗯，确实是共信念难。\u003c/p>\u003cp>\u003cstrong>（分享）\u003c/strong>时间到，组长分享：哪一步是最难的。我在白板上记下来。\u003c/p>\u003cp>\u003cstrong>一组静静\u003c/strong>：第三步，共信念。\u003c/p>\u003cp>\u003cstrong>二组红艳\u003c/strong>：我们也觉得是共信念。\u003c/p>\u003cp>现在请两组组长再说说你们为什么觉得这一步最难。\u003c/p>\u003cp>\u003cstrong>一组静静\u003c/strong>：信念属于认知层面，两个人如果认知不同，三观不同，就很难共到一起。\u003c/p>\u003cp>\u003cstrong>二组红艳\u003c/strong>：信念跟个人过往的经历和认知水平是有关系的，而且会比较稳定，不容易发生变化，所以你跟比较陌生的人实现共信念就会比较难。\u003c/p>\u003cp>两组都陈述了自己的理由，现在双方有没有被对方的理由说服，要改变主意的呢？\u003c/p>\u003cp>我们两个组的观点是一致的，都认为共信念最难。\u003c/p>\u003cp>我们再确认一下，我们今天要讨论解决的问题是共信念。（明确问题）\u003c/p>\u003cp>大家同意吗？同意。\u003c/p>\u003cp>\u003cstrong>2.引导讨论导致问题的本质原因 45’55”-53’18”，约7.5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（讨论）\u003c/strong>现在，我们在小组内针对“共信念”，进行挖掘问题本质的讨论，请大家结合自己的经历，思考一下，“共信念”的根源是什么，也就是导致“共信念”最难的本质原因是什么。\u003c/p>\u003cp>请小组长组织组内讨论，并在白纸上记录你们小组讨论出来的本质原因。讨论时长3分钟。然后请各组代表来分享你们讨论出来的问题本质。\u003c/p>\u003cp>讨论纪要：\u003c/p>\u003cp>红艳：经历会影响信念，也就相当于原生家庭。\u003c/p>\u003cp>洁琼：信念很难共，原因还有一个，思维方式不同。共信念就是我想跟对方达成一个统一的认知，但是我不了解对方，所以难。\u003c/p>\u003cp>熊瑛：通常，想连接的人都是比自己强的，去共信念想要获得他的回应，会胆怯、害怕、自卑。\u003c/p>\u003cp>静静：再就是过往的经历，你要去了解，因为不了解经历，就不了解信念的来源。\u003c/p>\u003cp>\u003cstrong>（分享）\u003c/strong>时间到。请代表分享你们小组的讨论结果。我在白板上做记录。\u003c/p>\u003cp>\u003cstrong>一组静静\u003c/strong>：我们讨论出来两条原因，第一是，\u003cstrong>自卑心理\u003c/strong>，害怕说错了，得不到对方的回应，或者得不到自己想要的回应；第二是和对方的\u003cstrong>人生经历不同\u003c/strong>，把握不准对方的信念。\u003c/p>\u003cp>\u003cstrong>二组红艳\u003c/strong>：我们讨论出来三条原因，第一是\u003cstrong>双方经历不一样\u003c/strong>，看待事情的观点不一样；第二是和人的\u003cstrong>思维方式有关，不同\u003c/strong>的人对一件事的观点不一样；第三是，\u003cstrong>和对方不熟悉，了解不够深\u003c/strong>，也没办法知道对方的信念。\u003c/p>\u003cp>\u003cstrong>3.明确问题本质 53’18”-62’25”，约9分钟\u003c/strong>\u003c/p>\u003cp>现在，大家看着白板上讨论出来的原因，我们一起分析一下问题的本质到底是什么。\u003c/p>\u003cp>\u003cstrong>（合并总结）\u003c/strong>我们总结归纳一下，一组的第二条和二组的第一条基本一致，可以合并为同一条，所以，我们整合出4条原因：\u003c/p>\u003cp>&lt;1&gt; 自卑心理。\u003c/p>\u003cp>&lt;2&gt; 人生经历不同。\u003c/p>\u003cp>&lt;3&gt; 思维方式不同。\u003c/p>\u003cp>&lt;4&gt; 了解不够深。\u003c/p>\u003cp>\u003cstrong>（讨论）\u003c/strong>请大家在小组内讨论，在这4条原因中选出一条最本质的原因。时长3分钟。\u003c/p>\u003cp>请两组代表讲一下你们认为的问题本质并陈述理由。\u003c/p>\u003cp>\u003cstrong>1组认为是\u003c/strong>，我们认为是思维方式不同。经历是浅层次的；自卑心理也是因为思维方式不同导致的；了解不够深，也是有办法的。\u003c/p>\u003cp>\u003cstrong>2组认为是\u003c/strong>，我们认为是不了解对方的观点。“共信念”要求我和对方产生信念层面的共鸣，人生经历是没法改变的，我需要调整自己的思维方式，自卑也是我可以自己把控的，所以，对方的观点是什么，是我要考虑的问题。观点就是指信念。\u003c/p>\u003cp>两个小组的观点不一样，在听了对方的解释后，有没有哪个小组被说服，要改变自己的观点呢？\u003c/p>\u003cp>没有，好，请大家现在自由讨论一下。\u003c/p>\u003cp>\u003cstrong>讨论纪要：\u003c/strong>\u003c/p>\u003cp>静静：二组讲的不了解对方的观点和信念，我觉得即使你了解后，双方的思维方式不同，也还是很难“共”。\u003c/p>\u003cp>红艳：因为我们觉得人的思维是比较固定的，很难去改变。但是我需要和对方连接，拉近关系，我就需要主动调整我的想法。\u003c/p>\u003cp>静静：你认为可以调整到对方的维度吗？\u003c/p>\u003cp>时间关系，我们来投票吧，一起选出绝大多数伙伴认同的问题本质。同意第一条“思维方式不同”的请举手，全票通过。二组改变主意了。\u003c/p>\u003cp>\u003cstrong>（总结）\u003c/strong>好，我们选出了“共信念”的问题本质，是：思维方式不同。\u003c/p>\u003cp>\u003cstrong>4.引导分组讨论解决问题 62’25”-67’18”，约5分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（讨论）\u003c/strong>问题本质确定了，我想问问大家，你们觉得这个问题解决到什么程度就可以了？想到了就直接分享。\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：如果我能了解对方的观点和信念，就可以解决思维方式不同这个问题了。\u003c/p>\u003cp>我：这就是我们的目标，找出解决方案。\u003c/p>\u003cp>现在，大家针对“思维方式不同”这个问题本质，继续在小组内讨论，形成一个解决方案，请组长做记录，把组内的讨论结果写在白纸上。3分钟后由代表分享。\u003c/p>\u003cp>请大家注意，办法要尽可能具体、可以直接操作的。\u003c/p>\u003cp>\u003cstrong>讨论纪要：\u003c/strong>\u003c/p>\u003cp>静静：思维方式不同，首先需要我们去了解对方的观点，怎么了解呢？\u003c/p>\u003cp>熊瑛：搜索网络、去找他的朋友，了解他是什么样的人，他有什么样的信念。\u003c/p>\u003cp>红艳：找他的言论，他做过什么事。\u003c/p>\u003cp>洁琼：还有他关注的东西，去看访谈节目。\u003c/p>\u003cp>静静：他做的事情，他感兴趣的领域，直播的时候输出的内容。\u003c/p>\u003cp>红艳：主动去找他沟通交流。\u003c/p>\u003cp>\u003cstrong>5.讲解讨论成果。各小组代表分享，拆书家引导总结解决方案 67’18”-74’37”，约7分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（分享）\u003c/strong>请小组代表讲解讨论出来的解决办法。\u003c/p>\u003cp>\u003cstrong>一组静静\u003c/strong>：我们讨论出来三条。第一，通过社交网络了解他的经历和表达的观点；第二，通过他的社交圈了解他关注的事情以及他的言论；第三是转变自己的思维方式。\u003c/p>\u003cp>\u003cstrong>二组红艳\u003c/strong>：我们讨论出来两条。第一是搜索有关对方的事情、爱好、言论、观点等；第二是直接询问，主动和对方交流，去问他的观点和信念。\u003c/p>\u003cp>\u003cstrong>（合并总结）\u003c/strong>我们大家一起来总结一下解决方案。\u003c/p>\u003cp>一组第一条和第二条，二组第一条，内容基本是一致的，可以用“主动收集对方信息”来概括；二组第二条，直接沟通，可以运用故事四环节法。\u003c/p>\u003cp>\u003cstrong>学习者\u003c/strong>：这两条就可以了，这两条可以实现转变自己的思维方式。\u003c/p>\u003cp>\u003cstrong>（形成并宣布）\u003c/strong>所以，\u003cstrong>我们最终的解决方案\u003c/strong>是：\u003c/p>\u003cp>第一点，主动收集对方的信息；\u003c/p>\u003cp>第二点，直接沟通。\u003c/p>\u003cp>好，感谢大家的积极参与。我们简单回顾一下，最开始，我们确定了第几步是今天要解决的一个问题“共信念”，这是我们明确的表象问题，然后，我们深入讨论找到了“共信念”的问题本质，也就是我们需要解决“思维方式不同”这个根源，最后大家一起找到了详细具体的解决方案，有两点，分别是主动收集对方信息和直接沟通。\u003c/p>\u003cp>今天的问题讨论和解决就先到这里。\u003c/p>\u003cp>\u003cstrong>【A2】布置任务74’37”-75’15”，约1.5分钟\u003c/strong>\u003c/p>\u003cp>接下来，我给大家布置一个课后任务。\u003c/p>\u003cp>\u003cstrong>（作业）\u003c/strong>请你思考，你的周围有没有你想要深度连接的伙伴，或许是你们单位新来的同事，或许是你的一位邻居，或许是某位拆书家，等等。在未来一周，请你主动联系一次这位伙伴，运用共鸣激发法，分享你的经历、感受、信念，看看能获得怎样的回应吧。\u003c/p>\u003cp>完成任务的小伙伴，请把你和对方交流的微信截图发给我，我会针对你的实践做出反馈。我非常期待你的反馈！\u003c/p>\u003cp>学习者静静的作业：\u003c/p>\u003cp>\u003cstrong>【结束语】75’15”-76’00”，约1分钟\u003c/strong>\u003c/p>\u003cp>今天的拆书已到尾声。我们一起回顾一下。\u003c/p>\u003cp>故事四环节，“开头-冲突-行动-结局”，帮你讲出走心的好故事，道理和事实都在故事里，也都进入听者的心里；\u003c/p>\u003cp>激发共鸣法，“共经历，共感受，共信念”，帮你唤起听者的共鸣，让同频者惺惺相惜。\u003c/p>\u003cp>学会讲故事，走心又动人；故事入人心，润物细无声。\u003c/p>\u003cp>感谢大家来参加我TF3-3的过级，我们下次活动再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1688540668000,"updated_at":1689695957000,"ria":true},{"id":15867,"topic":"激发共鸣，提升社交力","learn_goal":"","remark":"你的社交是有效社交吗？\n遇到问题，你能快速找到准确的人寻求帮助吗？\n遇到问题，TA能迅速回应你并给予帮助吗？\n如果不能，你需要提升你的社交力了！\n共鸣激发法，让你的社交力up up up！","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"美君grace","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是美君，欢迎大家来参加我TF3-2的拆书过级。今天我的拆书主题是“\u003cstrong>激发共鸣，提升社交力\u003c/strong>”，时长大约20分钟。\u003c/p>\u003cp>我先用三个标签做个自我介绍：拆书家、终身学习者、成长型思维践行者。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>结合今天的拆书内容，有需要分组讨论或者演练的环节，所以我们到时候会两两一组进行角色扮演。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>今天我的拆书主题是“\u003cstrong>激发共鸣，提升社交力\u003c/strong>”，拆页片段来自高琳的《故事力》一书。在拆解前，大家先来看看这样一个场景。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>小王新加入一个读书社群，第一次参加线下聚会，一共有十个人，聚会开始前，小王心想：我今天要多表达，在一个半的小时里，让大家记住我，我记住每个人的独特特征。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>如果你是小王，你会怎么做呢？怎么才能在一个半小时的时间里，让别人记住你，你记住每个人呢？做个光彩夺目的自我介绍，听听别人的自我介绍，然后和每个人单聊一次吗？你有没有过类似的经历，你是怎么做的呢？除了你自己的做法、小王的做法，还可以怎么做呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>自我介绍输出信息和听自我介绍获取信息，都是单向的；和伙伴们单聊，听起来是个不错的主意。但是，小王对于聊什么没有计划，按照常见情况，大概率是闲聊。这样一来，小王的目标是根本无法实现的。一次两次，好像没什么关系。但如果每次都是这样，参加了那么多社交活动，好像加了不少微信好友，但是后续又没有发生什么实实在在的交集。这是纯纯的无效社交啊！成年人最宝贵的时间和精力，就是这么浪费的！而且，无法和人建立深度关系，会导致你在职场、择偶、家庭、友谊等各类关系中碰壁受阻，也会给你带来无尽的内耗。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>记住别人和被人记住，建立深度关系的底层其实是社交能力。可见，社交力就是我们必须修炼的一门功课。像小王这样做，发生的是表象上的信息交互，这并不是有效社交的体现。《故事力》一书告诉我们，只有情感上产生了共鸣才能拉近人与人的距离。所以，我们想摆脱无效社交，就应该在目标的设定和实际的行动中以激发伙伴们的共鸣为核心。\u003c/p>\u003cp>那么，怎么才能激发共鸣呢？我们来看今天的学习内容。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在需要与他人产生深度连接的社交场合，运用共鸣激发法，讲述一个包含自己经历、感受、信念三个层次的故事，并获得他人的回应。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】设计量表自测\u003c/strong>\u003c/p>\u003cp>在学习怎么激发共鸣之前，我们先来做一套自测题。\u003c/p>\u003cp>下面表格中有5条描述，每条对应有6个分值，如果你觉得这条描述非常符合你的特质，打6分，符合，打5分，比较符合，4分，比较不符合3分，不符合2分，非常不符合，打1分。\u003c/p>\u003cp>请你拿出纸和笔，用一分钟的时间阅读并完成题目。\u003c/p>\u003cp>我看到大家都放下笔了，完成的伙伴，请把5个分值加起来，算出总和。\u003c/p>\u003cp>大家来说说，自己得了多少分。\u003c/p>\u003cp>\u003cstrong>【I解释量表自测意义】\u003c/strong>\u003c/p>\u003cp>我来解释一下这个自测题。题目是测试大家的社交力，在这里，我把社交力简化处理成共情力、沟通力、表达力的结合。\u003c/p>\u003cp>所以，总分在5-13分的小伙伴，你今天真是来着了，学完今天的拆页，你会get一个新方法，社交力也会大大提升。总分在14-22之间的伙伴，你的社交力非常棒呢，今天的拆页学习也会让你持续精进，助力你成为社交达人。有没有总分在23-30之间的呢？你在生活中一定像太阳一样温暖着所有人，我也要和你做朋友，今天的课程对于你来说就是锦上添花，可以帮助你梳理自己太阳的行为背后的发心，使你未来在社交中更加游刃有余。\u003c/p>\u003cp>接下来，请大家带着自己的测试结果，进入我们今天的拆书核心内容。\u003c/p>","ratings_count":1,"texts":[{"id":19947,"quote":"\u003cp>今天的拆页来自于《故事力》PDF版第82页，也就是第六章的第一页。我来为大家朗读一下。\u003c/p>\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>去年三八节前的某一天，我早上起来送儿子上学。有孩子的人都知道，孩子出门特别磨蹭，我等得着急就先去地库取车了，准备从车库绕出来，绕到楼下正好把儿子接上。等我开到小区门口要决定左转还是右转的时候，我想我这是要去哪儿呢？对，是去送儿子，我再一回头，咦？儿子呢？原来我根本就没接上他而是径直开走，准备去上班了。我赶紧掉头回去，在楼下接上一脸蒙的儿子，内疚地跟他道歉说：“哎呀，刚才妈妈脑子里一直在想工作，把你给忘了，不好意思啊！”其实更不好意思的是，这已经不是我第一次把儿子忘了！\u003c/p>\u003cp>到了公司，我就把这段糗事发在了朋友圈，结果一下子收到了80多条回复，不是点赞，是回复哦。你们猜猜回复的大都是什么样的人？对！是妈妈，是职场妈妈。很多人留言说自己也干过类似的事情。有个朋友说，有一次她开车送女儿上学，结果把车径直开到公司，她女儿问：“妈妈，这是哪儿啊？”还有很多女性，不一定是妈妈，也给我留言说，当个职场妈妈真不容易啊！\u003c/p>","explains":"\u003cp>\u003cstrong>【I拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页讲了一个案例。作者我，讲了自己本该接儿子却把儿子忘记的事情，收获了朋友圈同是职场妈妈们的热烈回应。\u003c/p>\u003cp>\u003cstrong>【和学习者简短互动】\u003c/strong>\u003c/p>\u003cp>我自己也是一个职场妈妈，看到这个故事的时候，我笑了。我想要是我有高琳老师的微信，也一定会在她这条动态下面发个评论。\u003c/p>\u003cp>在座的伙伴们，你们听了这个故事，请想一想，为什么这条动态能收获80多条回复？\u003c/p>\u003cp>在座有好几位女生，我想问问有没有同样是职场妈妈的？有的话请开麦回应一下，或者在聊天区扣1。\u003c/p>\u003cp>嗯。我看到好几位伙伴都回应了1哈，都是职场妈妈。谢谢大家回应。\u003c/p>\u003cp>我还想问问，你有没有过高琳老师类似的经历呢？有的话，看来高琳老师的故事也触发了你的回忆呢；没有的伙伴，你一定是一位高能妈妈，工作上和家庭里都能独当一面，太棒了！\u003c/p>\u003cp>回到我们的拆页，高琳老师的这条动态能收到这么多的评论，还能触发我们的伙伴记起了自己的经历，就是因为这个看似简单日常的故事唤起了职场妈妈、同为女性的群体的共鸣。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>再看我们今天的学习主题。很多人以为社交力强就是口若悬河、擅长表达的人才具备的，为了提升自己的社交力，要么是强迫自己多表达，见谁都能唠半小时；要么是奔走于各种场合，致力于广交天下好友。这样做的结果就是，看似朋友遍天下，实际上都是低质量社交，深度不够。\u003c/p>\u003cp>也就是说，我们真正需要的是有效社交、高质量社交，简单来说，当你需要帮助时，你知道找哪位好友帮忙，而且TA一定会帮你；当你情绪低落，你知道找谁倾诉，TA一定会给你全然的倾听，那你们之间一定是有效社交。\u003c/p>\u003cp>那怎么做才能提升社交力，让自己拥有有效的、高质量的社交圈呢？\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>结合拆页和我们的学习目标，我拆解出了共鸣激发法：\u003c/p>\u003cp>（1）共经历。讲述一个与对方经历类似的事件。用共同经历激发对方共鸣。\u003c/p>\u003cp>（2）共感受。讲述你对于某事的感受，而且是对方也可能会有的感受。用共同感受激发对方共鸣。\u003c/p>\u003cp>（3）共信念。讲述你的故事，传递鲜明的信念和观点，同样，这也是对方认同的价值观。用共同信念激发对方共鸣。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>大家从共鸣激发法中一定发现了，每一条都要求你讲出来的内容是和对方有一致性的，这就说明，你要对你的社交目标方有一定的了解，在原先的较浅层次了解的基础上，通过此次对话，再加深一层，逐渐形成深度连接。\u003c/p>\u003cp>所以，在表达和展示自己的个性、观点、需求并需要获得对方回应的时候，你需要先对社交目标方具备较浅层次了解，然后运用共鸣激发法去和对方对话、沟通。\u003c/p>\u003cp>当你完全不了解对方时，或者当你并不需要获得对方回应的时候，这个方法就不适用了。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>接下来，我举一个我自己的例子。\u003c/p>\u003cp>我在诺言社区（一个线上社群），阅读了一位诺友的动态，她组建了一个亲子阅读的读书会。我有孩子，我也和孩子每天保持亲子阅读的习惯，还给孩子和她的几个小朋友讲绘本，我想知道她是组建起来这个读书会的，既能认识更多的优秀妈妈，又能让孩子和小伙伴一起读书、讨论。\u003c/p>\u003cp>为了了解她，我阅读了她的更多关于读书会的分享和读书会的记录文。\u003c/p>\u003cp>然后，有一天，我给她发了下面这条信息：\u003c/p>\u003cp>“荷荷，你好，我是美君。从上个月起，我每周给我的孩子和几个小朋友讲一次绘本，通过促进孩子们问问题和让孩子们回答问题的过程中，我成了收获最大的人（共经历）。孩子们对于书中主人公情绪的感知、细节的把握都特别准，看到伤心的地方，连最好动的孩子都安安静静地沉浸其中了，让我看了特别感动，我也更能理解孩子了（共感受）。看到孩子们那么热爱阅读，可是，我又实在是精力不够，想像你们的四季亲子悦读一样组建一个亲子读书会，带动更多的家长参与进来，一起共建（共信念）。请问你是怎么做到的呢？”\u003c/p>\u003cp>很快，荷荷就回复我了，表示她很开心看到我的信息，还约我的时间。最后，我们通过电话进行了联系。\u003c/p>\u003cp>从这个案例中，大家可以看到，我发出的这条信息里，包含了我的经历，我的感受，我的信念，这些也都是能唤起荷荷共鸣的经历、感受和信念，所以她能愉快地回应我，给我提供帮助，也就成了顺理成章的事情。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A学习者拆为己用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3现场演练】场景设计、拆书家提问设计\u003c/strong>\u003c/p>\u003cp>现在到大家学以致用的环节啦。请你看以下场景。\u003c/p>\u003cp>你，大龄未婚男青年小帅，得知一位相亲对象小美很优秀，初步判断，对方是你喜欢的类型，经打听，知道女生离家远，自己独自在外工作，很不容易，但是自己独立自强，工作能力强，前段时间刚得到了提拔。\u003c/p>\u003cp>初次见面，你打算用自己同样的离家求学、工作的经历展开话题。\u003c/p>\u003cp>你会怎么说呢？\u003c/p>\u003cp>现在我给大家随机分组，两人一组，一个人扮演男生小帅，一个人扮演女生小美，进行现场模拟演练。男生该怎么说，会获得女生怎样的回应呢？\u003c/p>\u003cp>模拟演练时间4分钟，时间到，我结束分组，邀请一组小伙伴来现场演练。\u003c/p>\u003cp>现在我结束共享，把这个场景和共鸣激发法的内容发到聊天区，大家可以看到。\u003c/p>\u003cp>\u003cstrong>【A3现场演练】学习者案例\u003c/strong>\u003c/p>\u003cp>薛燕扮演小帅，Anna扮演小美。\u003c/p>\u003cp>小帅：小美，你好。\u003c/p>\u003cp>小美：你好。\u003c/p>\u003cp>小帅：听说你是外地人，在这边工作。\u003c/p>\u003cp>小美：对的。\u003c/p>\u003cp>小帅：我家离这儿也挺远的。你是自己在这里，还是有家人陪着呢？\u003c/p>\u003cp>小美：我自己在这边工作。\u003c/p>\u003cp>小帅：挺不容易吧？\u003c/p>\u003cp>小美：是的。挺不容易。\u003c/p>\u003cp>小帅：我自己在这里工作也有两年多的时间了。（共经历）一个人在这里，确实挺孤单的。（共感受）\u003c/p>\u003cp>小美：是的，没有朋友。\u003c/p>\u003cp>小帅：你为什么要一个人在这边工作呢？\u003c/p>\u003cp>小美：因为这边的环境好，机会更多，对我个人发展比较好。\u003c/p>\u003cp>小帅：女孩子，回到父母身边多好呀。\u003c/p>\u003cp>小美：是的，在父母身边好，但是我更想趁年轻在外面多闯一闯。\u003c/p>\u003cp>小帅：所以作为我们年轻人，都想在外面闯出一片天地，不依靠家里人。（共信念）\u003c/p>\u003cp>小美：是的，因为父母早晚有一天会离开我们。年龄大了以后，工作上也没有现在这么好的机会。（获得回应）\u003c/p>\u003cp>小帅：我们两个人的经历很相似啊，以后可以多交流啊。\u003c/p>\u003cp>两位小伙伴对角色的特征把握很好，对话很流畅，进展很顺利。尤其是扮演男青年的薛燕，很好地掌握和运用了共鸣激发法，从经历、感受出发，获取对方的积极回应，通过提问题的方式使对方讲出明确的信念，然后讲出自己的信念，再次获得对方的积极回应。\u003c/p>\u003cp>\u003cstrong>【A2】布置任务\u003c/strong>\u003c/p>\u003cp>好，我们今天的拆书课接近尾声了，我给大家布置一个课后任务。\u003c/p>\u003cp>请你思考，你的周围有没有你想要与之深度连接的伙伴，或许是你们单位新来的同事，或许是你的一位邻居，或许是某位拆书家，等等。在未来一周，请你主动联系一次这位伙伴，运用共鸣激发法，分享你的经历、感受、信念，看看能获得怎样的回应吧。\u003c/p>\u003cp>完成任务的小伙伴，请把你的作业发给我，我会针对你的实践做出反馈。我非常期待你的作业！\u003c/p>\u003cp>\u003cstrong>学员作业反馈\u003c/strong>\u003c/p>\u003cp>小王的作业：\u003c/p>\u003cp>我最近在上一个学习营的课程，要求学员找自己想要突破的一个卡点，我确定的卡点是复盘能力。但是我在网上搜到的方法五花八门，想尽快筛选出适合自己的方法，也想找一位这方面的专家给自己直接的反馈，我想到了一位拆书家宋老师，她讲过关于复盘的课程，自己也一直在给自己的工作生活做复盘。所以，我联系了宋老师。\u003c/p>\u003cp>“宋老师，您好，我最近想要突破复盘这个卡点，以前没有养成复盘的习惯，要么是事情结束后很久才复盘，复盘得不够全面和系统，要么是没有好的方法，把复盘做成了总结，对下次同类型工作没有借鉴和指导意义。（共经历）我关注您的朋友圈，看到您一直在做复盘，工作和生活都井井有条，所以，我想，要是我也能拥有这样的复盘力，做事的时候一定会更条理更清晰，那样的话，内耗和焦虑就会减少很多啊（共感受），而且，当坚持做复盘并且形成习惯后，工作生活一定更加充满能量。（共信念）\u003c/p>\u003cp>您能一直做复盘，是从复盘中获得了精进的目标和动力吗？您能分享一些您做复盘的心得和感悟吗？”\u003c/p>\u003cp>宋老师很愉快地回应我，“的确是，你的经历我也都经历过，正是因为不喜欢那种原地踏步的感觉，我才把复盘作为我每天必做的一件事，现在，我做起事来也的确更轻松自如了。接下来，我们打个电话吧，我可以分享一些我的复盘方法。”\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>讲述你的故事，结识更多朋友。\u003c/p>\u003cp>激发共鸣，熟练运用“共经历、共感受、共信念”，让你和TA的连接更紧密，让你拥有优秀的社交力。\u003c/p>\u003cp>感谢大家来参加我3-2的过级，我们下次再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1684748435000,"updated_at":1684982719000,"ria":true},{"id":15803,"topic":"2-3@英雄之旅＆2-4@神奇的PDCA循环法@无锡太湖分舵第236期","learn_goal":"","remark":"暂无","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"彼岸2022","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>【发拆页，分小组】\u003c/p>\u003cp>大家好，我叫孙宁，本次是TF2-3拆书过级，本次选择的书籍是《故事力 用故事决胜人生关键时刻》，所选拆页主要讲解“英雄之旅”的故事模型。开始之前，我先给大家分个组。\u003c/p>\u003cp>【用FAB法介绍图书，1-2分钟】\u003c/p>\u003cp>【F特点】\u003c/p>\u003cp>《故事力 用故事决胜人生关键时刻》，作者是高琳和林宏博两位作者，他们俩是“有意思教练”的创始人和CEO，两位都是英国工商管理博士，同时也是清华MBA、北大MBA颇受欢迎的客座讲师。\u003c/p>\u003cp>这本书里面有大量的真实案例，可以帮助大家建立一套属于自己的专业、实用、有趣的故事力思维训练方法。\u003c/p>\u003cp>【优势】\u003c/p>\u003cp>《故事力》在喜马拉雅APP上，长期霸榜故事沟通类课程TOP3，可见他的受欢迎程度。\u003c/p>\u003cp>【好处】\u003c/p>\u003cp>故事力是用故事思维去看待世界，掌握故事力，你就可以快速提升情商、沟通能力以及领导力。\u003c/p>\u003cp>今天我们学习的片段称之为“英雄之旅”的故事模型，可以手把手教会你用故事讲出你的影响力，让你在职场晋升、个人品牌打造的关键时刻，帮你脱颖而出。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp> 通过今天的拆书学习，大家能够套用“英雄之旅”的故事模型分享一些成长、转型等克服困难的故事，鼓励和帮助他人树立战胜困难的信心。\u003c/p>","ratings_count":1,"texts":[{"id":19890,"quote":"\u003cp>《故事力》英雄之旅：80%好莱坞影片都会用到的故事模型 P147-148\u003c/p>\u003cp>我在“有意思教练”公众号曾经讲过我们家“阿姨”如何蜕变的真实故事。她刚来我家的时候，是一个只有初中文凭，16岁的叫“小二”的东北姑娘，后来她在我家做了7年保姆，不但耳濡目染学会了半吊子的英语，还拿到了北师大幼儿教育的函授文凭，最终成功申请到去美国做互惠生的机会，现在“小二”已经在美国结了婚，买了房，拿了绿卡。\u003c/p>\u003cp>为什么个人转变的故事这么受欢迎呢？就好像灰姑娘这个老掉牙的故事，都听了千百遍了，但是迪士尼在2015年把它重新拍成电影的时候还是收获了不俗的票房。因为人们对白手起家，乌鸦变凤凰这样的故事有着一种说不出来的认同和向往。所以，一个蜕变的故事如果讲好了，会非常深入人心，并且能够表达出意味深长的道理。\u003c/p>\u003cp>其实，哪有什么华丽转身？每一次转身都无比艰难，活生生就是追梦中年人的血泪史。经历过这种蜕变式成长的人最能理解那种让你掉好几层皮的疼痛过程，最能够把这个过程讲好的故事模型非“英雄之旅”莫属。\u003c/p>\u003cp>“英雄之旅”这个概念来自美国著名神话学家约瑟夫·坎贝尔。他发现人类历史上，无论任何文化，神话也好，童话也好，似乎都建立在“英雄之旅”这一基本构造之上。这个构造基于一个故事的核心——所有的故事最终都是为了让主人公找回原来的平衡或者进入一个新的平衡。\u003c/p>\u003cp>\u003cstrong>具体来讲就是：一个人本来在自己平凡的世界里活得好好的，但是后来有个触发事件打破了他的平衡，于是他不得已告别过去的生活，开始进入一个新的世界，然而在这个新的世界里，他面临了新的挑战，结识了新的盟友，找到了新的导师，最终经过种种磨难，他克服了终极考验，实现了转变，并且进入一个新的平衡。\u003c/strong>\u003c/p>\u003cp>“英雄之旅”是好莱坞电影人必须了解的故事模型，可以说，80%的好莱坞电影都是按照“英雄之旅”这个框架搭建的。你也许会说好莱坞大片跟我有什么关系？莎士比亚说过：“人生就是一场多幕剧。”照这样，其实我们每个人都是自己生活的编剧，无论对于职场还是人生，我们的成长和转变过程也是我们自己的英雄之旅。\u003c/p>","explains":"\u003cp>【I引导拆解】\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>本拆页主要讲解了一个“英雄之旅”的故事模型。\u003c/p>\u003cp>英雄之旅不是新发明，它只是对事物的总结。神话学研究者约瑟夫坎贝尔，历尽多年搜寻阅读了全球各地的神话与宗教故事，将这些故事中的共通的奥秘提炼成“英雄之旅”的模型，揭示了英雄成长必经之路。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>人生也是一场英雄之旅，有低谷，也会有高光时刻，我们每一个人都是自己故事里的英雄。一个英雄蜕变的故事如果讲好了，无论是树立个人品牌、产品品牌，都会深入人心。\u003c/p>\u003cp>套用“英雄之旅”来讲故事，可以充分展示故事主人公由弱变强、从“失意和低落”到“腾飞和成功”，由乌鸦变凤凰等等经受坎坷与磨练的九九八十一难。让我们感受到主人公走出困境的心路历程以及情绪上的改变，让听故事的人更容易产生共鸣，可以赢得更多欣赏和信任。这比干巴巴的吹嘘自己要吸引人的多。\u003c/p>\u003cp>【HOW】\u003c/p>\u003ch3>那么究竟该怎么运用“英雄之旅”的故事模型来讲好我们自己的成长、转型、变强的故事来鼓励他人、树立战胜困难的信心呢？ \u003c/h3>\u003ch3> \u003cstrong>上一个月，有一条很火的新闻，新东方创始人俞敏洪豪气出手，给员工分红7.75亿人民币来激励员工。\u003c/strong> \u003c/h3>\u003cp> 接下来，我将为套用“英雄之旅”的故事模型，给大家讲讲出生于江阴的俞敏洪的英雄之旅。\u003c/p>\u003cp> \u003cstrong>第一、首先在平凡的世界。\u003c/strong>1980年俞敏洪历经三次高考后，顺利考入北京大学，毕业后留校任教，可谓是铁饭碗一辈子。\u003c/p>\u003cp>\u003cstrong>第二、发生触发事件，打破旧有平衡。\u003c/strong>明明可以依靠着在北大教授的工作，过着平凡的生活。可是为了出国留校看看外面的世界，赚取留学学费，他打着北大的名义私自举办补习班，被北大给予了处分。也许是因为外部环境所迫，也许是心中冥冥之中的某种召唤。不久，俞敏洪从北大辞职，离开北大校园，随后创办北京新东方学校。\u003c/p>\u003cp>\u003cstrong>第三、进入新世界，历经磨难与考验。\u003c/strong>\u003c/p>\u003cp>1993年，在一间10平米透风漏雨的小平房里，俞敏洪创办了北京新东方学校。最初创业只有俞敏洪夫妻俩，破桌子，破椅子，破平房，像是江湖术士。俞敏洪说，最初成立新东方，只是为了使自己能够活下去，为了每天能多挣一点钱。作为一个男人，快到三十而立的年龄，连一本自己喜欢的书都买不起，连为老婆买条像样的裙子都做不到。\u003c/p>\u003cp>尽管困难重重，但拼死拼活干了一段时间后，俞敏洪的培训班渐渐有了起色。\u003c/p>\u003cp>\u003cstrong>第四、最终实现转变，进入新的平衡。\u003c/strong>\u003c/p>\u003cp>从绝望中寻找希望，人生终将辉煌。俞敏洪创办的新东方，最终于2006年迎来高光时刻，在美国\u003ca href=\"https://baike.baidu.com/item/%E7%BA%BD%E7%BA%A6%E8%AF%81%E5%88%B8%E4%BA%A4%E6%98%93%E6%89%80/271637?fromModule=lemma_inlink\">纽约证券交易所上市，是中国大陆第一家在美国上市的教育机构。\u003c/p>\u003cp>当今俞敏洪已经不仅仅是一个教书先生，2014年创办洪泰基金，宏泰基金秉承着“成人·达己”的价值观，帮助、投资更多的青年创业者，奉献社会。\u003c/p>\u003cp>2021年，由于“双减”的实施，新东方股价跌落70%、关停了一半的教学点、裁员近4万名员工，俞敏洪和他创办的新东方正在经历新一轮的英雄之旅。\u003c/p>\u003cp>所以，才有了最近比较火的东方甄选。\u003c/p>\u003cp>【WHERE】当然，现实生活中，在套用“英雄之旅”讲故事的时候，不一定要严格按照每一个阶段，也可以简化或者省略其中的某些阶段。\u003c/p>","interaction":"\u003cp>【A3环节，10-15分，给出一个预先设计好的案例场景，请大家在小组内演练，最后要求一组做当众表达或者角色扮演】\u003c/p>\u003cp> 刚刚我们简单学习了英雄之旅的故事模型，其实，并不是只有大英雄、大人物、大成就的人的经历的磨炼才是英雄之旅。\u003c/p>\u003cp>不经历风雨怎能见彩虹，不经一番寒彻骨,怎得梅花扑鼻香。\u003c/p>\u003cp>人生就是一场英雄之旅，会遇到低谷，也会有高光时刻，只要积极向上、克服困难，每一个人都是自己故事中的英雄。\u003c/p>\u003cp>懂得了这么多知识，依旧过不好这一生。学习贵在应用，在拆书帮里面我们强调拆为己用。\u003c/p>\u003cp>\u003cstrong>接下来，会让大家做一个情景演练，练习使用英雄之旅的模型，请大家先认真听一下演练的场景：\u003c/strong>\u003c/p>\u003cp>由于“双减”政策的影响，在K12校外培训机构工作的小王也受到影响，因机构转型失败，小王被裁员了。随后，小王漫无目的海投简历，收到的面试机会比较少，仅有的几次面试也没通过，小王最近情绪比较低落。\u003c/p>\u003cp>有一天小王打电话给好朋友小张，小王在电话里说起了最近的情况，小张准备安慰一下小王。\u003c/p>\u003cp>\u003cstrong>演练要求如下：\u003c/strong>\u003c/p>\u003cp>1.两两一组，进行角色扮演，一个人扮演小王，小王的剧情特点是：小王最近找工作不顺心，情绪低落；另外一个扮演剧情的主角小张，请主角小张套用“英雄之旅”模型，讲一个自己或者他人成功克服困难的故事，安慰一下对方，鼓励对方当前困难只是暂时的，相信他肯定能找到工作的。\u003c/p>\u003cp>2.演练时间为5分钟，注意一下，我们演练的重点放在英雄之旅的故事模型上，而不是解决当前的困难。\u003c/p>\u003cp>\u003cstrong>演练结束后，我会邀请一组小伙伴做一个分享。\u003c/strong>\u003c/p>\u003cp>如果伙伴们不知道怎么开头，在此给大家一个场景话术，仅供参考。\u003c/p>\u003cp>小王可以开个头：张哥下午好呀，哎，最近我遇到糟心事了，想给你打个电话说道说道。\u003c/p>\u003cp>现场实录：\u003cbr>朱同学（扮演角色小王）： 张哥我最近过得不是特别好，被裁员了，然后面试也没有做个offer，然后感觉现在比较迷茫。\u003c/p>\u003cp>洁儿（扮演张哥）：“我知道，最近你不打我电话我也准备联系你了。\u003c/p>\u003cp> 我知道最近双减政策校外培训机构都是面临着生存问题，好多人都面临这样的一个问题，我知道你现在也是不是太太舒服的对吧？”\u003c/p>\u003cp>朱同学：是的。\u003c/p>\u003cp>杰儿：“其实我特别想想看到你这个现状，我想到我一个朋友。就是在七八年前对，他是做销售的，那个时候他也毕业不久，然后一直也没有业绩。他去请人吃饭去送礼，各种花了很多钱，但是最后也没有能够把订单给他，过得非常的迷茫。”\u003c/p>\u003cp>朱同学：“那然后呢？”\u003c/p>\u003cp>杰儿：“真的就是像很多年轻人一样碌碌无为，过得很糟心，那事情的转折点是什么？一个他的一个师弟，比他小两届，毕业以后没多久，正好那次他们一起聚会，发现这小子两年不见，如今年薪大几十万，然后业务做得特别好，他俩就聊起来了。他怎么能够这么快的去逆袭的，然后他师弟就跟他去聊，就说其实我们每个人都是有很多优势的，你不管有太多优势，在一个行业里面你一定要找到你的引路人，你拿什么去打动别人？他自己很成功的，他也想去帮助别人去成功，你要找到这样的一个人，然后他师弟跟他分享。”\u003c/p>\u003cp>洁儿：“他跟我讲，虽然说师傅领进门，但是修行在个人，其实在这样的一个过程中，其实也真的经过了很多的磨难和挫折。\u003c/p>\u003cp>我印象最深的一点就是我这个姓季的朋友，他说他在这个酒桌上，因为应酬不下10次被送进医院。对，就有一些人他还能通过酒桌去做进入他们的圈子，但是也有一些人他不喝酒，有一些学校的领导不喝酒怎么办？他会曲线救国，去通过各种关系来知道他的爱好，人都有爱好，有弱点或者有特别在意的，比方说孩子什么的，通过各种方式去知道它的切入口，然后就搞定了两所学校。他到现在的客户都是学校，因为这样的项目会一直有需求一直做。”\u003c/p>\u003cp>洁儿：“现在他自己创业。现在他年个人年收入已经超过了1,000万，这应该是从平凡的世界到达了另外一个出发点，最后成实现了个人财富自由。”\u003c/p>\u003cp>结尾总结：\u003c/p>\u003cp>好，其实我为什么选择这个拆页呢，这个和我自己的经历有关，我是做技术的，然后转向做技术管理的。其实也没人带，现在从技术管理，我想斜杠做培训，结果遇到了采薇师父，还有猫老师。这个过程，而且在我带团队过程中，我发现只有你讲自己的真实的故事，这种由低谷到高光的故事，进行自我披露之后，别人才愿意信服你，所以说我就选了英雄之旅的模型，基本上这是我今天2-3的一个拆书的整个过程了。好，谢谢各位。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1684133330000,"updated_at":1684741482000,"ria":true},{"id":15799,"topic":"什么样的故事才会影响他人","learn_goal":"","remark":"在某个场合，如何才能让一个重要的人，对我产生好奇，并在对方心目中留下深刻的印象？！学习目标1：在跟随我完成上半场RIA拆书学习后，现场演练当别人不认识我时，如何运用引发好奇心法，引起对方兴趣，瞬间知道我的特点。\n学习目标2：在跟随我完成下半场RIA拆书学习后，现场演练当别人不了解我时，如何运用引发共鸣法，正确表达我的观点，让对方觉得我们有类似的价值观，有机会还可以深入沟通。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"大雪","city":"湖州市"},"club":{"name":"湖州吴越分舵","city":"湖州"},"prologue":"\u003cp>\u003cstrong>TF2-4《故事力》中2个拆页 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>总时长：50-60分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、【自我介绍】（2分钟）\u003c/strong>\u003cbr>大家好，我是拆书家晏雪，我有3个标签：全屋定制设计师、大客户管理者、养生达人。\u003cbr>为了方便接下来的讨论，正式拆书前先进行一个简单的分组。就以相邻的小伙伴组成2个小组吧。\u003cbr>上周六，我参加一个行业协会会议，在会场与一些行业人士聊得比较好、当时也互加了微信，但是回来之后我们谁也没有联系过谁。你们有没有遇到过类似的场景呢？有的话可以给我挥挥手！\u003cbr>哈，大家也有遇到啊，如果再次遇到，我们该如何处理呢？今天带来的《故事力》这本书，正好可以解决这个问题。\u003cbr>\u003cbr>\u003cstrong>二、【图书介绍】\u003c/strong>\u003cbr>【F】《故事力》本书作者高琳和林宏博，两位即有工商管理博士的理论基础，又有40多年世界500强管理和咨询实战经验。作者用故事思维去看待世界、与世界沟通的能力。\u003cbr>【A】与其它沟通类的书籍相比，本书凝聚了情商，沟通力，领导力、战略思维等综合能力，并总结出6个故事模型对应不同应用场景；让人学完就能模仿，学完技能就能落地；是一本致用类的沟通书籍。\u003cbr>【B】本书通过讲故事的模型，让你在不同应用场景，成为有特点、价值、影响力的人，成就一个平凡之中不平凡的自己；而本拆页让你掌握如何收获好感和认可。\u003cbr>\u003cstrong>（技能点：FAB法介绍图书）\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>三、【学习目标+逻辑关系】（2分钟）\u003c/strong>\u003cbr>今天课程仅一小时，我们就拿书中两个片段来解决：在某个场合，如何用故事模型才能影响一个重要的人，对我的介绍产生浓厚兴趣，后面再沟通时，就能获得他的初步认可呢？！做到这点，要分成2个目标。\u003cbr>学习目标1：在跟随我完成上半场RIA拆书学习后，现场演练\u003cstrong>当别人不认识我\u003c/strong>时，如何运用引发好奇心法，\u003cstrong>让对方了解我的特点/优势，并引发他的兴趣。\u003c/strong>\u003cbr>学习目标2：在跟随我完成下半场RIA拆书学习后，现场演练\u003cstrong>当别人不了解我\u003c/strong>时，如何运用引发共鸣法，\u003cstrong>表达我的价值观，获得别人的初步认可。\u003c/strong>\u003cbr>拆页1和拆页2，逻辑上是递进关系。\u003cbr>\u003cbr>\u003cstrong>R\u003c/strong>原文片段：\u003cbr>四、\u003cstrong>第一个拆页RIA\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>【学习目标1】\u003c/strong>在跟随我完成上半场RIA拆书学习后，现场演练\u003cstrong>当别人不认识我\u003c/strong>时，如何运用引发好奇心法，让对方了解我的特点/优势，并引发他的兴趣。\u003cbr>\u003cbr>\u003cstrong>【R】阅读原书拆页1（1分钟）\u003c/strong>\u003cbr>\u003cstrong>什么样的故事才会影响他人？\u003c/strong>\u003cbr>我先给大家讲一个真实的故事\u003cbr>曾经一位全职妈妈创业找融资的时候给著名的投资人徐小平发了一条短信。\u003cbr>第一句: 我是北大毕业的\u003cbr>第二句:现在在开淘宝店，淘宝店的销售额已经3 000万了。\u003cbr>第三句: 但是我陷入了迷茫，您是一位心灵导师，您能不能开导开导我?\u003cbr>结果，徐老师看到这条短信后3分钟就把电话打了过去。当天下午他们就约好见面，谈了4个小时后，徐小平就打算投资她了。这位全职妈妈就是电商平台蜜芽的创始人刘楠。经过五轮融资，现在这家公司已经有了100亿元的估值。所有这些都源于一个三句话的自我介绍，这个介绍就是一个典型的故事。\u003cbr>为什么这么说呢?\u003cbr>你看，如果她的这个短信是这么说的:“徐小平老师你好!我叫刘楠我从北大毕业，创业销售额达到3000万了，想要寻求融资，能见见您吗?”你觉得这么说还会有同样的效果吗? 估计徐小平老师看一下就删1o\u003cbr>只有“因为”+“所以就不算一个故事-因为我想融资(目标)，所以我想见你(结果)，这只能算是一个叙述。那什么是故事呢?在“因为”和所以”之间加一个“但是”，就变成了故事!这个“但是”就是故事所必备的转折、冲突、矛盾。无冲突，不故事，在这短短的三句话里，就有三个“冲突”\u003cbr>北大毕业生怎么开淘宝店了? 徐老师看完一定有点儿好奇，这就是第一个冲突。销售额已经3 000万了居然能做出这样的成绩? 想必看到这儿，徐小平老师一定更好奇了。紧接着“但是我陷入了迷茫”，都3000万了还迷茫? 这是第三个冲突。最后再将徐老师当作心灵导师，徐老师一听肯定心花怒放啊!\u003cbr>也许你没意识到，这三句话其实就是\u003cstrong>一个最简单的故事架构，叫作--因为，但是，所以。\u003c/strong>\u003cbr>\u003cstrong>*因为我有一个目标\u003c/strong>\u003cbr>\u003cstrong>*但是在追求目标的过程中遇到了障碍\u003c/strong>\u003cbr>\u003cstrong>*所以我做了什么/想要做什么去克服这个障碍\u003c/strong>\u003cbr>\u003cbr>\u003cstrong>I\u003c/strong>拆书家讲解引导：\u003cbr>【I】拆书家讲解引导（5分钟）\u003cbr>【拆书技能】：【I】环节。1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤，4）根据原书中案例脉络，给出了更贴近实际的例子。\u003cbr>\u003cbr>〖why〗\u003cu>如果在某个场合做自我推荐\u003c/u>，只简单表达\u003cstrong>我是谁/来自哪里/做什么的\u003c/strong>；这种平铺直叙的方式，让人搞不清我有什么特点/优势？！也让听的人没有兴趣听下去！难道是这个人真的没有特点吗？\u003cbr> 不是。一般人思维局限在要讲什么，没思考别人愿意听什么？有一些人在表达上天生胆怯，有些人不擅长临场发挥，还有些人本身缺乏逻辑性，缺少练习。 \u003cbr>\u003cbr>〖what〗原文片段，给了个简单的故事架构“因为，但是，所以”。让人知道我是有目标、有行动力，还懂得谦虚，并能共赢（分享）的人。这种推荐瞬间就会引发别人的兴趣。\u003cbr> \u003cbr>〖how〗【细化原文行动步骤】\u003cbr>为了让大家更容易理解片段的意思，我把原文片段作了步骤细化，引发好奇心4步法：\u003cbr>\u003cstrong>步骤1，明确目标！\u003c/strong>在沟通前，就要在内心深处想好：这次沟通的主要目标是什么？\u003cbr>\u003cstrong>步骤2，列举障碍！\u003c/strong>列举我在现状中遇到的各种障碍。\u003cbr>\u003cstrong>步骤3，罗列努力！\u003c/strong>罗列我为\u003cstrong>扫清障碍\u003c/strong>所作出的各种努力。\u003cbr>\u003cstrong>步骤4，寻求帮助！\u003c/strong>我想寻求什么样的帮助？\u003cbr> 原文中，北大毕业生3句话的故事，她就是用了这个故事框架。\u003cbr>她沟通前的目标是想融资；障碍是营业额在3000万时遇到了瓶颈无法突破，还有资金上的困难（生意做大，都缺钱）；她的努力是作为北大毕业生，有知识有头脑有团队，还把淘宝店的营业额做到3000万。想要寻求的帮助：通过融资把事业做大，生意上是双赢的思路。\u003cbr>看到这种盈利项目，徐小平老师是投资人眼睛都是发亮的，兴趣马上来了。\u003cbr>\u003cbr>\u003cbr>&lt;*拆书家自己的反例*&gt;\u003cbr>给大家举个我自己的例子。有一次参加聚会，在酒桌上介绍自己，喝了点小酒脑袋有点发晕，我害羞地说“我是晏雪，在南浔做全屋定制的。请大家多多指教！”然后酒足饭饱后，对面的女士问我，“美女，刚才说你是做什么的呀？”。听她说完，我的老脸一下子涨红了。\u003cstrong>这是多么失败的一次自我推荐呀。\u003c/strong>\u003cbr>&lt;*列举正例*&gt;\u003cbr>后来读了《故事力》这本书，又有一次遇到了另外一个场合：\u003cbr>出发前，心里想要认识1-2个意向客户（明确目标）。宴席上是这样自我推荐了：\u003cbr>我做了10年房地产广告，阴差阳错进入了木门生产行业。\u003cbr>从广告转型木门行业，完全不懂木门工艺、市场需求，也没有客户。（列举障碍）\u003cbr>后来从0开始陌拜，到把江浙沪市场最大牌的客户资源抓在手里，只用了2年。（罗列努力）\u003cbr>现在，面临着营销向技术转型，您行业知识丰富，能不能指导指导我?（寻求帮助）\u003cbr>在这段推荐中， 我运用了故事框架：明确目标，列举障碍，罗列努力，寻求帮助的引发好奇心4步法，引发了老板们的好奇，当时吴老板很感兴趣，主动要了我的电话。\u003cbr>\u003cbr>【预防异议】\u003cbr>是不是我只要用了这个故事模型，就能让别人对我产生浓厚的兴趣呢？那也未必，如果为了获得效果捏造一些优势，即使当时听的人对你很兴趣，一旦了解后发现表里不一，结果会更糟糕。\u003cbr>因为影响他人，不一定巧舌如簧，可能默默地付出、言行一致也会有人会看得到。\u003cbr>〖where〗\u003cbr>比如面试、聚会、向人请教、点头之交等不太熟悉的场合，想要想要重要的人对我感兴趣时，可以用这个故事模型； 如果是完全熟悉的人，这方法就不太适用了。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>A\u003c/strong>拆书家讲解引导：\u003cbr>\u003cstrong>【A1】激活经验（7分钟）\u003c/strong>\u003cbr>【拆书技能】：【A1】技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己过往的具体经验，且加工出如果以后遇到同等情况，可以如何做。\u003cbr>\u003cstrong>A1【显像提问法】\u003c/strong>\u003cbr>下面进入\u003cstrong>分享\u003c/strong>时间。请大家回忆下，有没有碰到这样的场景：去面试、见客户、聚会等场合，因为自我介绍让你紧迫的场景？（3分钟）\u003cbr>可以想想“过去在什么时间、什么地点、和谁？发生了什么事，导致了什么结果？”请大家先在组内\u003cstrong>分享\u003c/strong>3分钟，等会邀请一位小伙伴来分享。\u003cbr>\u003cstrong>学习者案例记录【A1】：（1分钟）\u003c/strong>\u003cbr>钱娟分享：这个尴尬的场景是：上个月我参加了一个演讲培训，当时的情景是我们好不容易和顶级的培训师围桌吃饭，他给了一个机会进行1分钟自我介绍。结果呢？我采取了自杀式的自我介绍，我就说“不行不行什么的，我不擅长这种1分钟的自我介绍，到现在还印象深刻，等自我否定后一分钟结束后，我的自我介绍还没开始。也没有和顶级培训师链接上。\u003cbr>\u003cstrong>回应与反馈：\u003c/strong>\u003cbr>非常好，谢谢钱娟小伙伴的分享-还没开始就被结束，这种场景听起来是比较尴尬的。\u003cbr>\u003cbr>\u003cstrong>A1+【显像提问法】\u003c/strong>\u003cbr>今天，学习了引发好奇心4步法，如果大家有机会穿越回当时的场景，你会怎么沟通呢？\u003cbr>请大家组内\u003cstrong>分享\u003c/strong>2分钟后，等会还是请一位位小伙伴来分享。\u003cstrong>（2分钟）\u003c/strong>\u003cbr>（旁白：引发好奇心4步法，明确目标，列举障碍，罗列努力，寻求帮助）\u003cbr>\u003cstrong>学习者案例记录【A1+】：\u003c/strong>\u003cbr>钱娟分享：如果让我重新回到当时的场景，用引发好奇心的方法，我会这样向别人介绍自己，在去之前先想好自己的目标是什么？我的目标是认识2个人建立链接，介绍时我可以这样说：“我叫钱娟，做学历考证7年；当时做这行业时，很多人不理解也不了解我们这个行业，业务很难开展；后来通过2年的努力，手头上掌握了2000个学生资源，现在我想把这些资源转化，您是这方面的专家，能不能指导我？用这种方法来介绍，可能当场就会引发他的兴趣。\u003cbr>\u003cbr>\u003cstrong>【拆书技能】：拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003c/strong>\u003cbr>\u003cstrong>回应与反馈：\u003c/strong>\u003cbr>谢谢钱娟的分享，这个案例中她已经运用了引发好奇心的故事模型，是一次非常成功的尝试，非常棒！\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>原文片段：\u003cbr>五、\u003cstrong>第二个拆页RIA\u003c/strong>\u003cbr>刚才在拆页1，掌握了运用引发好奇心的方法，让对方有了解我的兴趣，是不是就能影响这个重要的人呢？这，还远远不够，因为我们还需要赢得他的初步认可。\u003cbr>\u003cstrong>接下拆页2，即\u003c/strong>\u003cbr>\u003cstrong>【学习目标2】\u003c/strong>学习者在跟随我完成下半场RIA拆书学习后，现场演练\u003cstrong>当别人不了解我\u003c/strong>时，运用引发共鸣法，表达我的价值观，获得别人的初步认可。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>【R】阅读原书拆页2（2分钟）\u003c/strong>\u003cbr>\u003cstrong>用故事讲出你的价值观\u003c/strong>\u003cbr>我在之前公司的时候，有一次因为一个历史遗留问题，公司有可能被罚款几百万，但在公司看来这样的处罚是缺乏足够依据的。当时我被老板派去解决这个问题，看能不能不罚款或者少罚一些。那时候，我和团队几乎每周都要一大早坐上高铁去和当地相关部门沟通，交涉了很久，但问题都像皮球一样被踢来踢去，大家都很绝望。其中有一个下属就提出，要不然给经手的人点好处，把这事儿打点了得了。\u003cbr>我当时就对他说：“我理解你的心情，我也很烦，天天到处求人。但是老板曾经跟我说过这么一句话：‘如果明天报纸的头版头条登的就是你做的这件事，你觉得可以登吗？如果可以，你就去做，如果不可以就不要做。’ 所以，你好好想想，刚才你那建议能达到这样一个标准吗？”那个下属说“肯定不能”，我说：“那不就完了，咱继续想办法解决吧。”最后我们通过各种沟通，反复游说，找相关证据，总算是把问题完美解决了。\u003cbr>这件事情背后体现的是什么呢？既是我的价值观，也是公司的企业文化。这个故事看似没有提到“选择”这两个字，但是你能看出来背后的选择。\u003cbr>所以\u003cstrong>讲故事的最大作用之一就是证明\u003c/strong>。最好的证明，就是\u003cstrong>因为\u003c/strong>你觉得这个“价值观”重要，\u003cstrong>所以\u003c/strong>不管发生了什么困难，无论结果如何，\u003cstrong>你都会坚守\u003c/strong>这个价值观。说到价值观就一定会涉及选择。讲故事就是不仅要告诉别人你的\u003cstrong>选择是什么，还讲述了你选择的过程\u003c/strong>。在那个过程中，你的纠结，你的痛苦，你的努力，说明了你为什么做出那个选择，那个“为什么”就是你的价值观。而如果没有那些选择上的冲突，你就无法体现你的价值观。\u003cbr>\u003cbr>\u003cstrong>I\u003c/strong>拆书家讲解引导：\u003cbr>【I】拆书家讲解引导（9分钟）\u003cbr>【拆书技能】：【I】环节。1）强调不那么做的坏处，2）给出了学习者可能异议的预防性讲解，3）细化了原文行动建议的步骤，4）根据原书中案例脉络，给出了更贴近实际的例子。\u003cbr>\u003cbr>我看大多数小伙伴都读完了，没读完的也没有关系，下面听我拆解就好。\u003cbr>〖why〗相信大家都听过一句话：好看的皮囊千篇一律，有趣的灵魂万里挑一，大多数人希望自己能成为很有趣的人。但实际上向别人表达时，我们往往说了一堆自己都不知道的废话，让听的人一头雾水不知道我在讲什么，无法引发共鸣；甚至还让旁人误会到“听完你的故事，我感觉你有点固执”。\u003cbr> 这是因为每个人的成长背景各不相同，社会所处位置不同，观点也不同；而每个人的观点，都代表他背后的价值观。价值观没有对错，只有合不合拍；浅层次的交往是吃饭、送礼，深层次的交往就是引发共鸣。\u003cbr> \u003cbr>〖what〗原文片段，用了一个故事模型“因为……即使……我还是选择…… 阐述如何用故事模型向别人表达价值观，从而赢得对方认可。\u003cbr>\u003cbr>〖how〗\u003cbr>根据文章大意，为了让大家更好理解原文片段，我梳理出引发共鸣3步法，\u003cbr>\u003cstrong>步法1，因为…… \u003c/strong>（阐述我的价值观，这个对我很重要的价值观）。\u003cbr>\u003cstrong>步法2，即使…… \u003c/strong>（面临的什么困难/冲突，很难解决的问题）。\u003cbr>\u003cstrong>步法3，我还是选择……\u003c/strong> （做成了什么）。\u003cbr> 片段的故事就是套用的这个模型，那就是：因为诚信对我很重要，即使面临的问题难以解决，我还是选择了通过正当渠道沟通，而不是不择手段。让面试官认为他具有和企业一样“诚信”的价值观，从而对他个人表示认可。\u003cbr>\u003cbr>\u003cbr>【意译案例】\u003cbr> 这个片段，这让我想起拆页一认识的吴总，在和他合作前发生的一个矛盾，事情的背景是这样的：\u003cbr>当时，客户让我帮他介绍了一家石材厂。他们签约后客户临时增加了项目，石材厂报价要多补9500元，但客户认为谈好的一口价顶多补1000元。石材厂要挟客户不补钱就不安装，客户认为是我介绍的，不认那个数只认我这个人，他们双方拉扯不下。后来石材厂的人给我说，要么客户补的就不要做了，让别的厂给他做好了。\u003cbr>当时就对他说：“我理解你的心情，我也很烦，天天被客户骂介绍了一个什么厂，吃力不讨好。但是这个业务是南浔地板厂老板介绍过来的，如果客户把这事儿捅到介绍人那，你觉得我们在南浔还有口碑吗？石材厂的人说“肯定不行”。\u003cbr>出于做生意要诚信的角度，即使这个错误不是我造成的，我还是主动承担了8500元的损失，把问题完美解决了。因为我的诚信，得到了客户的认可，吴总在介绍人前美言：“晏雪还是蛮讲信誉的”。后来他家的全屋定制也如期给我做了。\u003cbr>&lt;根据原书中案例脉络，给出了更贴近实际的例子。&gt;\u003cbr>\u003cbr>【预防异议】\u003cbr>有人会说，如果要承担这么大的代价，我是做不到的。没有必要为了别人委曲求全，刻意讨好变成讨好型人格。拆页中也讲了，讲故事的最大作用之一就是证明你觉得这个“价值观”重要，这个价值观只针对你要搞定的对象或者想影响的人；当然你用了这个方法也未必能100%影响他人，只能增加别人愿意认可我的概率。\u003cbr>〖where〗\u003cbr>拆页中的方法，在公开课、当众演讲、竞选岗位、面试、新品推荐、客户提案、家校沟通、相亲等场合，想要通过引发共鸣、获得别人的好感或认可时，都可以用此故事模型。但是对很了解你或对你有偏见的人，不在这个范围内。\u003cbr>\u003cbr>\u003cstrong>A\u003c/strong>学习者拆为己用：【A3】促动参与（10-12分钟）\u003cbr>\u003cstrong>【拆书技能】：【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/strong>\u003cbr>\u003cbr> 接下来，我们进入现场演练环节，根据刚刚学习的引发共鸣3步法，模拟下面的场景进行角色扮演。\u003cbr>【场景设计：】\u003cstrong>（1分钟）\u003c/strong>\u003cbr>小王在一家公司工作快三年了，一直勤勤恳恳，每次都能把上级交代的事认真完成，但是较少接触老板，也没有特别的贡献，所以一直未能得到晋升。\u003cbr>今年，公司招聘一名总监助理，岗位中最重要的一点要求就是：做事要\u003cstrong>诚恳\u003c/strong>，能不折不扣地将总监分配或将分配的事落实下去。小王认为自己可以一试，准备向上老板推荐自己。\u003cbr>\u003cbr>【角色扮演】 \u003cstrong>（7分钟）\u003c/strong>\u003cbr>请2组小伙伴根据以上信息分别扮演小王和老板，并且将对话的关键词写在下面的表格中，给大家7分钟讨论时间，之后会邀请2个小伙伴来展示。\u003cbr>引发共鸣3步法，\u003cbr>\u003cstrong>步法1，因为…… \u003c/strong>（阐述我的价值观，这个对我很重要的价值观）。\u003cbr>\u003cstrong>步法2，即使…… \u003c/strong>（面临的什么困难/冲突，很难解决的问题）。\u003cbr>\u003cstrong>步法3，我还是选择……\u003c/strong> （做成了什么）。\u003cbr>\u003cbr>【学习者案例记录:】\u003cstrong>（2分钟）\u003c/strong>\u003cbr>小王（扮演者：小娜），老板（扮演者：悠悠） \u003cbr>\u003cstrong>小王：\u003c/strong>老板，我今天是来竞聘总监助理一职。\u003cbr>\u003cstrong>老板：\u003c/strong>你知道这个岗位最重要的要求是什么吗？\u003cbr>\u003cstrong>小王：\u003c/strong>我感觉这个岗位最重要的一点就是\u003cstrong>诚恳\u003c/strong>，我下面想向老板说下我在工作中的一个案例，来证明我适合做总监助理。\u003cbr> 去年，我们公司面临要被评估。当时我就觉得诚恳务实是公司比较看重的，需要整理一些材料。在整理这些材料时发现有错误而且时间也很紧，我手里只有几分材料但是公司牵扯到上百份材料，而且我这几份材料发现问题之后，本来我可以得过且过--不管它了直接交上去，即使对公司造成什么影响也不会对我个人造成什么影响，但是我还是觉得这样做对公司信誉是影响比较大的。所以我还是决定找我的上司，沟通了这件事，最后把其他同事共上百份材料集中到我这里，统一进行更正替换。最后我们公司有惊无险地通过了评估，我觉得在\u003cstrong>诚恳\u003c/strong>这方面我绝对地是可以保证的，所以我想竞聘总监助理，希望老板可以给我一个机会！\u003cbr>\u003cstrong>老板：\u003c/strong>不错噢，小王！你这种做法，我还是蛮认可的。\u003cbr> \u003cbr>【拆书技能】：拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003cbr>\u003cstrong>回应与反馈:\u003c/strong> \u003cbr>谢谢悠悠老师和小娜的精彩演出，她们运用了共鸣的故事模型，小娜扮演的小王精准地把诚恳这个价值观向老板阐述了。让老板听到这个案例，就知道小王是个诚恳的人，从而获得老板的初步认可。再次谢谢两位学习者！\u003cbr>\u003cbr>\u003cstrong>【A2\u003c/strong>】催化应用\u003cstrong>（共10-12分钟）\u003c/strong>\u003cbr>【拆书技能】：【A2】技能点指令清晰，至少一个【A2】环节提问中包括情境或场景，有学习者受启发联系到自己的具体应用场景。\u003cbr>\u003cstrong>A2【分步催化1\u003c/strong>——指向未来的显像提问法\u003cstrong>】（4分钟）\u003c/strong>\u003cbr>接下来，请大家想一想，\u003cbr>\u003cstrong>未来会不会碰到这样的场景：公众演讲发表演说，结果台下没人反应的尴尬情景？向客户推荐新品，讲了半天客户不知道你讲什么的尴尬画面？\u003c/strong>\u003cbr>想想“未来某个时间、某个地点、和谁？发生什么事，将会导致什么结果？”。\u003cbr>接下来，大家花3分钟时间，\u003cstrong>分享\u003c/strong>下未来可能遇到的场景！等会将请1位小伙伴上来分享：\u003cbr>\u003cbr>【学习者案例记录1:】\u003cstrong>（1分钟）\u003c/strong>\u003cbr> 悠悠分享：我是一名大学老师，\u003cstrong>未来一个星期\u003c/strong>，我可能会遇到在学校课堂上讲得热情洋溢，下面的学生无动于衷并且让我很无奈的一个情景！\u003cbr>\u003cstrong>回应与反馈:\u003c/strong> 谢谢悠悠老师分享，这点确实让人很无奈，也确实让人很苦恼。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>A2\u003c/strong>【\u003cstrong>分步催化2\u003c/strong>——学习者加工未来场景中的应用】\u003cstrong>（5分钟）\u003c/strong>\u003cbr>对应\u003cstrong>未来\u003c/strong>可能发生的场景，学习引发共鸣3步法后，我们现场演练一次！\u003cbr>OK，接下来每组花3分钟时间现场\u003cstrong>分享\u003c/strong>下，等会将请1位小伙伴上来分享：\u003cbr>引发共鸣3步法，\u003cbr>\u003cstrong>步法1，因为…… \u003c/strong>（阐述我的价值观，这个对我很重要的价值观）。\u003cbr>\u003cstrong>步法2，即使…… \u003c/strong>（面临的什么困难/冲突，很难解决的问题）。\u003cbr>\u003cstrong>步法3，我还是选择……\u003c/strong> （做成了什么）。\u003cbr>\u003cbr>【学习者案例记录2:】\u003cstrong>（1分钟）\u003c/strong>\u003cbr> 悠悠分享：\u003cstrong>对应刚才说过的那个未来场景，\u003c/strong>我发现学生对考研比较感兴趣，但很多学生都是跟风的，所以我想要向学生表达一个观点：明确考研后，需要全力以赴/非常专注地去准备；然后跟学生讲述我自己的一些经历。比如说我以前也想要考研，可寝室里一点氛围都没有，而且当时我拿到的复习资料也非常有限，但是我还是觉得要专心致志的做一件事情--不给自己留任何遗憾；后来我调好生物钟，每天学习10个小时以上，经过自己的不懈努力，最后成功上岸（考上研究生） 。学生当时听完之后，就频频地点头。\u003cbr>\u003cbr>【拆书技能】：拆书家至少有一次给出了关联到原文知识点的回应或反馈。\u003cbr>\u003cstrong>回应与反馈:\u003c/strong>\u003cbr>太棒了，悠悠老师分享的这个案例也是比较经典的。学生不愿意学时，抓住了学生想考研这件事，向学生输出做事要专心致志的价值观，并且列举了她当时考研时也面临了很多困难，但是她还是选择了专心致志的考研，最后考上了研究生的案例。引发学生共鸣，让他们对她的价值观表示认可。\u003cbr>谢谢悠悠老师的分享，说明她已经掌握了引发共鸣的故事模型。\u003cbr>\u003cbr>【回应2个拆页的关联】：\u003cbr>如何引发重要人的兴趣？拆页一，钱娟小伙伴用自己的亲身案例，用好奇心4步法，演练了如何通过自我介绍引发想要影响的重要人的浓厚兴趣。接着，如何让重要人初步认可？拆页二，悠悠小伙伴又运用了引发共鸣3步法，阐述了自己专心致志的价值观，获得大学学生的共鸣，从而赢得学生的初步认可。\u003cbr>\u003cbr>\u003cbr>\u003cstrong>结束语（1分钟）\u003c/strong>\u003cbr>【拆书技能】：结尾时给出了强有力的结语。\u003cbr> 今天我们这一个小时的课程，主要用《故事力》的思维模型解决了：在某个场合，如何才能影响一个重要的人，对我的介绍产生浓厚兴趣，后面再沟通时，就能获得他的初步认可呢？！\u003cbr>为了解决这个问题，我们分了两个拆页。\u003cbr>第一个拆页，通过现场演练\u003cstrong>当别人不认识我\u003c/strong>时，运用了引发好奇心的方法，\u003cstrong>让对方了解我的特点/优势，并引发他的兴趣。\u003c/strong>引发好奇心4步法分别是明确目标，列举障碍，罗列努力，寻求帮助。\u003cbr>第二个拆页，通过现场演练\u003cstrong>当别人不了解我\u003c/strong>时，运用了引发共鸣的方法，输出\u003cstrong>我的价值观，获得别人的初步认可。\u003c/strong>\u003cbr>OK，掌握了这两个模式模型，对“如何影响一个重要的人？”的问题，解决起来就游刃有余了。在未来的一个月，希望大家能多次运用到这2种故事模型，开展美好的人际关系。\u003cbr>感谢大家的参与，本次拆书到此结束！谢谢大家！\u003cbr>\u003cbr>晏雪于南浔\u003cbr>2023年5月13日\u003c/p>","ratings_count":2,"texts":[{"id":19885,"quote":"\u003cp>已完成。\u003c/p>","explains":"\u003cp>已完成。\u003c/p>","interaction":"\u003cp>已完成。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684115699000,"updated_at":1684988138000,"ria":true},{"id":15750,"topic":"用故事述说人生，用故事影响他人","learn_goal":"","remark":"你还在为自我介绍发愁吗？\n你还在为汇报工作打怵吗？\n你想和孩子平等对话吗？\n你想让朋友更了解你吗？\n\n做生活的有心人，做故事的创造者。\n用故事力养成四步法，讲出你的故事，影响更多人。","level":"TF3-1","duration":25,"status":29,"type":0,"chaishujia":{"username":"美君grace","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是美君，欢迎大家来参加我TF3-1的拆书过级。今天我的拆书主题是“\u003cstrong>用故事述说人生，用故事影响他人\u003c/strong>”，时长大约25分钟。\u003c/p>\u003cp>我先用三个标签做个自我介绍：拆书家、终身学习者、成长型思维践行者。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>结合今天的拆书内容，没有需要分组讨论或者演练的环节，所以不专门设置分组。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】\u003c/strong>\u003c/p>\u003cp>今天我的拆书主题是“\u003cstrong>用故事述说人生，用故事影响他人\u003c/strong>”，拆页片段来自高琳的《故事力》一书。在拆解前，大家先来看看这样一个场景。\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>我的一个好朋友生二胎后饱受体重增长几十斤的困扰，不自信，不敢见熟人，通过半年的减脂后成功瘦回原来的体型，她想建议另一位同样长胖且打算通过节食减肥的朋友采取她用过的方法。\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>请大家试想一下，我的这位朋友应该怎么分享才能成功安利自己的方法呢？如果是你，你会怎么说呢？直接告诉朋友，节食不利于健康，我这方法非常管用，你看我，半年就成功瘦回来了，你应该这样做，不应该那样做……如果这样说，听的人会是什么感受呢？如果这个方法不好，那什么方法才是好方法呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>如果我朋友直接讲节食的坏处和自己方法的好处，估计还没说完，对方就有拉黑她的想法了。可见，讲的人好像情绪高涨，在分享对对方有用的内容，但是听的人却不领情，甚至有损双方关系。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>我今天带来的《故事力》就是用讲故事的方法取代滔滔不绝的大道理、反反复复的碎碎念、直接否定对方、强制安利，通过有策略地讲述你的人生故事，吸引别人注意力并使之对你这个人、对你想表达的内容产生好奇、共鸣，实现事半功倍的说服效果。\u003c/p>\u003cp>具体怎么做呢？我们继续。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在需要展示自己并期望获取认同的时候，运用故事力养成四步法，从过往的记忆库中搜索一个自己的人生故事，提取故事的分享点，设想一个合适的场景，并按照一定的逻辑框架把故事分享给场景中的对话者。\u003c/p>","ratings_count":1,"texts":[{"id":19833,"quote":"\u003cp>接下来，我用两分钟的时间为大家朗读今天的拆页。\u003c/p>\u003cp> 拆页来自《故事力》PDF版第15-16页\u003c/p>\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>畅销书作家丹尼尔·平克在他的《全新思维》中提出：“未来属于那些拥有与众不同思维的人，唯有拥有右脑时代的6大全新思维能力，才能决胜于未来。”这6大全新思维能力中很重要的一项就是\u003cstrong>“故事力”——用故事思维讲出你的故事并由此产生影响力。\u003c/strong>\u003c/p>\u003cp>面试的时候讲好故事，会让面试官认为你就是他们想要找的那个人；销售的时候讲好故事，客户就能心甘情愿地埋单；工作汇报的时候讲好故事，能让领导立刻认可你；相亲约会的时候讲好故事，就能让对方觉得你是那个三观一致、趣味相投的Mr. or Mrs. Right。如果你是领导或者创业者，讲故事更是你的必修课，因为故事是成本最低的说服方式。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页借用一本畅销书引出了故事力的概念，“用故事思维讲出你的故事并由此产生影响力”。\u003c/p>\u003cp>这个概念中有三个要点。\u003c/p>\u003cp>一个是你的故事，不是别人的故事；\u003c/p>\u003cp>第二是影响力，你讲出你的故事后要对听的人产生影响，比如，好奇、认同等等，这就意味着，要在什么场合讲什么故事和怎么讲故事，所以要在你的故事提取可以用来影响他人的点；\u003c/p>\u003cp>第三是故事思维，也就是说，讲故事，不能平铺直叙，像流水账一样浮于表面，要提取真实事件和经历中的“故事点”，然后用一定的逻辑框架讲出来。\u003c/p>\u003cp>综合这三个要点，故事力就演变成，用某种逻辑框架、详略得当地讲出你的故事，进而使听者产生好奇、认同等感受和行为。\u003c/p>\u003cp>下面，我们一起通过案例来进一步拆解这个概念。\u003c/p>\u003cp>我给大家展示几个案例，大家在我讲完案例后来说一说这些案例中，主人公的分享内容是否符合故事力的定义，符合，在聊天区扣1，不符合扣2。\u003c/p>\u003cp>\u003cstrong>【强化概念讲解——概念与案例折返】（强化概念讲解二选一）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（案例1）\u003c/strong>\u003c/p>\u003cp>五岁孩子放学回家，妈妈发现孩子书包里有一个小玩具，孩子说是小朋友送的，反复追问后，孩子才说是自己太喜欢了，装进自己书包里的。\u003c/p>\u003cp>妈妈觉得拿别人东西和说谎都是不好的行为，就给孩子讲了两个故事，一个是小兔阿布和布娃娃的故事，一个是狼来了的故事。\u003c/p>\u003cp>孩子听了以后，表示以后再也不未经允许乱拿别人东西了，也不会再说谎话了。\u003c/p>\u003cp>大家来看看，觉得妈妈讲的故事符合故事力概念的小伙伴扣1，不符合的扣2。\u003c/p>\u003cp>\u003cstrong>（概念折返1）\u003c/strong>\u003c/p>\u003cp>大家都扣了2。是的，大家回答正确。\u003c/p>\u003cp>哪位小伙伴能说一说问题出在哪里吗？（小伙伴回答：这位妈妈讲的不是自己的故事。）\u003c/p>\u003cp>非常好。故事力的第一个概念要点就说了，要讲自己的故事。\u003c/p>\u003cp>我们再看下一个案例。\u003c/p>\u003cp>\u003cstrong>（案例2）\u003c/strong>\u003c/p>\u003cp>面试官问小王：讲讲你的一个缺点吧，举个例子说明。\u003c/p>\u003cp>小王答：我做事很严谨，不放过每一个细节，只是，有时候过于追求细节会降低我的工作效率，但是，我已经意识到了这一点，最近半年采用了一系列方法调整我的工作节奏，到目前还是很有效果的，尤其是上个月结束的一个大项目，我高质量高效率地完成了，公司领导非常满意。\u003c/p>\u003cp>大家认为小王的回答符合故事力概念的扣1，不符合扣2。\u003c/p>\u003cp>\u003cstrong>（概念折返2）\u003c/strong>\u003c/p>\u003cp>大家都扣了2。回答正确。\u003c/p>\u003cp>大家能说说小王的问题出在哪里吗？（小伙伴回答：小王没有讲故事。）\u003c/p>\u003cp>小王的回答没有对面试官产生影响力。小王讲的内容看起来是他的经历，但实际上，这是他经过实践后的反思和改进，以及粗略地介绍了一个所谓的大项目的完成情况。面试官要求举个例子，是很好的讲故事机会，很可惜，小王错过了。\u003c/p>\u003cp>我们再看一个案例。\u003c/p>\u003cp>\u003cstrong>（案例3）\u003c/strong>\u003c/p>\u003cp>张姐热爱旅游，每次旅游回来都会向李姐分享她的见闻和感受，并建议李姐下次和她一起去玩。\u003c/p>\u003cp>张姐说，这次我去了三亚，我原来以为三亚物价高，人又多，肯定玩得不好，去了才知道，特别好；我们七天有四天都在海边，海水真好，特别清澈，天气也特别好；我们还吃了很多水果，和咱们北方买的真不一样，特别好吃，都是自然熟的；那个海鲜，特别新鲜，我们去海鲜市场买了就做了吃，味道真是好；我打算过些天再去一趟，你不是也一直想去吗，咱们一块儿啊。\u003c/p>\u003cp>同样，大家认为张姐的说辞符合故事力概念的扣1，不符合扣2。\u003c/p>\u003cp>\u003cstrong>（概念折返3）\u003c/strong>\u003c/p>\u003cp>大家都扣了2，谢谢。\u003c/p>\u003cp>问题出在哪里呢？回归故事力第三个概念要点，要用故事思维讲故事。\u003c/p>\u003cp>张姐的故事讲得没有逻辑，一会儿说期望和现实，一会儿说海水，一会儿吃水果海鲜，很是混乱，我们可以想象李姐在听的时候是什么感受。\u003c/p>\u003cp>\u003cstrong>结合这三个典型案例，我们再来看看常见的三种情况。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>当我们表达的时候，为了说服听者，常常会出现三种情况。第一，拿别人的事情作为案例，“某某某做了什么，最后他获得了什么什么，所以你也应该怎样做，你就能获得什么”，这样的话给人一种套路感，而且我们都知道，做和获得之间并不存在单一的逻辑关系，说服力太低；第二，滔滔不绝大道理，很多家长甚至老师在和孩子/学生沟通的时候，喜欢讲道理，照本宣科，但是，道理谁都懂，却依然过不好每天的生活，光讲道理，浮于表面，无法走进人心；第三，讲自己的故事，却只讲“我曾经怎么怎么样，你看我现在多棒，所以你也应该怎么怎么样”，给说教披上了虚假的故事外衣。\u003c/p>\u003cp>这三种情况下，听的人碍于礼貌，硬着头皮听，其实，恨不得立即消失，更别谈对其产生影响力了。\u003c/p>\u003cp>所以，我们应该采取正确的方法，养成和提升自己的故事力，让讲出来的话更具影响力和说服力。\u003c/p>\u003cp>我们系统地整合一下故事力概念要点、三个案例和三种常见情况：\u003c/p>\u003cp>要点一，讲自己的故事。如果案例一中妈妈能讲一个自己小时候的类似故事，能起到共情孩子的作用，帮助孩子树立正确的价值观。为了有故事可讲，你需要建立自己的故事库。\u003c/p>\u003cp>要点二，讲故事并产生影响力，如果案例二中小王能讲出他怎样高质量完成大项目的故事，面试官也会对他做出另一番评价。看来，讲故事不是为了讲，而是为了“影响”。\u003c/p>\u003cp>要点三，用故事思维讲故事。如果案例三中张姐能讲出其中一个点，比如只讲吃了什么，口味怎么样，价格怎么样，购买的方便程度怎么样，而且没有缺斤短两，对食物有高要求的李姐听了一定会很心动。也就是说，讲故事要有逻辑和框架。\u003c/p>\u003cp>\u003cstrong>所以，怎么做才能讲出充满故事力的内容呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>我在故事力概念的基础上，拆解出故事力养成四步法。\u003c/p>\u003cp>\u003cstrong>1. 记录我的故事。\u003c/strong>坚信“我”是有故事的人，首先要做生活的有心人，养成记录故事的好习惯，搭建起属于你的故事素材库。注意：要记录细节，时间、地点、人、事、起因、经过、结果以及你的反思。\u003c/p>\u003cp>\u003cstrong>2. 标记故事类型。\u003c/strong>记录故事的过程中，给故事划分类型，可以是“个人成长”、“职场执行力”、“职场领导力”、“时间管理”等等，有利于以后按图索骥，迅速找到需要分享的故事案例。一个故事可以有多个标签，也就是说，可以从不同角度提取故事的分享点。\u003c/p>\u003cp>\u003cstrong>3. 辨析分享场合。\u003c/strong>不同场合、不同对象，要讲不同的故事。注意：要勤于翻阅故事库，建立起标签与故事以及适用场合的关联，通过下一步，不断强化其中的关联。\u003c/p>\u003cp>\u003cstrong>4. 讲出我的故事。\u003c/strong>故事有、标签有、场合有，是时候讲出你的故事了。给故事构建一个逻辑框架，可以是黄金三点，可以是首先其次最后，可以是因为-但是-所以，等等。最开始，你可能不擅长讲出来，影响力，即说服力比较低，但是，讲出你的故事，就是最好的让大家认识你、记住你的途径。多多练习，讲故事的逻辑能力及其影响力也会得到提升。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>当你需要展示自己的独特一面，让别人对你产生好奇时；当你需要说服别人，想让对方受到启发或者采纳你的观点做出行动时，你就可以使用故事力养成四步法，从你的故事库提取和讲出合适的故事，让对方听进去、感兴趣、去行动。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>一位朋友二胎后长胖几十斤，她情绪低落了很久，后来经过调整饮食习惯和运动习惯，成功瘦身，恢复身材。她想把自己的减脂经验分享给更多的产后妈妈，就跟我咨询该怎么分享。我用故事力养成四步法帮她梳理了自己的故事，她是这样做的。以下以第一人称口吻叙述。\u003c/p>\u003cp>\u003cstrong>1. 记录我的故事。\u003c/strong>\u003c/p>\u003cp>我怀二胎前只有110多斤，生完后150多斤，腹直肌分离为四指，肚子大、腿粗、骨盆前倾、圆肩驼背，整个人的气质都变了。而且，身材走样，让我很没有自信，我已经很久都不敢见以前熟悉的朋友了。后来，经过半年多的饮食习惯和运动习惯调整（具体的饮食习惯和运动习惯另有记录），我成功瘦回了孕前体重，而且身形比孕前还好，体力也好了很多。朋友看到我，都非常惊讶，还向我咨询怎么调节饮食和安排运动计划呢。\u003c/p>\u003cp>\u003cstrong>2. 标记故事类型。\u003c/strong>\u003c/p>\u003cp>我给这个故事划分了三个标签，成功减脂、产后瘦身、合理饮食。\u003c/p>\u003cp>\u003cstrong>3. 辨析分享场合。\u003c/strong>\u003c/p>\u003cp>当有同样受身材困扰的产后女性、肥胖人士提出疑问时，我就可以分享我的减脂故事。\u003c/p>\u003cp>\u003cstrong>4. 讲出我的故事。\u003c/strong>\u003c/p>\u003cp>见到几年没见的朋友，夸赞我气色好，身材好，问我生二胎后是不是带孩子累瘦的。\u003c/p>\u003cp>我说，完全不是，你看我现在的样子能想象生完三个月后，我还有150多斤吗？肚子格外突出，像怀孕六七个月，圆肩驼背，脸比现在大两圈。我是怎么瘦下来的呢？我从孩子五个月大的时候，下定决心减脂。学了营养学知识，每天三餐给自己按比例搭配饭菜，每天有氧运动、力量训练，半年就瘦下来了。这个方法特别好，真的是“七分吃，三分练”。吃对了，很容易减脂，你要是想试试，我可以给你一些调理饮食的建议。\u003c/p>\u003cp>朋友立刻说：你快跟我说说吧，快到夏天了，我也想减减脂，瘦一点好看。\u003c/p>\u003cp>大家听了这位朋友的故事，是不是也想问问怎么吃就会瘦啊？\u003c/p>","interaction":"\u003cp>回到我们今天的主题，接下来，我们进入下一环节：学习者拆为己用。\u003c/p>\u003cp>\u003cstrong>【A学习者拆为己用】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2编剧本】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>今天的拆为己用是请每位小伙伴独立编写一个小剧本，需要设计人物、情节变化（包括：起因、经过 、结果）和当时双方的对话、动作等。\u003c/p>\u003cp>故事背景和人物设计，可以是你未来有可能遇到的场景。记得用上我们今天分享的“故事力养成四步法”哦，将可以使你产生联想的关键词句写在我给大家的剧本框架表里，不需要写长篇大论。时间5分钟，5分钟后我会邀请一位小伙伴来分享他设计的故事。\u003c/p>\u003cp>需要注意的是，我们今天初次接触故事力养成四步法，所以第一步中，你的故事库可能并不详细完备，没关系，你可以从记忆中提取一个过往经历。今后，随着你用心的记录，你的故事库会越来越丰富，可提取的点也越来越多。\u003c/p>\u003cp>时间差不多了，我看王颖同学一直在写，请你来分享一下你的剧本吧。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>非常感谢王颖同学的分享。我们今天写小剧本的时间还是比较紧张，但是我们可以听出来，她对于和女儿的对话是提前进行了一番构思的。她思考了女儿面对的问题，自己读书的经验，提取出了故事点并且运用一定的逻辑框架分享给了女儿，也成功引起了女儿的好奇和追问。\u003c/p>\u003cp>建议王颖同学今天课后能进一步完善剧本内容，然后提高自己实际中和女儿对话、成功建议女儿使用“翻书”APP，帮女儿解决问题。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>“\u003cstrong>用故事述说人生，用故事影响他人\u003c/strong>”，积累你的故事，标记故事类型，辨析分享场合，讲出你的故事，故事力养成四步法，助你成就精彩人生。\u003c/p>\u003cp>感谢大家来参加我3-1的过级，我们下次再见。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1683271212000,"updated_at":1684481238000,"ria":true},{"id":15660,"topic":"用故事讲出你的价值观","learn_goal":"","remark":"经典书","level":"TF2-3","duration":35,"status":30,"type":0,"chaishujia":{"username":"程林","city":"湖州市"},"club":{"name":"湖州吴越分舵","city":"湖州"},"prologue":"\u003cp>大家好我叫木木，我是一名不爱讲课的的培训师，我在过去2年，一直在某非营利组织帮助伙伴磨课打比赛，以赛代练助力他们成长，去年我辅导的选手成功拿到全国赛冠军，我不爱讲课，但是我爱给其他伙伴磨课\u003c/p>\u003cp>今天木木不磨课哈，我讲课，木木先简单给大家介绍一下本次课程来源的书《故事力》\u003c/p>\u003cp>作者高琳我们用故事思维去看待世界、与世界沟通的能力，也是帮助我们决胜于未来的一种重要思维能力。它体现了人类的高度智慧，是凝聚了情商，沟通力，领导力、战略性思维等的综合能力。人工智能时代，这种能力在职场和生活中的重要性已经越来越被人们高度重视和认可。和其他讲故事力书不一样的是，这本书有六种不同场景下的故事模型，让你学完就能模仿，在技能下落地，而今天的拆书课程主要是用于大家展示自己的价值观，能从干巴巴的词语中走出来，用故事让大家认识你信任你最后按照你说的去做，从而增加自己的影响力。\u003c/p>\u003cp>接下来我们用2分钟的时间来阅读一下原文，稍后木木会带大家一起来学习一下。看完的伙伴可以在聊天框扣666告诉我\u003c/p>\u003cp>木木看到很多伙伴都可以看完了，那开始我们今天的学习之旅吧~\u003c/p>\u003cp>在开始之前，我们可以来看一个实际的案例：\u003c/p>\u003cp>背景是：一群伙伴参加了拆书帮十周年回来进行复盘\u003c/p>","ratings_count":1,"texts":[{"id":19723,"quote":"\u003cp>片段来源于《故事力》-用故事讲出你的价值观\u003c/p>\u003cp>很多人对面试有一个误解，总觉得面试就是面试官或用人单位对候选人的考核。其实，面试应该是一个双向选择的过程，也是候选人对于自己和公司文化是否契合的判断过程。一份好的职业，一定是你的能力和岗位需求互相呼应，你的价值观和公司愿景互相匹配的结果。所以对你来说，了解公司文化和用人标准也是一次选择的过程。\u003c/p>\u003cp>那么，当你知道了面试公司的价值观，怎么证明你就是那个与其“三观”相符的人呢？总不能说“因为华为是一家以客户为中心的公司，我也是吧”？所以要怎么证明呢？\u003c/p>\u003cp>首先，价值观跟免疫系统一样，平时没什么用，你也不会特别清晰地知道自己到底有什么价值观。它只有在关键时候，尤其是面对选择的时候才起作用。比如：找对象，谁都想要一个长得美，身材好，贤惠又能干的女朋友，但是要让你在以上几样中选择一样的时候就难了。找工作也是一样，谁都想要钱多事儿少离家近的工作，可如果必须选一样，我们就纠结了。\u003c/p>\u003cp>其次，当什么事儿是自然而然的，根本就不需要做什么特殊的努力时，就谈不上什么价值观或者动力了。比如吃饭，谁都得吃，你说你每天都选择吃饭，这就是废话，但是如果你说你在减肥，讲你如何忍着饥饿不吃饭，这就成了一个价值观故事了。因为你面临了一个艰难的选择。\u003c/p>\u003cp>基于以上两点，你就知道故事要怎么讲了，首先，这个故事里一定要有选择上的冲突；其次，你一定需要做一些特殊的努力，那才可以凸显你的价值观。还记得我们讲过无冲突，不故事吗？冲突越强，你想要体现的价值观也就越强。\u003c/p>\u003cp>所以你在讲你的价值观故事的时候就可以套用这样的一个模型：因为×××（价值观）对我很重要，即使×××（面临什么困难/冲突），我还是选择×××（做了什么）。\u003c/p>\u003cp>比如，假设我去面试的一家企业最注重的价值观是“诚信”，那我就会讲一个自己当年真实面对的涉及“诚信”的经历。如果套用这个模型，那就是：因为诚信对我很重要，即使面临的问题难以解决，我还是选择了通过正当渠道沟通而不是不择手段。当然，这样讲只能算是个“骨架”，还不算是一个故事，如果把“肉”加上去，那么这个故事就可以这么讲。\u003c/p>\u003cp>我在之前公司的时候，有一次因为一个历史遗留问题，公司有可能被罚款几百万，但在公司看来这样的处罚是缺乏足够依据的。当时我被老板派去解决这个问题，看能不能不罚款或者少罚一些。那时候，我和团队几乎每周都要一大早坐上高铁去和当地相关部门沟通，交涉了很久，但问题都像皮球一样被踢来踢去，大家都很绝望。其中有一个下属就提出，要不然给经手的人点好处，把这事儿打点了得了。\u003c/p>\u003cp>我当时就对他说：“我理解你的心情，我也很烦，天天到处求人。但是老板曾经跟我说过这么一句话：‘如果明天报纸的头版头条登的就是你做的这件事，你觉得可以登吗？如果可以，你就去做，如果不可以就不要做。’ 所以，你好好想想，刚才你那建议能达到这样一个标准吗？”那个下属说“肯定不能”，我说：“那不就完了，咱继续想办法解决吧。”最后我们通过各种沟通，反复游说，找相关证据，总算是把问题完美解决了。\u003c/p>","explains":"\u003cp>木木看到很多伙伴都可以看完了，那开始我们今天的学习之旅吧~\u003c/p>\u003cp>在开始之前，我们可以来看一个实际的案例：\u003c/p>\u003cp>背景是：一群伙伴参加了拆书帮十周年回来进行复盘\u003c/p>\u003cp>看完大家是否有这样的疑惑，明明两个人想要达到的结果是一致的，为什么最后聊天不欢而散，甚至有些不愉悦。\u003c/p>\u003cp>在个人被信任从而让他人按照你的安排走的路径的过程其实是这样的 \u003c/p>\u003cp>认识-记住-认可-信任-选择\u003c/p>\u003cp>所以在展示自己我是谁-也是就有关个人选择以及体现自我价值观想要被信任，我们用对方式特别的重要—亚里士多德说：我们无法通过智力去影响别人，情感却能做到这一点，用好的个人故事去讲述自己的价值观，从而让她人信任你到选择你，如果今天想学的话 ，可以在聊天框扣666\u003c/p>\u003cp>想要讲好自己的故事，是不是一定要从故事六要素出发，那答案是不一定，好故事的标准从来都是以真心换真心。\u003c/p>\u003cp>到底怎么用故事去展示自己价值观呢 ，我们看一个模型框架\u003c/p>\u003cp>书上的案例：\u003c/p>\u003cp>我在之前公司的时候，有一次因为一个历史遗留问题，公司有可能被罚款几百万，但在公司看来这样的处罚是缺乏足够依据的。当时我被老板派去解决这个问题，看能不能不罚款或者少罚一些。那时候，我和团队几乎每周都要一大早坐上高铁去和当地相关部门沟通，交涉了很久，但问题都像皮球一样被踢来踢去，大家都很绝望。其中有一个下属就提出，要不然给经手的人点好处，把这事儿打点了得了。\u003c/p>\u003cp>我当时就对他说：“我理解你的心情，我也很烦，天天到处求人。但是老板曾经跟我说过这么一句话：‘如果明天报纸的头版头条登的就是你做的这件事，你觉得可以登吗？如果可以，你就去做，如果不可以就不要做。’ 所以，你好好想想，刚才你那建议能达到这样一个标准吗？”那个下属说“肯定不能”，我说：“那不就完了，咱继续想办法解决吧。”最后我们通过各种沟通，反复游说，找相关证据，总算是把问题完美解决了。\u003c/p>\u003cp>这个案例偏于职场，那如果想要应用在我们现实生活中，要怎么使用呢 ，给大家举个例子\u003c/p>\u003cp>我是一名理科生，从小就很不喜欢看书，喜欢逻辑思维，因为这个个人问题，在大学毕业，阴差阳错成为了一名培训师，在我众多的导师中，他们性格不同，年龄不同，爱好不用，但他们都送给了我一句话：要多看书呀 木木。那个时候，我几乎每天都要强迫自己看书，浪费可很多时间，但是并不能完全吸收书中的知识点，后来我就想到了一个办法，我需要什么东西花钱去学就行了，也不一定要看书呢 ，这样一直到我自己成为培训经理，站在百人培训场合被学员一句话问倒，从而被质疑专业性的时候，我惊醒，作为一名培训师，我需要的知识点远远不是培训技能上的提升，培训技能永远是为我知识服务的，后来我制定了每年看书计划并加入了拆书帮进行拆书，让书为我所用。现在的木木每个月保持至少三本书的阅读量，每个月可以开发1-2门课程，也准备努力成为三级拆书家接触更多优秀的人，听完木木的故事之后，那接下来，我们来自己使用，刚刚的案例大家都有印象么 \u003c/p>","interaction":"\u003cp>如果你是小A你要如何用自己的故事去让小B更加有力量成为三级拆书家呢\u003c/p>\u003cp>接下来进行分组环节，我们每组（人），共8分钟\u003c/p>\u003cp>1、选择一个人成为小A,一个人选择成为小B，\u003c/p>\u003cp>2、小A根据自己过去的经历去设计故事，小B思考可能存在的纠结点\u003c/p>\u003cp>3、2分钟时间思考，然后小A小B进行对话，剩下的伙伴进行反馈，可以修改更好的点\u003c/p>\u003cp>回到大厅，是否有小组愿意分享刚刚的对话，可以在聊天区扣666，\u003c/p>\u003cp>接下来总结一下，今天我们学习了用故事展示自己的价值观\u003c/p>\u003cp>最后送大家一句话：不要吝啬你的故事送出你的礼物，这个世界正等着接受它！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1682147978000,"updated_at":1682232696000,"ria":true},{"id":14875,"topic":"一学就会，一会就可以用的故事架构","learn_goal":"","remark":"宣传语：为什么有的人讲话让人昏昏欲睡，有的人讲话让人听了还想听，甚至有人通过短短的三句自我介绍就能引起投资者好奇，进而获取约谈见面机会、顺利获取投资。想知道你们的奥秘吗？ 故事让你讲话引发好奇，散发魅力。","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"万敏","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>开场：\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp> 大家好，我是未来的三级拆书家万敏，很高兴这周末的下午和一群积极爱学习的伙伴一起参加线上拆书活动。按照惯例首先自我介绍一下。\u003c/p>\u003cp>我的三个标签：\u003c/p>\u003cp>会计师认证，其次我有PMP项目管理认证，最后我是一名演讲爱好者，可以为大家提供财务管理、项目管理和演讲技巧方面的专业知识。 \u003c/p>\u003cp>\u003cstrong>【技能点】分组\u003c/strong>\u003cbr> 为了便于待会学习时讨论、分享，我们先分一下组,从我左手边开始，二个小伙伴一个组\u003c/p>\u003cp>\u003cstrong>【技能点】设定学习目\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后,在公众表达（例如面试求职、社交等）场景下，学习者能够区分叙述和故事，并且使用故事三段式（因为-但是-所以），写出一个自我介绍。\u003c/p>\u003cp>\u003cstrong>【图书介绍】【技能点】场景法介绍图书：事件场景-提问-影响-解决\u003c/strong>\u003c/p>\u003cp>【事件场景】：\u003c/p>\u003cp> 刚毕业那儿，参加一家心仪已久的公司面试，HR看完简历说：先自我介绍一下吧。\u003c/p>\u003cp> 我：你好，我叫万敏，来自xxx学校xxx专业，在校期间获得xx奖项。暑假期间在xx上市公司实习三个月，提前适应工作节奏。我的兴趣爱好也很广泛：羽毛球、跑步、手工艺品等。很希望成为贵公司一员。\u003c/p>\u003cp>【提问】：现场的小伙伴们是否有遇到类似的职场面试的自我介绍、项目进度汇报、年中工作汇报、产品宣讲、创业公司融资路演等场景中，是否和我一样简单的讲述自己的一些属性后，空气突然变得很安静。不知道该如何有意识的组织语言以获得对方认同或者影响他人呢？\u003cbr> 【影响】：那次面试自然没通过。\u003c/p>\u003cp>【解决】：当你不知道该如何让自己更有说服力或影响力时，看到了《故事力》这本书，它运用大量实例阐述讲故事的重要性，以及讲好故事的3大标准和6大要素，并总结出6个人人都需要的故事模型，落实到8大职场应用场景，用故事力帮你决胜人生关键时刻。创造不平凡的全新自己。\u003c/p>","ratings_count":2,"texts":[{"id":18889,"quote":"\u003cp>今天的拆页来自于这本书中的p5-6页，现在让我们花2分钟时间一起欣赏原文片段\u003c/p>\u003cp>R 原文片段\u003c/p>\u003cp>\u003cstrong>【技能点】【R】所选拆页，不包括how内容（致用类图书）\u003c/strong>\u003c/p>\u003cp>R 原文片段\u003c/p>\u003cp>我们每个人都喜欢听故事，因为我们就生活在无数的故事里面。人类通过故事去理解世界，解释事物的运作。从小到大，我们学习很多生存之道、人生哲理时都是通过故事来理解的。比如，当你两三岁的时候，父母告诉你不要玩火，他们一定不会说：玩火啊，玩火会导致三度烧伤。”因为这是事实，事实需要经验和知识的加持，才能被理解。但是如果父母说：“你别玩火啊，一会儿别把咱们家房子都烧了，再把你烧了，特别疼的！”你是不是就会马上停手？其实你爸妈就是编了一个故事让不懂事的你理解玩火的坏处。\u003c/p>\u003cp>故事之所以有那么大的冲击力，是因为我们无论有什么背景，都熟悉故事，都会很自然地用故事去解释一个不容易理解都情况。比如你突然听到办公室里啊个同事大声囔囔，你脑子里就会开始编一个故事解释：为什么会这样呢？他俩有什么矛盾啊？我们都习惯用故事看待这个世界。\u003c/p>\u003cp>叙述，是按照逻辑顺序罗列事实，告诉你发生了什么。故事则帮助我们解释事情为什么发生，这个事件告诉我们一个什么道理，并且把这个因果和听者紧密联系起来。\u003c/p>\u003cp>叙述靠的是走脑，要有理有据。故事靠的是走心，需要情感和联想、想象的能力。\u003c/p>","explains":"\u003cp>\u003cstrong>【技能点】\u003c/strong>\u003c/p>\u003cp>我看大家都看完了原文片段，下面我来和大家分享一下我对这个拆页的解读。\u003c/p>\u003cp>what\u003c/p>\u003cp> 这个拆页主要告诉什么是叙述，什么是故事以及它们的区别。\u003c/p>\u003cp>Why\u003c/p>\u003cp>为什么要讲故事？有的创业者路演能引起投资者好奇，进而获取约谈见面机会、顺利获取投资？有的第一轮开口就无疾而终例如我刚才的自我介绍？为什么东方甄选直播带货，让人听的上头，甚至有人想报新东方课程的冲动等等。那是因为他们的演说中加入了故事；故事比简历、名片更吸引人，比事实更让人记住，更有说服力和影响力。例如我们小时候学的孔融让梨、司马光砸缸等等。\u003c/p>\u003cp>讲解概念\u003c/p>\u003cp>其实大部分伙伴是生活和工作中是叙述事情而非讲故事。既然说到讲故事，\u003c/p>\u003cp>首先需要了解什么是叙述什么是故事？\u003c/p>\u003cp>叙述，是按照逻辑顺序罗列事实，告诉你发生了什么，靠的是走脑，要有理有据。\u003c/p>\u003cp>故事，通过\u003ca href=\"https://baike.baidu.com/item/%E5%8F%99%E8%BF%B0?fromModule=lemma_inlink\">叙述的方式讲一个带有寓意的事件，或是陈述一件往事，容易让人记住，具有传播某一个观点，影响某个特定的受众群体。靠的是走心，需要情感和联想、想象的能力。\u003c/p>\u003cp>我们一起看看下面几个例子，大家判断是叙述还是故事？\u003c/p>\u003cp>互动\u003c/p>\u003cp>拆书家：\u003c/p>\u003cp>A：（反例）\u003c/p>\u003cp>经常看到微课或短视频里晒出高大上的视觉笔记，请问现场的伙伴想不想学？三步教你快速学会视觉笔记？第一步；第二步；第三步。。。\u003c/p>\u003cp>大家觉得我这是叙述还是讲故事？\u003c/p>\u003cp>\u003cstrong>学习者答：叙述（做什么，怎么做）\u003c/strong>\u003c/p>\u003cp>B：\u003c/p>\u003cp>（反例）\u003c/p>\u003cp>职场中，公司要求做年终总结汇报。一般情况下，大家这样汇报\u003c/p>\u003cp>转瞬间，即将迎来2023年，回顾2022年，收获颇多，感悟也颇深。现将2022年个人工作进行总结，具体情况如下：\u003c/p>\u003cp>1、工作总体完成情况xxx\u003c/p>\u003cp>2、具体工作开展情况xxx\u003c/p>\u003cp>3、总结和展望\u003c/p>\u003cp>大家觉得这是叙述还是讲故事？\u003c/p>\u003cp>\u003cstrong>学习者答：叙述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家反馈：叙述（罗列事实）\u003c/strong>\u003c/p>\u003cp>C（反例子）：\u003c/p>\u003cp>信息安全与我们生活日益密切相关，今年315信息安全实验室对此展开了专门的测试，测试人员发现，连接时点击过的“确认”和“打开”字样的弹窗，都是伪装的广告链接。一旦用户被诱导点击，没有任何提示，广告链接中的应用程序就会自动安装到手机里。最终，用户想要的免费WiFi没用上，手机里却多了一堆莫名其妙的应用程序。同时这些免费wifi还在后台大量收集用户信息。\u003c/p>\u003cp>大家觉得这是叙述还是讲故事？\u003c/p>\u003cp>\u003cstrong>学习者答：叙述\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家反馈：叙述（掌握信息证据）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>D（正例）\u003c/strong>\u003c/p>\u003cp>一位全职妈妈创业找融资的时候给著名投资人徐小平发了一条短信：\u003c/p>\u003cp>第一句：我是北大毕业的\u003c/p>\u003cp>第二句：现在在开淘宝店，淘宝店的销售额已经3000万了\u003c/p>\u003cp>第三句：但是我陷入了迷茫，您是一位心灵导师，您能不能开导开导我？\u003c/p>\u003cp>大家觉得这位创业妈妈是在叙述还是讲故事？\u003c/p>\u003cp>\u003cstrong>学习者答：故事\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家反馈：\u003c/strong>\u003c/p>\u003cp>现场的小伙伴们学习能力真棒！经过这4个案例，想必大家现在已经可以清楚出什么叙述什么是故事。叙述靠的是走脑，要有理有据。故事靠的是走心，需要情感和联想、想象的能力。例如刚刚第4个例子全职妈妈融资的故事，是不是立刻引发你的好奇，北大毕业为什么去开淘宝店？淘宝店销售额已经3000万了为什么还迷茫？等等一系列为什么？这就是故事都魅力。\u003c/p>\u003cp>How:\u003c/p>\u003cp>我们从故事的概念和要点可以归纳出故事的核心三段式：开头、中间、结尾\u003c/p>\u003cp>1、开头引发好奇（好奇）\u003c/p>\u003cp>好的开头是成功的一半，故事开头是否引发好奇。可以引发听众追问“为什么”。\u003c/p>\u003cp>2、中间有冲突（冲突）\u003c/p>\u003cp>俗话说无冲突不故事。正反方对决、感受到的负面情绪、其中双方“对话”是彰显冲突的神器。例如2022年世界杯小组赛。阿根廷对战墨西哥，上半场墨西哥队严防死守，阿根廷队毫无机会；下半场第64分钟当阿根廷队梅西进球时，全场欢呼，解说员激动的流下眼泪。随后一球拯救阿根廷，顺利小组出线。上半场和下半场就形成强烈反差、这就是冲突。\u003c/p>\u003cp>3、结尾有升华（走心）\u003c/p>\u003cp>故事结尾部分总结主要观点和中心思想，提出行动建议或号召行动，价值升华，让人记住。\u003c/p>\u003cp>介绍一个简单的故事结构=因为+但是+所以，“但是”就是故事必备的转折、冲突、矛盾。就那全职妈妈创业找融资第时候给著名投资人徐小平来说吧。\u003c/p>\u003cp>（1）、因为\u003c/p>\u003cp>因为xxxx目标/目的（例如：因为我要获得融资，北大毕业现在开淘宝店，销售额已经3000万。）\u003c/p>\u003cp>（2）、但是\u003c/p>\u003cp>在追求目标的过程中遇到了障碍（例如：但是陷入迷茫） \u003c/p>\u003cp>（3）、所以\u003c/p>\u003cp>所有我做了什么/想要做什么去克服这个障碍（例如：所以希望您当我的导师）\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有伙伴肯定会问，讲故事一定要用“因为+但是+所以”，当然不是了。俗话说无冲突不故事，故事还有经典的英雄之旅模型、雪中送炭模型等等。这里用“因为+但是+所以”这3个词，是我们日常生活中使用频率较高的词汇，大家一学就会，一会就可以用的故事结构。熟练运用后，养成故事冲突思维，也可以不用这3个词汇，很自然的加入冲突。例如脱口秀中反转、停顿都可以产生前后反差，形成冲突，快速引发听众好奇。\u003c/p>\u003cp>【匹配自己的案例】\u003c/p>\u003cp> 熟悉我的小伙伴们，都知道我还是头马演讲俱乐部会员，因为在我们的讲演路径中，有一关是需要讲导师对自己对影响；但是我入会以后我的导师来无影无踪江湖人称一阵风；所以那次演讲开场就快速勾起听众的好奇，我的导师是怎么无影无踪有时怎么一阵风的？尽管没有见面但是在参加演讲前她一遍遍的陪我改稿磨稿，鼓励我。导师就像一盏指路明灯，引导你穿越火线，向前奔跑（升华）。\u003c/p>\u003cp>【适用边界】 \u003c/p>\u003cp> 故事这么好，是不是适合所有的场合呢？也有适用边界。它适用于学习故事思维初学者、适用于想引发听众好奇的公众演讲、社交场合、求职面试、创业路演等场景。不适合与表严肃的政治会谈、商务汇报、叙职汇报等场景。\u003c/p>","interaction":"\u003cp>【技能点】【A2】教学习者编剧本。\u003c/p>\u003cp>接下来，请大家用“因为+但是+所以”的故事结构，编一个自我介绍的小剧本在未来的一周或一个月的拆书中介绍自己，字数不限，但是要包括因为但是所以。\u003c/p>\u003cp>例如：一位歌手的自我介绍\u003c/p>\u003cp>每个人都有自己的人生目标，因为我的目标是成为一名歌手。许多人一定认为我天生嗓子好，但是我并非天赋异禀，如果说有十个人想当歌手，我可能会排到第九。所以，为了实现这个梦想，我每天勤学苦练，并从当流浪歌手做起，每天到街头练唱，一唱就是几个小时。我相信，每累计一千小时，我就能向前进一步。现在我已经连续唱了九千多个小时，正朝着一万小时迈进（升华）\u003c/p>\u003cp>。\u003c/p>\u003cp> 模版参考：\u003c/p>\u003cp> 未来的一周或一个月的拆书中介绍自己：\u003c/p>\u003cp> 大家好，我是xxx，因为有一个____目标（引发好奇），\u003c/p>\u003cp> 但是让在追求目标的过程中遇到了____困难（冲突）\u003c/p>\u003cp> 所以我做了____去克服这个困难，我相信____（升华）\u003c/p>\u003cp>现在给大家5分钟的时间来编一个小剧本，之后会请1位伙伴来和我们分享一下\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp> 时间：2022.12.26 \u003c/p>\u003cp> 办公室：大洲、小李\u003c/p>\u003cp> 事件：下周六小李第一次参加拆书活动，希望有个让人印象深刻的自我介绍；知道大洲是讲故事高手，特意来请教大洲\u003c/p>\u003cp> 小李：大洲，好久不见，我最近遇到一个小困惑，大家都知道你是讲故事高手，特来请你来解惑。\u003c/p>\u003cp> 大洲：大家都是同事，你太客气了，可以说出来，看我是否能帮上忙。\u003c/p>\u003cp> 小李：事情是这样的，下周六第一次参加拆书活动，希望有个让人印象深刻的自我介绍；有没有什么模型推荐一下？\u003c/p>\u003cp> 大洲：你来的真巧，最近我学了一个故事模型（因为-但是-所以），简单好用，你看可否？例如：\u003c/p>\u003cp>大家好，我是来自沈阳的大洲，是一名阅读爱好者\u003c/p>\u003cp>因为有\u003cu>希望自己学会十八般武艺，就像xx节目中那样高级读书者那样\u003c/u>（引发好奇）\u003c/p>\u003cp>但是让在追求目标的过程中\u003cu>遇到了阅读障碍，发现很多书看我那后一点印象都没有\u003c/u>（冲突）\u003c/p>\u003cp>所以\u003cu>经朋友介绍，来参加拆书活动，今天参加后知道来对了，我相信只要迈出第一步并且刻意练习一定能成为高级读书者那样\u003c/u>。（升华）\u003c/p>\u003cp> 小李：哇，太棒了，真是简单又好记，下周六我就用因为-但是-所以，来自我介绍。感谢感谢\u003c/p>\u003cp> 大洲：客气客气\u003c/p>\u003cp>拆书家反馈：\u003c/p>\u003cp>感谢大洲的分享，故事结构（因为但是所以）运用得非常好.现在对自我介绍和会议开场是不是让人印象深刻。\u003c/p>\u003cp>结尾：\u003c/p>\u003cp>让我们一起回顾今天学习的讲故事的要点，大家还记得吗？\u003c/p>\u003cp>1、开头引发好奇2、中间有冲突3、结尾要走心\u003c/p>\u003cp>还有一个故事结构（因为+但是+所以）。我今天的拆书到此结束，感谢大家的聆听。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1671452995000,"updated_at":1678803258000,"ria":true},{"id":14758,"topic":"如何提高自己的同理心","learn_goal":"","remark":"学习目标：学会提高自己同理心得三个步骤和方法，达成更好的沟通效果\n内容简介：详细了解提高自己同理心的三个步骤","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"可睿","city":"唐山市"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>【分组】\u003c/p>\u003cp>大家好，在分享开始之前，先分一下组，我们随机\u003cstrong>3\u003c/strong>个人一组，分成两组。\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是许睿。我的三个标签是：6年教培创业者、终身学习者，未来的拆书家。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>我们今天学习的片段选自《故事力》，作者高琳，她从各个角度、深入浅出地帮助读者分析和掌握结构性地搭建、技巧性地讲述故事的能力。这项能力不仅适用于职场，更适用于生活。\u003c/p>","ratings_count":1,"texts":[{"id":18783,"quote":"\u003ch2>【过渡语】\u003c/h2>\u003ch2>请大家阅读选自《故事力》摘录自133-134页（怎样提高自己的同理心），给大家一分钟的时间来阅读：\u003c/h2>\u003cp>【原文拆页】\u003c/p>\u003ch2>那么，要怎样提高自己的同理心呢？\u003c/h2>\u003ch2>1. 放下自己。共情的前提就是能够放下自己，如果你带着属于自己的认知、观点、评判、期待去看待他人，你是不可能达到真正的共情的。只有把自己的脚放进对方的鞋子里，你才能真正体会到他的脚的感受是什么，所以，在达成共情之前，你需要把你的“鞋子”脱下来，才能换他人的“鞋子”。\u003c/h2>\u003ch2>2. 带着尊重的好奇心。不带功利，不带评判，怀着尊重他人的好奇心，能够让你在共情的过程中保持中立与平等的心态，也有助于和他人建立联结。\u003c/h2>\u003ch2>3. 深度倾听。在前面两步的基础上，深度倾听。除了听对方在说什么，更要听对方没说出来的情绪、感受、需求，这是共情的关键。在你进入深度倾听后，你的注意力是完全放在对方身上的，这时候对方完全能够感受到被你关注。\u003c/h2>\u003ch2>4. 核对验证。听到了一些信息之后，要使用恰当的方式表达，联结才能被建立起来。如果不那么确定的时候，可以通过提问的方式来表达，当然，如果没有得到对方的回应或对方否认了，说明你没有共情成功，不要担心，可以继续尝试。\u003c/h2>","explains":"\u003ch2>【What】这个片段讲了提高自己同理心的方法。同理心指的是设身处地站在当事人的角度看问题，将心比心，就像是把你的鞋子脱下，穿上别人的鞋子，设身处地感受当时的问题和感受。\u003c/h2>\u003ch2>\u003c/h2>\u003ch2>【Why】应用同理心能够透过表象，看到当事人真实的情绪以及背后的原因，更得以当事人所在的处境思考问题，能更好的解决问题。相反，如果没有同理心的话，一味地站在自己的角度思考问题，最终很难达成一致的观点。\u003c/h2>\u003ch2>【Where】这适用于所有的沟通场合，比如师生之间的沟通、同事之间的交流，上下级之间的工作交接。带着同理心去看待问题，交流沟通，更能透过问题看本质，获得更好地交流结果\u003c/h2>\u003ch2>【How】\u003c/h2>\u003ch2>第一步，放下自己。放下自己的认知去看待他人，例：老师在和学生沟通时，先放下自己的认知，假如学生某次没完成作业，先不要马上就开始批评。\u003c/h2>\u003ch2>第二步，带着尊重的好奇心。例：尊重孩子的内心，平等着和孩子去沟通，了解情况。\u003c/h2>\u003ch2>第三步， 深度倾听。例：一定要倾听孩子的陈述，孩子可能确实遇到困难了，也可能是其他原因，倾听才能了解真正得原因。\u003c/h2>\u003ch2>第四步，核对验证。了解了一定的信息之后，再寻求解决方案。例：了解了孩子的真实情况后我再针对性的提出解决方案，比如可以延后惩罚或者思想教育等。\u003c/h2>","interaction":"\u003ch2>【故事】\u003c/h2>\u003cp> 我记得第一年做班主任的时候，有一次看晚自习的时候，一个平时爱说话的同学又在违反纪律，我立马展现出班主任的姿态，在班里对她大声训斥：张同学又开始说话了，没想到这个孩子顿时就站起来，顶了一句”老师我咋又说话了，我刚说一句“，后来了解到孩子那天刚好和同学闹矛盾，结果又被我在班里批评，最后孩子受到了学校的处分，但是我这也是班主任工作的一次失败的教训。\u003c/p>\u003ch2> 【反思】\u003c/h2>\u003cp>现在回想起这件事来，还是没有用同理心去处理问题。看到有学生违纪，我第一时间就是拿出班主任的姿态，而没有放下自己，也没有尊重孩子的自尊心，如果我们平心静气地认真倾听孩子的问题，站在她的角度思考，那么这件事我能处理得更好。\u003c/p>\u003ch2>【目标】本周末应用同理心跟张同学做一次心理疏导。\u003c/h2>\u003ch2> 【应用】 张同学是我目前带着的一个学生，孩子现在高三，学业压力比较大，而且现在在家上网课。我打算应用同理心和她做一个深度交流。\u003c/h2>\u003ch2> 首先放下自己，我虽然是他的老师，但更是他的朋友，以朋友聊天的形式沟通交流。\u003c/h2>\u003ch2> “你看最近学校也一直考试，而且还在家上网课，对你有啥影响吗”\u003c/h2>\u003ch2> 然后，带着尊重的好奇心去沟通。“我都挺佩服你的，你看你现在学业任务这么重，你还能有条不紊得坚持不放松”\u003c/h2>\u003ch2> 再次，倾听孩子的真实想法，并且对他的一些想法表示认同\u003c/h2>\u003cp> 最后，在认同他的观点的时候 ，恰当得进行鼓励，指出他的不足，并且给树立小目标。\u003c/p>\u003cp>【激活经验提问设计】\u003c/p>\u003cp>现在请大家想想你过去在职场中或在生活中有没有沟通冲突的场景，比如：在职场中，同事之间的沟通冲突，工作扯皮；生活中父母与孩子的沟通，辅导作业鸡飞狗跳。每个人想一个发生在自己身上的例子，写在便利贴上，在小组内分享，每人一分钟左右的时间，小组分享完后，我们请一位小伙伴来跟大家分享下。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp> 一位小伙伴分享孩子在家上网课，有时候不听话的场景。\u003c/p>\u003cp>【催化应用提问设计】\u003c/p>\u003cp>谢谢这位伙伴为我们分享的案例，那接下来再请伙伴们结合我们刚刚分享的应用同理心与他人沟通的方法，如果未来的1个月你再遇到类似的场景，应用今天学到的同理心沟通的方法做个计划，你会怎么做？我们用1分钟时间把它写在你的便签上。一会儿我们请小伙伴来分享。写便签时请注意：需要有场景、明确时限、可衡量，还要符合方法的步骤。\u003c/p>\u003cp>【学习者应用】\u003c/p>\u003cp> 鲍老师分享和她女儿的沟通，站在女儿的角度考虑问题\u003c/p>\u003cp> 【总结】\u003c/p>\u003cp>小伙伴们，时间到了。由于时间的原因，我们就不分享了，我们简单总结一下本次分享的内容：提升同理心的方法有四步：放下自己、带着自重的好奇心、深度倾听以及核对验证，希望这个方法能够帮助到大家，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1670466657000,"updated_at":1671181379000,"ria":true},{"id":14455,"topic":"因为-但是-所以故事模式","learn_goal":"","remark":"这是一本讲好故事的书","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"三金","city":"湖州市"},"club":{"name":"湖州吴越分舵","city":"湖州"},"prologue":"\u003cp>\u003cstrong>【开场】\u003c/strong>大家好，我是今天的TF2-3练级选手曹鑫，大家也可以叫我三金。我的三个标签：心理社会工作者，疫情下凸显出来的一个重要工种；家庭教育指导师，较多参加社区一些家庭教育讲座，帮助小区里的年轻妈妈更好了解家庭教育的知识；阅读爱好者，目前在湖州拆书帮的拆书路上升级打怪，努力早日成为三级拆书家。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>2分钟\u003c/p>\u003cp>今天我分享的一本书叫《故事力》，拆解其中第一章中关于“因为—但是—所以”故事模式的内容\u003c/p>\u003cp>【F】《故事力》这本书的作者是高琳和林宏博，两位都拥有40多年的世界500强管理和咨询实战经验，同时也拥有工商管理博士的扎实理论基础。为我们展示如何用故事思维无去看待世界、与世界沟通的能力。\u003c/p>\u003cp>【A】这本书的优势在于它是一本实战型书籍，与其他培养领导力、沟通力的书籍相比，作者运用大量实例阐述讲故事的重要性以及讲好故事的3大标准和6大要素，总结出6个常用故事模型，让读者带着故事力去决胜人生关键时刻。\u003c/p>\u003cp>【B】你有没有面试不知如何介绍自己、推荐项目不知如何打动人心的时候？那么《故事力》这个书会给你一个全新的方向，让你通过讲好故事的方法获得更多的影响力。很多时候我们有能力去做好某项工作，但因为缺乏一个具体的故事打动他人导致自己不能拿到理想的工作或者项目，那么今天跟我一起学习一下其中一个关于“”故事模式，也许你可以得到不少启发。\u003c/p>\u003cp>\u003cstrong>【学习目标\u003c/strong>】通过今天的解读和场景演练能够学会用“因为—但是—所以”故事模式介绍自己或者自己的项目来讲好故事。\u003c/p>","ratings_count":1,"texts":[{"id":18469,"quote":"\u003cp>因为人员数量，今天现场我给大家做个简单的分组。然后接下来请大家用2分钟时间看一下我给大家的原页片段（看完的小伙伴请举手示意）：\u003c/p>\u003cp>【R】\u003c/p>\u003cp>我先给大家讲一个真实的故事。\u003c/p>\u003cp>曾经一位全职妈妈创业找融资的时候给著名的投资人徐小平发了一条短信。第一句：我是北大毕业的。\u003c/p>\u003cp>第二句：现在在开淘宝店，淘宝店的销售额已经3 000万了。\u003c/p>\u003cp>第三句：但是我陷入了迷茫，您是一位心灵导师，您能不能开导开导我？\u003c/p>\u003cp>结果，徐老师看到这条短信后3分钟就把电话打了过去。当天下午他们就约好见面，谈了4个小时后，徐小平就打算投资她了。这位全职妈妈就是电商平台蜜芽的创始人刘楠。经过五轮融资，现在这家公司已经有了100亿元的估值。所有这些都源于一个三句话的自我介绍，这个介绍就是一个典型的故事。\u003c/p>\u003cp>为什么这么说呢？\u003c/p>\u003cp>你看，如果她的这个短信是这么说的：“徐小平老师你好！我叫刘楠，我从北大毕业，创业销售额达到3 000万了，想要寻求融资，能见见您吗？”你觉得这么说还会有同样的效果吗？估计徐小平老师看一下就删了。\u003c/p>\u003cp>只有“因为”+“所以”就不算一个故事——因为我想融资（目标），所以我想见你（结果），这只能算是一个叙述。那什么是故事呢？在“因为”和“所以”之间加一个“但是”，就变成了故事！这个“但是”就是故事所必备的转折、冲突、矛盾。无冲突，不故事，在这短短的三句话里，就有三个“冲突”。\u003c/p>","explains":"\u003cp>拆书家讲解：看到有学习者已经举手示意看完这个片段了，接下来请允许我用拆书法为大家拆解这个片段的精华，大家仔细听哦，会有意想不到的收获。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>“因为—但是—所以”这个句式的故事模式就是将一个平平无奇的叙述变成有转折、冲突、矛盾情节的故事，引起听者好奇心，让人向更加深入了解你的故事，最后可以使得讲故事的人达到自己的目的。\u003c/p>\u003cp>\u003cstrong>Why：（不这么做的坏处）\u003c/strong>不会讲故事的人往往平铺直叙一个事实，听故事的人可以说每天接触许许多多的案例，凭什么要对你的事实进行记忆和重点关注呢？所以平淡无奇的讲述基本也就让人听过即忘。（\u003cstrong>这么做的好处\u003c/strong>）但是一个跌宕起伏的故事会更加引人入胜，为什么简单的加一个“但是”就能达到出其不意的目的呢？因为人们往往被那种意想不到的情节所以吸引，大家好奇啊，讲的故事没有按照常理进行，那么是会向那个结局演变呢？所以“但是”引起“好奇”，最后形成听下去的欲望。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>那么怎么讲好一个“因为—但是—所以”模式的故事呢？\u003c/p>\u003cp>\u003cstrong>第一步：交代特定背景。\u003c/strong>就如同一般叙事将时间地点人物等做一个背景说明，简单明了说明自己接下来要说的故事前提特定的身份。如同原文案例，表明“我是北大毕业的”，而不是我来自XX地区，我是XX店老板等等，这个背景必须要和下文的故事能形成冲突。\u003c/p>\u003cp>\u003cstrong>第二步：制造多次转折。\u003c/strong>利用“但是”转折情节来制作冲突引发对方的好奇心，原文介绍的北大毕业生很多，那么来访者遇到什么问题了呢？原来啊她北大毕业后做了淘宝（即电商），大家知道知名高校毕业做起了电商，这就是一个小小的转折，后来她又表明她的销售额已经达到了3000万，wow，这个北大毕业的电商果然不同凡响啊，销售额如此之高，引发听着好奇，她是怎么做到的呢？这就是第二个冲突。最后来访者又表明她陷入了迷茫，创业销售额都已经达到3000万了，怎么又迷茫了呢？第三个矛盾制造完成。想想如果你是听故事的人，是不是很想知道她的故事呢？\u003c/p>\u003cp>\u003cstrong>第三步：表达最终目的。\u003c/strong>最后自然揪着听故事人的好奇心表明自己的目的，希望得到帮助或者达成某些协议。\u003c/p>\u003cp>\u003cstrong>（意译）：\u003c/strong>可能大家不会有去咨询融资的经历，对原文的故事模式不能很好理解，我来举个自己的例子，方便大家更深一步理解。\u003c/p>\u003cp>比如我将要去成立一个公益性社会组织，希望得到民政局相关领导的关注和支持，简化我的成立步骤并缩短审批时间。因为民政局也在大力提倡乡镇发展社会公益组织，但为啥要单独给我简化程序呢？可就需要我的一点点故事力了。那我按照以上故事模式讲这样去打动民政局的领导：\u003c/p>\u003cp>第一句：我是XX乡镇一名中级社工，目前正在运行我们乡镇的社工站工作。第二句：我们社工站由我一个人在运维，相关活动上报的时候常常受到局里领导的点赞，提炼的经验也在多个平台推广。\u003c/p>\u003cp>第三句：但是现在中心要求成立枢纽型社会组织来承接社工站的工作，一是方便社工站市场化运维，二是对辖区其他社会组织进行专业化统一管理。我们乡镇鉴于以往的工作经历建议我来成立这个枢纽型社会组织，方便继续运维社工站。希望民政社会事务科的领导给与支持，帮助我快速成立这个社会组织。\u003c/p>\u003cp>\u003cstrong>详细说明步骤背后的逻辑：1.简单交代接下来我要得到支持内的所需要的身份背景。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.一个人运维整个社工站这个工作量是非常大的，很好奇你是怎么做到的。这是第一个冲突；而且运维成效非常好，更加期待了解你的运维经验了，这是第二个冲突。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.中心要求成立形成第三个转折，同时说明为何一定要我去成立这个组织制造更大的冲突。如此引发工作人员给我开绿通的好奇心。\u003c/strong>\u003c/p>\u003cp>结果是民政社会事务发展科听了我的介绍，向中心了解我的工作情况然后很好奇我是如何开展社工站的工作，很期待我接来下的表现。这样最后跟我确认了这个社会组织法人是我之后给我开了一个绿通。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>“因为—但是—所以”模式讲故事运用非常广泛，基本的聊天都可以运用，尤其在你面试、争取项目的时候运用更为有效。但是如果时间有限就需要高度概括你的故事咯。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>我们讲自己的故事要基于事实，不能无辜捏造细节。这里的故事力“因为+但是+所以”模式是基于我们有一个目的在其中，而且我的目的也能对对方带来益处，而不是讲童话或者神话故事只是简单引起别人的兴趣。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3场景设计】\u003c/strong>说到这里，不知道大家学习了多少故事力？接下来我会给在场的学习者一个场景，我们现场演练一下，学会的可以加深印象，还没完全学会的可以在演练中继续学。\u003c/p>\u003cp>场景：下周“我”要去找一个社区谈一个读书分享项目，作为湖州拆书帮会员，想用RIA便签学习法以工作坊的形式来讲一些“如何做好组织管理”的方法论。那么“我”该如何用好“因为+但是+所以”故事模式吸引社区的工作人员来了解我的工作坊内容呢？\u003c/p>\u003cp>“因为+但是+所以”模式：\u003cstrong>第一步：交代特定背景、第二步：制造多次转折、第三步：表达最终目的。\u003c/strong>\u003c/p>\u003cp>我们试一试怎么用？\u003c/p>\u003cp>\u003cstrong>（小组演练）\u003c/strong>现在请大家在组内分配角色，相互演练一下，一位扮演前去谈项目的拆书帮会员，一位扮演社区工作人员，最后请扮演社区工作人员进行本次听故事后的反馈。扮演社区工作人员不需要太多的问句，因为我们这次演练主要锻炼讲故事人的故事力。\u003c/p>\u003cp>\u003cstrong>（学习者分享）张静、可可\u003c/strong>\u003c/p>\u003cp>张静：\u003c/p>\u003cp>\u003cstrong>第一步：交代我的特定身份。\u003c/strong>\u003c/p>\u003cp>第一句：我是一名独立运营社会组织的社工。\u003c/p>\u003cp>\u003cstrong>第二步：利用RIA便签学习法与别的读书法不同之处制造冲突。\u003c/strong>\u003c/p>\u003cp>第二句：目前我在湖州运用拆书学习法给很多企业及社区开展关于组织管理、学习力培养的课程，收到很多好评的反馈，不少社区还邀请我再去开办更多讲座；而且我的工作坊也收到湖州相关专家的好评和指导，落地性很强。\u003c/p>\u003cp>\u003cstrong>第三步：加入“但是”形成最大矛盾，说明自己的目的。\u003c/strong>\u003c/p>\u003cp>第三句：我现在准备把这个学习方法和形式带到长兴的社区组织中，但是需要一个社区作为“带头兵”，请陈皇社区给与支持，提供场地并帮助招募学员。\u003c/p>\u003cp>社区工作人员反馈：\u003c/p>\u003cp> 听到上面这位小伙伴的介绍，我作为社区工作人员很想知道什么叫拆书学习法，她是怎么做到独立运营还把讲座开得这么好的，非常好奇很想尝试一下。而且找我做第一个试点社区，我也很期待开办下来的反馈如何。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1667192826000,"updated_at":1667194403000,"ria":true},{"id":14437,"topic":"向上管理","learn_goal":"","remark":"平时工作兢兢业业，一到工作汇报就卡壳，说话磕磕巴巴，语无伦次，措施晋升机会。故事里SCR模型教你如何突破，向上管理，决胜职场关键时刻。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"万敏","city":"武汉市"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003ch1>\u003cstrong>【自我介绍】\u003c/strong>\u003c/h1>\u003cp>大家好，我是新手拆书家万敏，很高兴今晚和大家一起参加线上拆书活动。按照惯例首先自我介绍一下。\u003c/p>\u003cp>我的三个标签：\u003c/p>\u003cp>1、PMP项目管理认证，有多年参与大型集团项目的经验，可以为大家提供项目管理方面的专业知识。\u003c/p>\u003cp>2、我名字拼音的简称（wanmin)wm，也可以译为完美。这个可能和我财务专业有关，考取会计师证。众所周知会计对数据是非常严谨和追求完美。可以为大家提供财务方面的专业知识。\u003c/p>\u003cp>3、演讲爱好者。参与拆书帮之前，还是一家头马演讲俱乐部前主席，可以为大家提供演讲方面的技能。\u003c/p>\u003ch1>\u003cstrong>【拆书帮介绍】\u003c/strong>\u003c/h1>\u003cp>今天有很多新老朋友，按照惯例我还是简单介绍一下什么是拆书帮？\u003c/p>\u003cp>拆书帮是一个非盈利的学习交流平台。以拆书帮分舵的形式展示在各个城市。它将全国各地爱学习的伙伴们荟聚在一起共同精进，裹挟成长。非常有幸能成为其中一员。\u003c/p>\u003cp>既然叫拆书帮，当然少不了拆书。什么是拆书？\u003c/p>\u003cp>拆书是一项成人学习方法论，类似于费曼学习法、洋葱阅读法等。但又有不同。拆书的目标是将知识拆为己用，助力成长。分为个人学习拆书法和组织学习拆书法。其中个人学习拆书法的经典工具RIA便签法，R—阅读原文；I—用自己的语言重述原文，要求表达清晰、准确且有具体操作步骤。\u003c/p>\u003cp>A—包含A1和A2；A1：激活自己旧知；A2：确定目标和行动。\u003c/p>\u003cp>教是最好的学，组织学习拆书法就是一本书拆为自用后，分享和传授给一群人，助力一群人成长，类似培训师、教练角色。\u003c/p>\u003cp>欢迎来到今天的拆书现场。\u003c/p>","ratings_count":1,"texts":[{"id":18451,"quote":"\u003ch1>\u003cstrong>【过渡语】\u003c/strong>\u003c/h1>\u003cp>请大家阅读我为大家准备的原书片段，这个片段选自高琳【美】林宏博著《故事力》中P180-P181。大家有2分钟时间阅读原文，阅读完毕后，可以在聊天框内call1或开麦示意我。让我们一起阅读吧。\u003c/p>\u003ch1>\u003cstrong>【R阅读原文拆页】\u003c/strong>\u003c/h1>\u003cp>主题【页码】\u003c/p>\u003cp>咨询公司常用的故事模型SCR\u003c/p>\u003cp>《故事力》 高琳【美】林宏博著 P180-P181\u003c/p>\u003cp>那么，怎么讲汇报时的故事才能让老饭既看到你的能力，又看到你的潜力呢？你需要根据的你的汇报对象和想在汇报中实现的目的，选用合适的故事模型。 在这里我们给大家介绍--个最简单的架构，也是咨询公司常用的架构--SCR 模型。 \u003c/p>\u003cp>S(situation)代表背最信息，C(cormplieation）代表沖突挑战，R （resolution）代表\u003c/p>\u003cp>解决方案\u003c/p>\u003cp>S（背景信息）\u003c/p>\u003cp>即简单地说这件事的背景信息，讲达问题出现之前的情况。大多数情况下，这会是一个你想要强调的正面且有价值的信息，比如团队想要实现的目标，准备上线的项目。在正常情况下，实现这样的目标应该是没问题的。\u003c/p>\u003cp>C（冲突挑战 ）\u003c/p>\u003cp>即有些意外情况导致目标的实现出现了困难，这个困难可能是人为的，比如由于沟通不足，你的下属惹怒了供应商，或者突然杀出一个竞争对手；也可能是非人为的，比如天气不好导致物流瘫痪或是经济动荡等\u003c/p>\u003cp>R(解决方案）\u003c/p>\u003cp>即这个困难是怎么解决的，或者可以使用哪些解决方案。如果对方不知道这些困难是什么造成的，那么你可以给出一些解释，这就是我们说的 故事背景。然后针对这些原因分析，你做的工作是怎么解改他的问题的，解决后得到了什么，这就是工作汇报类的故事。如果是工作提案或销售方案类的故事，那就是你打算怎么解决，才能实现一个完美结局。\u003c/p>","explains":"\u003ch1>\u003cstrong>【I重述知识点】\u003c/strong>\u003c/h1>\u003cp>\u003cstrong>[why]\u003c/strong>\u003c/p>\u003cp>平时工作兢兢业业，业务精湛，一遇到周汇报、月汇报、年终汇报和竞职汇报时，大脑紧张的一片空白，说话磕磕巴巴，语无伦次。错失职场关键时刻的竞迁机会。SCR模型教你如何突破，向上管理，决胜关键时刻。\u003c/p>\u003cp>\u003cstrong>[what]\u003c/strong>\u003c/p>\u003cp>什么是SCR模型？\u003c/p>\u003cp>S（situation）背景信息：陈叙事实。例如：参与一个大型项目，那么背景信息有项目背景、参与人员、项目周期、项目流程管理、项目目标等。\u003c/p>\u003cp>C(cormplieation）困难：遇到的难题和已知的风险。例如：团队成员的冲突、不配合；客户需求不断变更，项目遇到延期风险。\u003c/p>\u003cp>R（resolution）解决方案。遇到项目延期风险，是如何应付和具体解决的步骤。\u003c/p>\u003cp>\u003cstrong>[how]\u003c/strong>\u003c/p>\u003cp> SCR模型让你工作汇报脱颖而出，让你被大家看见。如何使用这个模型？\u003c/p>\u003cp>1、背景介绍：\u003c/p>\u003cp>如果是10分钟汇报，可以用1分30秒时间来简单的介绍汇报项目的背景，包括人员配备、客户的质量和时间要求、物资采购等。\u003c/p>\u003cp>2、冲突：\u003c/p>\u003cp>讲述项目中遇到哪些困难，这些难点会导致什么结果。例如：参加大型信息化项目建设，到达项目现场后，发现和外部供应商业务没有沟通，xxx集成没有实现，导致项目的核心功能无法如期交付。\u003c/p>\u003cp>3、解决方案：\u003c/p>\u003cp>为确保项目保质保量如期完工，采取以下三步骤：\u003c/p>\u003cp>①梳理业务逻辑、排列问题清单\u003c/p>\u003cp>②评估问题风险、分析主要风险\u003c/p>\u003cp>③积极和供应商沟通，确认业务方案，达成共赢\u003c/p>\u003cp>\u003cstrong>[Where]\u003c/strong>\u003c/p>\u003cp>SCR模型这么好，是不是适合所有场景呢？当然不是。\u003c/p>\u003cp>如果你的上级是直接型人格或以结果为导向的急性子，则不适合使用该模型。可以采用金字塔模型。\u003c/p>","interaction":"\u003ch1>\u003cstrong>【A1联系具体经验】\u003c/strong>\u003c/h1>\u003cp>记得有一次，部门组织产品演讲技能提升活动，作为年终考核的一项指标。要求每位业务人员学习研究公司的一款软件产品，然后以ppt的形式在30分钟内向现场的5位评委介绍该产品功能。\u003c/p>\u003cp> 加点加班研究软件产品和制作ppt，万事俱备只欠开讲。刚讲的前3分钟，评委们偶尔提出几个问题，继续往后讲，对面人的神情越来越凝重，ppt讲到一半时，对面人鸦雀无声有的频频摇头有的开始刷手机，主评委直接说：今天你的介绍，我们已经了解了，有请下一位演讲者。\u003c/p>\u003cp> 郁闷的我坐在后排听下一位的产品介绍，同时在想：是领导们心情不好，我正好撞到枪口，为什么我的发言被打断？对比下一位演讲者，她观点突出，结构清晰，语言流畅。采用总分总结构，开场对整个产品进行概述，接着讲述该产品的亮点功能，使用范围，然后用3分钟时间介绍其他辅助功能，最后用一句简短的对产品进行高浓度总结。台下的评委们听听的频频点评，我在后排听的也是全神贯注，意犹未尽。\u003c/p>\u003cp>事后对比反思：对业务的理解不比另外一位同事少，主要是语言表达苍白无力，毫无逻辑和亮点，导致那次产品介绍失败告终。\u003c/p>\u003ch1>\u003cstrong>【A2具体应用】\u003c/strong>\u003c/h1>\u003cp>一、目标：\u003c/p>\u003cp>用SCR模型向经理汇报项目进度情况，让上级看自己的能力和潜力。\u003c/p>\u003cp>二、计划：\u003c/p>\u003cp>目前参加一个大型项目的用户测试，计划2022年9月9日早会向项目经理汇报用户测试情况。\u003c/p>\u003cp>三、具体行动步骤：\u003c/p>\u003cp>1、背景介绍：\u003c/p>\u003cp>XXX系统项目用户测试，用户参与人数20人，研发线参与人员10人；原计划8月29日~9月9日完成。项目9月15日正式上线。\u003c/p>\u003cp>2、冲突：\u003c/p>\u003cp>截止到9月2日用户提出的问题，均在问题提出日解决完成。3号用户邀请第三方咨询公司参与测试，对系统项目提出100+多个优化建议，其中部分优化建议超出原需求范围，极大可能会影响产品上线时间。\u003c/p>\u003cp>3、解决方案：\u003c/p>\u003cp>为确保产品顺利上线，将采用以下方案：\u003c/p>\u003cp>首先，认真分析咨询公司提出的100+优化建议并进行分类；分为合理建议、待讨论建议、不合理建议、超出本期业务范围四类。\u003c/p>\u003cp>其次，列出讨论清单，约咨询公司人员面对面方式逐一讨论每个优化建议，明确建议内容，去除不合理的建议。\u003c/p>\u003cp> 最后，讨论建议内容，力争达成一致：9月9日前完成可优化部分，10月30日前完成达成一致对建议内容，剩余优化建议作为明年的业务调研范围。\u003c/p>\u003ch1>三、\u003cstrong>【结束语】\u003c/strong>\u003c/h1>\u003cp>以上是我的三张便签，最后一起回顾一下《故事力》中SCR故事模型S是背景介绍，C是冲突，R是解决方案。适应于职场汇报、向上管理、产品介绍等场景，不适用于向以结果为导向的急性子领导汇报。\u003c/p>\u003cp>谢谢大家聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1667039352000,"updated_at":1668483007000,"ria":true},{"id":12566,"topic":"用STAR模型，打动面试官","learn_goal":"","remark":"你是否曾经在面试中被问到：\n过去工作中最大的挑战是什么？\n你觉得为什么自己适合这份工作？\n面对面试官棘手的问题，如何回答才会让他们感受到你的实力和真诚？","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"张蕾Emma","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>开场：（1.5分钟）\u003c/strong>\u003cbr> 大家好，我是Emma,爱就马上行动。首先用三个标签来介绍自己：\u003cbr> 1.资深外贸从业者 2.演讲辩论教练 3.一个不断折腾的人。\u003c/p>\u003cp>今天进行的是我TF2-2 的拆书过级。\u003c/p>\u003cp>今天的拆书主题是：使用STAR模型，搞定面试官。\u003cbr> 本次预计时长在15-20分钟。\u003cbr> \u003cstrong>学习目标：\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够在面试场合，使用STAR模型，更加清晰条理展示自己的能力。\u003c/p>\u003cp>\u003cstrong>分组：\u003c/strong>为了方便讨论，我们分成2组，前面4位一组，后面4位一组。\u003c/p>\u003cp>\u003cstrong>FAB介绍图书：（2分钟）\u003c/strong>\u003c/p>\u003cp>F:《故事力》的作者是高琳，林宏博夫妻搭档，两位作者都拥有世界500强的管理咨询实战经验以及工商管理博士的理论技术，为很多大型企业的管理人员提供培训。这本书可以帮助大家用故事思维来决胜人生关键时刻。\u003c/p>\u003cp>A: 这本书是应用类书籍，杨澜，潘石屹，张德芬等名人联袂推荐。本书运用了大量的实例来阐述讲故事的重要性。同时总结出6个人人都需要的故事模型，落实到8大职场应用场景。是一本可以马上在生活中时间的书籍。\u003c/p>\u003cp>B1：你是否感觉讲了很多道理，却没有办法说服老板？开了很多会议，却没有激励起团队的积极性？这本书将通过不同的应用场景，给出不同的故事模型，让你提升你的故事力，用故事去说服，影响更多的人。\u003c/p>\u003cp>B2：你是否曾经在面试中被问到：过去工作中最大的挑战是什么？你觉得自己最有优势的能力是什么？你觉得为什么自己适合这份工作？这些问题都可以用到我们今天的拆页，用STAR模型，来打动面试官。\u003c/p>","ratings_count":1,"texts":[{"id":16486,"quote":"\u003cp>\u003cstrong>R：原文拆页（2分钟）\u003c/strong>\u003c/p>\u003cp>面试官的法宝STAR模型，知己知彼才能胜出\u003c/p>\u003cp>HR在面试的时候，常用这样一个工具——STAR模型。他们套用这个模型，通过对候选人过去行为的判断，来预测他将来在新的岗位上的表现。\u003c/p>\u003cp>S：代表情境（situation）。要求求职者描述曾经遇到过的一个情境，讲清楚相关的背景信息，以及自己在这个情境中的角色。\u003c/p>\u003cp>T：代表任务（task）。说明在上述情境中承担了一个什么样的任务。\u003c/p>\u003cp>A：代表行动（action）。说明针对这样的情境和任务，你采取了什么样的行为。\u003c/p>\u003cp>R：代表结果（result）。说明所采取的行为取得了什么结果。\u003c/p>\u003cp>你看出来了吗？STAR模型不就是一个完美的故事模型吗？“情境”和你当时的“任务”，其实就是一个故事的背景和冲突，情境有多复杂多困难，任务有多艰巨，冲突的墙就有多高。你解决这个问题的“行动”，体现的就是你的能力。事件最后的“结果”可以是你的成就，也可以是你的学习成长。\u003c/p>","explains":"\u003cp>I 拆书家讲解（4分钟）\u003cbr>\u003cstrong>What:\u003c/strong> 这个拆页为我们介绍了面试时可以用到的STAR模型。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>我们每个人都会经历面试场合。在面试时我们需要向面试官来证明我们的能力。\u003cbr> 有人会告诉面试官，我擅长团队合作，领导力很强。可是面试官听了之后可能会问，怎么证明你的能力？有人会跟面试官介绍很多自己成功的案例，展示自己职场里所向披靡，这样面试官会想可能是你之前的工作难度太低，或者你避重就轻，没有展示自己失败的案例？\u003cbr> 这个STAR模型一方面可以让大家讲出具体的故事，比空洞的口号有说服力。另外，这个模型下的故事可以让对方感觉到面对挑战，你付出了什么努力，取得了什么结果。从而认可你的能力。\u003cbr> \u003c/p>\u003cp>具体怎么做呢？\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003cbr> 第一步：S 代表场景Situation，为了让对方明白这个故事，我们需要讲明白事情的背景，时间地点人物，故事的起因。\u003cbr> 第二步：T代表任务task. 在刚才的情景之下，我需要完成什么任务。这个时候的任务肯定是有难度，有挑战的。\u003cbr> 第三步：A代表行动action，那面对这种困难和挑战，我做了哪些事情和努力？\u003cbr> 第四步：R代表结果（result）,经过了我的努力之后，我达到了什么结果。这个结果也就彰显了我的能力。\u003cbr> where：STAR模型在大家面试的时候都可以用到，无论是面试某一个岗位，还是争取某一个项目，只要是需要展示个人能力的时候，都可以使用这个模型。所以这个面试官是非常宽泛的，可能是你的领导，合作伙伴。\u003cbr> \u003cbr>上个月，朋友介绍有有一家女性社群想要找演讲力培训教练，结果对方就比较挑剔的问，我们之前的演讲教练可都是青岛交通广播的主持人。你们能让我们的学员愿意上台演讲吗？当时我就用到了这个方法。\u003c/p>\u003cp>S：今年暑假，我们带了一批初中生，做他们的演讲辩论教练。\u003cbr> T:家长希望孩子们能够勇敢上台表达。但是叛逆期的孩子们心里是有抵触和害怕上台发言的。\u003cbr> A:我们通过在课堂上创造良好的氛围，让孩子们感受到安全的环境，设计他们感兴趣的主题，同时教给他们一些实际可操作的方法。\u003cbr> R：课程上，孩子们参与度非常高。在几次课程之后，孩子们在舞台上呈现了一场很棒的演讲，很多家长看到孩子的成长，特别开心。\u003cbr> \u003c/p>\u003cp>\u003cstrong>预防异议：\u003c/strong>有些小伙伴可能说面试的时候那么紧张，哪里想得出来适合的故事？其实大家在进行一场面试之前，肯定是要了解这个岗位的职责要求的。那么针对职责要求，大家需要提前准备一些自己过去经历的故事，这样才能有备无患。\u003cbr> 而且有的故事，是可以展示多种能力的，比如在资金困难的情况下，你带领团队完成了一个项目，不仅可以体现你统筹安排，成本控制的能力，同时也能代表你团队协作，具备领导力的能力。\u003cbr> 所以只要大家提前做好准备，是完全可以做到有备无患的。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2 催化学习者应用\u003c/strong> \u003c/p>\u003cp>\u003cstrong>分步催化1(3分钟)\u003c/strong>：在接下来的一个月里，如果你计划跳槽到一家新的公司？或者公司内部竞聘新岗位？或者说服老板让你负责一个新项目？想要跟其他人谈合作？你的工作中会设计到哪种场景呢？\u003cbr> 请大家思考一下，小组讨论一下2分钟，我们会每组请一位小伙伴来分享一下自己想到的场景。 \u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cbr>小喆，教育培训行业从事者。最近计划拓展其他内容的培训项目，需要展示自己的能力，促成新项目的合作。\u003cbr>曹沛，预计在接下来一个月，需要向领导汇报一下某个项目自己做出的努力，是领导认识到自己的能力。\u003cbr> \u003cbr>\u003cstrong>分步催化2(5分钟)\u003c/strong>：接下来请大家思考一下，在未来遇到这种具体的场景时，如何使用四个步骤，应用STAR模型，去展示你的能力。\u003cbr> \u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>曹沛分享\u003cbr>S: 最近公司有比较大的一个项目在运行，而曹沛作为电力公司总部的员工，属于支持团队。\u003cbr>T: 曹沛需要为这个项目选择合适的技术支持方案。但是这个技术方案牵涉到多家公司，每个公司擅长的方面不同。很难取舍。\u003cbr>A:曹沛需要一方面利用自己的人脉，跟一些技术专家沟通，另一方面需要整合多种资源，比较每个公司的优势和劣势。\u003cbr>R: 通过他的努力，项目组对于总部提供的技术支持方案非常满意。\u003cbr>\u003cbr>相信通过STAR的模型去给领导表达这件事情，可以让领导意识到曹沛的工作能力，从而争取更多的工作机会。\u003cbr>\u003cbr>\u003cstrong>总结：\u003c/strong>\u003cbr>谢谢大家的分享，感谢大家的参与，希望大家在今后的场景中，可以使用STAR模型，展示大家的工作能力，从而搞定“面试官”。\u003cbr>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1635312727000,"updated_at":1635605085000,"ria":true},{"id":11466,"topic":"好的开头是成功的一半","learn_goal":"","remark":"故事力是用故事思维去看待世界,与世界沟通的能力,也是帮助我们决胜于未来的一种重要思维能力.","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"徐丹丹","city":"海口市"},"club":{"name":"海口花梨分舵","city":"海口"},"prologue":"\u003cp> 小伙伴们大家好，我是徐丹丹，很高兴跟大家相聚在我的1－2过级现场，首先请大家以邻近的两人为一组自行分一下组，分好了吗？那咱们今天就这样俩俩一组来一起学习。\u003c/p>\u003cp> 今天我带来的书是一本教大家如何把故事讲好，讲出个人影响力的技术型书籍——《故事力》，这本书是由高琳和林宏博共同打造，杨澜、潘石屹、张德芬等人联袂推荐的，书中介绍了许多讲好故事的标准、要素、技巧以及不同场合角色如何去讲好自己所需的故事，书的内容非常丰富也很实用，今天我们就先一起来看看其中的一项技能:怎样讲好开头故事，以引起听众的好奇和共鸣，从而愿意听我们讲下去。（下面请大家看一下手上的原文拆页，看完的举手示意一下。）\u003c/p>","ratings_count":4,"texts":[{"id":15392,"quote":"\u003cp> 好的开头，是成功的一半选自《故事力》作者：高琳[美]林宏博 P56－57\u003c/p>\u003cp> 你有没有收到过这样的礼物？没有什么包装，甚至盒子敞着口就被送上来了。盒子里面就算装的是老佛爷的夜明珠，估计你的兴趣也会大打折扣。一个故事如果没有好的开头，和这个敞口的盒子就是一样的。一个好的开头，就是一个精美的包装，让人忍不住想要把盒子打开，看看里面的礼物到底是什么。\u003c/p>\u003cp> 那么，什么样的故事开头，才是一个好的开头呢？想象一下，你走进一个完全陌生的场合，台下坐着一两百个你完全不熟悉的听众，你第一句话要说什么，才会让他们对你接下来要讲的东西产生兴趣呢？这就得靠我们之前提到过的两个元素——好奇和共鸣。\u003c/p>\u003cp>那些“从前有座山”的开头之所以让人索然无味，是因为它是按照时间顺序来开场的。对讲的人来说这么讲很顺，因为事情就是这么发生的，可其实，要讲出有趣的故事，你得灵活一点。比如刚才说到有共鸣的开头，你可以从“冲突”开始讲，然后再回去补背景。比如：“我记得我去年工作也特别不顺利，要资源没资源，要涨工资差点被炒鱿鱼…… ”\u003c/p>\u003cp> 那什么是一个令人好奇的开头呢？你也可以把故事的完美结局先抛出来：“你知道吗，一年之内，我从快被炒鱿鱼到升职接替了我老板，你猜发生了什么？”这样听众一下子屁股就从椅子上起来了，希望你赶紧说下文。\u003c/p>\u003cp> 你还可以从故事中最强烈的一个情绪开始，比如：“你知道那一刻我的心情吗？老板说他要把我开除，我充满恐惧…… ”还有一招，是我做演讲的一个绝招，那就是：“我永远不会忘记我的第一次……”不管是第一次的什么经历，都会引起对方“八卦”的兴趣。\u003c/p>\u003cp>一旦你跟听者之间建立了共鸣，把对方的好奇心调动起来，就像输液的时候一针扎进了血管，后面打什么“药”，他都能听得进去了。 \u003cbr> （大家都看得差不多了，下面我们一起来分解这个拆页内容。）\u003c/p>","explains":"\u003cp> 我们怎样能让听众对我们接下来要讲的内容产生兴趣呢，拆页中介绍了三种方法：第一个是从“冲突”入手来开始我们的故事讲述，可能很多人都会说觉得自己根本没啥冲突，总不能为了讲故事而故意制造冲突吧？到底什么是冲突呢？咱们回忆一下最近有没有感受到负面的情绪？如伤心、害怕、担心、着急、失望、生气等。是什么点燃了这些情绪？点燃这些情绪的事情就是冲突，当我们的期望跟实际发生产生差距时，这些冲突就会浮现出来。例如说去年我放弃了之前发展得很好的事业来到海口，期望开启幸福新生活，可现实却不如我愿……大家可能就会想，发生了什么事情呢？面对冲突时，我们可能会感到沮丧、愤怒、失望、焦虑，悲伤、恐惧、紧张、不知所措等等，如果能够挑起强烈的情绪，那就是 “以强烈的情绪开头”，通俗也叫煽情，当我们以强烈的情绪感染了听众，听众就会随着我们的故事情绪起伏，被我们所吸引。第三种就是以结局的方式开头，先把故事的完美结局抛出来，让大家对你的故事充满了好奇心，例如前个星期我孩子跟我说抠门的老师请她们全班喝奶茶，我马上好奇是为什么呢，就想听她说下去。开好故事头能够让沟通事半功倍，当你想要让别人接受你的价值观，想吸引别人对你讲述的内容感兴趣，从而对其产生影响，想让别人追随你、认可你的时候的时候，那就请开始讲述你的故事吧。\u003c/p>","interaction":"\u003cp> A1（激活经验）：拆书家提问设计（逐字稿）：现在我们来回忆一下我们过去有没有什么场合需要讲故事的？你是怎么开头的呢？三分钟时间，请在小组里两人互相分享一下。（学员组里分享，巡视）好的，我大概听了一下，大家分享得都很精彩，谁愿意上台来给我们做个分享？\u003c/p>\u003cp> （学习者分享）\u003c/p>\u003cp> 学习者案例记录：我想给大家讲我家小朋友的事：我家小朋友三岁多，特别喜欢火箭，从一岁多接触乐高课开始他就对图形有了认知，积木对他帮助很大，对身边的物品会很感兴趣。今早说要跟一起造火箭，然后就让我找橡皮筋、牙签，他制造火箭的过程让我很欣慰……\u003c/p>\u003cp> A2（催化应用）：拆书家提问设计（逐字稿）：今天我们学习了讲好故事开头的三种方式：以“冲突”开头、以“强烈的情绪”开头、以“结局”开头，接下来的日子我们可以怎样把它运用到平时的工作、学习和生活中需要讲故事的情境中呢？请大家思考讨论，然后记在便签上。\u003c/p>\u003cp> 学习者案例记录：我接下来想向我的师姐表达我对馆里前台工作的意见，我会以把结局先说出来这样来表达：师姐，我觉得小林不适合我们馆里的前台工作，理由有以下几点……我认为这样说，师姐会更清晰的知道我所表达的意思，从而接受我的建议。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":15393,"quote":"\u003cp>好的开头，是成功的一半选自《故事力》作者：高琳[美]林宏博 P56－57你有没有收到过这样的礼物？没有什么包装，甚至盒子敞着口就被送上来了。盒子里面就算装的是老佛爷的夜明珠，估计你的兴趣也会大打折扣。一个故事如果没有好的开头，和这个敞口的盒子就是一样的。一个好的开头，就是一个精美的包装，让人忍不住想要把盒子打开，看看里面的礼物到底是什么。\u003c/p>\u003cp>那么，什么样的故事开头，才是一个好的开头呢？想象一下，你走进一个完全陌生的场合，台下坐着一两百个你完全不熟悉的听众，你第一句话要说什么，才会让他们对你接下来要讲的东西产生兴趣呢？这就得靠我们之前提到过的两个元素——好奇和共鸣。\u003c/p>\u003cp>那些“从前有座山”的开头之所以让人索然无味，是因为它是按照时间顺序来开场的。对讲的人来说这么讲很顺，因为事情就是这么发生的，可其实，要讲出有趣的故事，你得灵活一点。比如刚才说到有共鸣的开头，你可以从“冲突”开始讲，然后再回去补背景。比如：“我记得我去年工作也特别不顺利，要资源没资源，要涨工资差点被炒鱿鱼…… ”\u003c/p>\u003cp>那什么是一个令人好奇的开头呢？你也可以把故事的完美结局先抛出来：“你知道吗，一年之内，我从快被炒鱿鱼到升职接替了我老板，你猜发生了什么？”这样听众一下子屁股就从椅子上起来了，希望你赶紧说下文。\u003c/p>\u003cp>你还可以从故事中最强烈的一个情绪开始，比如：“你知道那一刻我的心情吗？老板说他要把我开除，我充满恐惧…… ”还有一招，是我做演讲的一个绝招，那就是：“我永远不会忘记我的第一次……”不管是第一次的什么经历，都会引起对方“八卦”的兴趣。\u003c/p>\u003cp>一旦你跟听者之间建立了共鸣，把对方的好奇心调动起来，就像输液的时候一针扎进了血管，后面打什么“药”，他都能听得进去了。（大家都看得差不多了，下面我们一起来分解这个拆页内容。）\u003c/p>","explains":null,"interaction":null,"flags":{"r":true,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1619691064000,"updated_at":1619706668000,"ria":true},{"id":10820,"topic":"提高对情绪颗粒度的感知","learn_goal":"","remark":"用故事思维呈现想法，提高与外界的沟通效果。","level":"TF1-2","duration":14,"status":30,"type":0,"chaishujia":{"username":"岳兴彦","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>（分组）在今天的分享中，会有讨论，我们根据现场的人员，分为2组，3人一个组，便于之后的讨论和分享。\u003cbr>（自我介绍）大家好，我是岳兴彦。我的三个标签分别是人力资源/宝妈/学习坚持者。今天分享的主题为“3步提高对情绪颗粒度的感知”。\u003c/p>\u003cp>（图书介绍）今天分享的拆页来自于《故事力》这本书，作者是高琳和林宏博，两位作者拥有多年的世界500强管理和咨询实战经验，“故事力”作为未来6大全新思维能力中的一项，其重要性不言而喻。本书总结出了好故事的3大标准和6大要素，并落实到面试、汇报工作等8个关键应用场景中，每一场景都给出了具体操作步骤，可模仿性强。好的故事一定离不开能引起听众共鸣的情绪调动，今天我们的学习主题就是关于情绪。请小伙伴们用2分钟时间阅读手中的拆页。读完后点头或举手示意我。\u003c/p>","ratings_count":2,"texts":[{"id":14706,"quote":"\u003cp>摘自《故事力》第5章如何提高对情绪颗粒度的感知 P69-70\u003c/p>\u003cp>故事讲得好的人通常情商都比较高，这是因为一个人的情商其实就包括我们识别和驾驭情绪的能力。如果你长期缺乏对自己情绪的感知，则需要通过一定的刻意练习，逐渐提高自己对情绪的感知，从这个角度来讲，学习讲故事也是提高自己情商的一个途径。你可以试试以下几个步骤。\u003c/p>\u003cp>1.接纳情绪的存在\u003c/p>\u003cp> 首先，情绪本身其实没有好坏对错之分，只不过我们为自己的情绪赋予了意义。在这个意义的基础上，我们有了不同的感受。通常所说的负面情绪，从严格意义上来说，应该是负面感受情绪。如同呼吸是正常的生理反应一样，情绪是正常的心理反应，而且情绪有起伏更是常态，你见过哪个正常的心电图是一条直线呢？心电图直了人就不在了！要心如止水不是说自己不能有情绪，而是说要接纳情绪本身以及情绪的起伏，这是实现情绪颗粒度感知更精细化的第一步。\u003c/p>\u003cp>2.探索情绪背后的积极意义\u003c/p>\u003cp> 每种情绪的背后都有对当事人的积极意义，当你承认这一点，就会有意识地去探索自己的情绪。比如，愤怒是在告诉你，自己的边界被侵犯，悲伤想提醒你失去的痛，要好好珍惜拥有，恐惧的时候要关注如何保护自己。情绪其实只是呈现了你的某种模式，一旦模式被打破，情绪也就不会出现了。当自己的情绪来了，你可以像面对一个老朋友一样，跟它打招呼，问问它：“你想提醒我什么呢？”\u003c/p>\u003cp>3.慢下来，充分感受情绪以及情绪带来的信息\u003c/p>\u003cp> 有了前面两步的基础，情绪出现的时候，你就可以停下手边的事情，慢下来，给自己一些独处的时间，感知情绪带来的身体和心理感受，以及情绪所带给你的信息，并据此给自己的情绪命名，你会发现，这时候的命名，就比前面这几步时的命名精准得多。这个时候，你对自己情绪颗粒度的感知就更加精细了。当然，精准地给自己的情绪命名还有个前提，就是需要积累一定的关于情绪描述的词汇。心理学家巴雷特研究发现：“当你能准确地描述当前发生了什么或者你到底经历了什么的时候，你会更容易找到处理这种情绪的解决方案。”\u003c/p>","explains":"\u003cp>\u003cstrong>WHAT：\u003c/strong>这个拆段讲述了提高对情绪颗粒度感知的方法。首先我们来理解什么是“情绪颗粒度”？简单来说，情绪颗粒度就是对情绪的识别和描述。颗粒，有大小之分。颗粒度大，意味着对情绪的描述和感知会稍显笼统；而颗粒度小，就意味着对情绪的感知和感受会更加精细、准确，甚至对很多细微的差异都能感知察觉到，并能表达出来。提高对情绪颗粒度的感知，其本质就是提高对情绪的感知识别，用颗粒度小的词语描述情绪的能力。\u003c/p>\u003cp>\u003cstrong>WHY: \u003c/strong>有研究表明，如果我们在沟通中足够清晰地描述自己的情绪，或者表达出别人的情绪，会提高双方的沟通效果，有助于解决问题。比如，客户提出一些要求，以我们公司现在的实力是无法满足的，这让我感觉“不爽”。如果我们能准确的识别这种“不爽”究竟是自己付出努力后却达不到要求的委屈，或是为客户的无理要求而生气，还是对公司实力不足的失望，或者是哪几种情绪同时存在，那么我们能更快走出负面情绪，面对困难。\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>今天的拆页为我们提供了如何提高对情绪颗粒度感知的具体步骤。\u003c/p>\u003cp>1、接纳情绪\u003c/p>\u003cp>当我们觉察到有情绪时，为了避免批判，我们可以在心里默念一句：“嘿，老朋友，你来啦！”或者说“啊哦，我有情绪了！”来替换“我不该又发脾气！”\u003c/p>\u003cp>2、探索意义\u003c/p>\u003cp> 不管我们产生的情绪是正面的还是负面的，我们都可以探索它背后的积极意义。所谓积极意义，只要能促使我们变得更好的，都算。这时候，问问自己“这个情绪有什么积极意义呢？”或者说“我有什么正面需求？”\u003c/p>\u003cp>3、命名情绪\u003c/p>\u003cp>有情绪时，通常我们的身体和心理会有一些变化，比如走来走去、心跳加快、胸口堵、大脑空白等等，这个时候，请暂停手边的事情，好好体会这种变化，条件允许的话写下来，并根据这些信息归纳成描述情绪的词语。\u003c/p>\u003cp>\u003cstrong>WHERE\u003c/strong>：适用于所有想要提高对情绪颗粒度感知的人。\u003c/p>\u003cp>\u003cstrong>EXAMPLE：\u003c/strong>周一晚上，孩子已经睡觉了，老公才回家，他听到孩子在咳嗽，就对我说：你对孩子的咳嗽要引起重视哟，免得又像上次一样咳成肺炎了。我一听，提高音量说：“你怎么知道我没重视呢？”说完，我意识到我有情绪了（接纳情绪）。我问自己：我的正面需求是什么？我是希望老公知道我已经给孩子喂过药了，而不是无根据的指责（探索意义）。我生气，此时的我，皱着眉头、提高音量，胸口堵了一下。当我停下来体会这些信息和变化后，我用了更小的颗粒度来描述情绪，是委屈（命名情绪）。\u003c/p>\u003cp>然后我就把这个叫做委屈的情绪故事讲给老公听了。最后我们达成共识：不吃药的话那就去推拿调理，平时要多沟通，一起关注孩子。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：接下来，请大家回想一下，在过去的一个月里，我们与别人或自己相处时，因为某些事情导致情绪的变化，我们当时有什么感觉，最后又是怎么处理情绪的。请小组内彼此分享自己的案例，两分钟后请一位代表来和大家分享一下你的案例。\u003c/p>\u003cp>学习者案例记录：吴平：孩子即将上幼儿园，紧张孩子因为年纪太小，即使在幼儿园受到不公平的待遇、遭受欺负等也不会表达，可是她将这个想法告诉老公以后，老公非但没有安慰她，反而说她是瞎操心！老公的做法她感觉心里堵得慌，现在都还没跟老公说话。\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：大家想一想，今天我们学习了用3步提高对情绪颗粒度感知的方法，在未来的一周或一个月内，可能会在什么场景下用上这个方法？现在请每一个小伙伴在便签纸上写下使用这个方法的行动计划，包括明确的时限、具体做法、期望达成的结果，注意，这个结果应该是可以被观察到或者能够量化的。时间1分钟。\u003c/p>\u003cp>学习者案例：事件：下周一叫孩子起床上学，她可能会拖延，半天不动。\u003c/p>\u003cp>具体做法：1、接纳情绪：察觉到我的脾气要上来了，我会自嘲：啊，河东狮吼要来了！\u003c/p>\u003cp> 2、探索意义：我上班快迟到了，所以很着急，希望孩子能快点起床配合着出门。这个过程中，我更希望孩子能学会独立。\u003c/p>\u003cp> 3、命名情绪：焦急。孩子的做法与我的期望不一致，我很焦急，希望他能快点达到我的期望。我会把这个情绪分享给孩子，希望他能理解妈妈为什么脾气暴躁，然后能在闹钟响起的时候，自己起床，早点独立起来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1608473893000,"updated_at":1616248339000,"ria":true}]};